/* 2026.09 证券从业 LC 终极押题 · 6 套（以纯试卷版HTML为源重建，题干更完整；仅供内部学习） */
var PREDICT_202609 = [{"id":"law1","subject":"law","name":"法律法规 · 押题卷一","stats":{"单选":30,"多选":50,"判断":30,"案例":10},"questions":[{"id":"law1-0","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"发行股票后溢价收入是公司的（）。","options":["法定公积金","任意公积金","资本公积金","营业收入"],"answer":"C","explain":"C选项正确，公司以超过股票票面金额的发行价格发行股份所得的溢价款、发行无面额股所得股款未计入注册资本的金额以及国务院财政部门规定列入资本公积金的其他项目，应当列为公司资本公积金。故本题选C选项。"},{"id":"law1-1","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《合伙企业法》，下列关于合伙企业债务承担的说法，错误的是（）。","options":["合伙企业依法被宣告破产的，普通合伙人对合伙企业债务仍应承担无限连带责任","合伙企业不能清偿到期债务的，债权人可以依法向人民法院提出破产清算申请","合伙企业注销后，原普通合伙人对合伙企业存续期间的债务仍应承担无限连带责任","合伙企业不能清偿到期债务的，债权人可以要求有限合伙人清偿"],"answer":"D","explain":"D选项错误，合伙企业不能清偿到期债务的，债权人可以依法向人民法院提出破产清算申请，也可以要求普通合伙人清偿（并非“有限合伙人”）。"},{"id":"law1-2","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《合伙企业法》，下列关于有限合伙企业事务执行的说法，错误的是（）。","options":["有限合伙企业由普通合伙人执行合伙事务","有限合伙企业仅剩有限合伙人的，应当解散","有限合伙人不执行合伙事务，不得对外代表有限合伙企业","有限合伙企业仅剩普通合伙人的，应当解散"],"answer":"D","explain":"有限合伙企业仅剩普通合伙人的，转为普通合伙企业（D选项错误）。故本题选D选项。"},{"id":"law1-3","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《上海证券交易所科创板股票交易特别规定》，关于投资者参与科创板股票交易需满足的适当性条件，下列说法正确的是（）。","options":["机构投资者申请权限开通前20个交易日证券账户及资金账户内的资产日均不低于人民币50万元，或者参与证券交易24个月以上","机构投资者申请权限开通前20个交易日证券账户及资金账户内的资产日均不低于人民币50万元，并且参与证券交易24个月以上","个人投资者申请权限开通前20个交易日证券账户及资金账户内的资产日均不低于人民币50万元（不包括该投资者通过融资融券融入的资金和证券），或者参与证券交易24个月以上","个人投资者申请权限开通前20个交易日证券账户及资金账户内的资产日均不低于人民币50万元（不包括该投资者通过融资融券融入的资金和证券），并且参与证券交易24个月以上"],"answer":"D","explain":"个人投资者申请权限开通前20个交易日证券账户及资金账户内的资产日均不低于人民币50万元（不包括融资融券融入的资金和证券），并且参与证券交易24个月以上（D选项正确）。"},{"id":"law1-4","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《证券法》，下列关于上市公司收购方式的说法，错误的是（）。","options":["收购要约约定的收购期限不得少于30日，并不得超过60日","上市公司发行不同种类股份的，收购人可以针对不同种类股份提出不同的收购条件","在收购要约确定的承诺期限内，收购人不得变更其收购要约","采取协议收购方式的，协议双方可以临时委托证券登记结算机构保管协议转让的股票，并将资金存放于指定的银行"],"answer":"C","explain":"C选项错误，在收购要约确定的承诺期限内，收购人不得撤销其收购要约。收购人需要变更收购要约的，应当及时公告，载明具体变更事项。故本题选C选项。"},{"id":"law1-5","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《证券法》有关规定，证券公司在承销期结束时，将未售出的证券全部退还给发行人的承销方式是（）。","options":["自行销售","代销","余额包销","全额包销"],"answer":"B","explain":"B选项正确，证券代销是指证券公司代发行人发售证券，在承销期结束时，将未售出的证券全部退还给发行人的承销方式。"},{"id":"law1-6","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《证券公司风险处置条例》，相关机构或人员存在以下（）情形的，应禁止参与处置证券公司风险工作。","options":["内部控制存在一定瑕疵","因违规行为受到纪律处分未逾3年","因严重违法行为受到行政处罚已逾3年","涉嫌犯罪正在被立案侦查、起诉"],"answer":"D","explain":"有下列情形之一的机构或者人员，禁止参与处置证券公司风险工作：（1）曾受过刑事处罚或者涉嫌犯罪正在被立案侦查、起诉（D选项正确）；（2）涉嫌严重违法正在被行政管理部门立案稽查或者曾因严重违法行为受到行政处罚未逾3年（B、C选项错误）；（3）仍处于证券市场禁入期；（4）内部控制薄弱、存在重大风险隐患（A选项错误）；（5）与被处置证券公司处置事项有利害关系；（6）国务院证券监督管理机构认定不宜参与处置证券公司风险工作的其他情形。"},{"id":"law1-7","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《证券期货经营机构及其工作人员廉洁从业规定》，下列关于证券期货经营机构工作人员违反廉洁从业规定的说法，错误的是（）。","options":["曾任证券期货经营机构合规风控职务的人员违反廉洁从业规定的，应当从重处理","直接、间接或者唆使、协助他人向监管人员输送利益的，应当从重处理","违反廉洁从业规定，事后及时向中国证券业协会报告，或者积极配合调查的，依法免予从轻处理","曾为公职人员特别是监管人员违反廉洁从业规定的，应当从重处理"],"answer":"C","explain":"C选项错误，证券期货经营机构工作人员违反《廉洁规定》，事后及时向中国证监会（而非中国证券业协会）报告，或者积极配合调查的，依法免于追究责任或者从轻、减轻处理。"},{"id":"law1-8","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《证券期货经营机构及其工作人员廉洁从业规定》《证券经营机构及其工作人员廉洁从业实施细则》，以下关于廉洁从业风险报告的说法，正确的是（）。","options":["证券期货经营机构应于每年4月30日、8月30日前，向中国证监会有关派出机构报送年度廉洁从业管理报告、半年度廉洁从业管理报告","证券期货经营机构及其工作人员发现监管人员存在应当回避的情形而未进行回避、利用职务之便索取或者收受不正当利益等违反廉洁规定行为的，应当在五个工作日内，向中国证监会有关派出机构报告","证券期货经营机构在内部检查中，发现存在违反《证券期货经营机构及其工作人员廉洁从业规定》行为的，且进行内部追责的，应当在十个工作日内，向中国证券业协会报告","证券期货经营机构或者其工作人员因违反廉洁从业相关规定被纪检监察部门、司法机关立案调查或者被采取纪律处分、行政处罚、刑事处罚等措施的，应当在五个工作日内，向中国证券业协会报告"],"answer":"B","explain":"B选项正确，发现监管人员存在应当回避而未回避、利用职务之便索取或者收受不正当利益等违反廉洁规定行为的，应当在5个工作日内向中国证监会有关派出机构报告。"},{"id":"law1-9","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《证券行业诚信准则》，下列选项中，属于证券公司及其工作人员应当遵守的勤勉尽责要求的是（）。","options":["自觉学习了解并遵守相关法律法规、监管规定、自律规则、业务规范和内部规章制度","尊重同行，公平竞争，禁止商业贿赂，自觉维护市场竞争秩序，坚决反对不正当竞争的行为","对自己的专业能力有充分认识，不承诺力不能及或不能如期完成的业务，不推诿应承担的责任","不利用虚假和误导性信息进行宣传，不编造传播虚假和误导性信息"],"answer":"C","explain":"C选项正确，属于勤勉尽责的要求。A选项属于合法合规要求，B选项属于公平竞争要求，D选项属于言行一致要求。"},{"id":"law1-10","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"公司分配当年税后利润时，应当提取利润的10%列入公司法定公积金。公司法定公积金累计额为公司注册资本的（）以上的，可以不再提取。","options":["20%","30%","50%","60%"],"answer":"C","explain":"C选项正确，公司法定公积金累计额为公司注册资本的50%以上的，可以不再提取。"},{"id":"law1-11","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"股份有限公司的发起人不得超过（）。","options":["50人","30人","200人","100人"],"answer":"C","explain":"C选项正确，设立股份有限公司，应当有1人以上200人以下为发起人。"},{"id":"law1-12","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"股票期权经过（）交付权利金后，可以决定是否在约定期间内是否行使权利。","options":["双方","买方","卖方","中间交易方"],"answer":"B","explain":"B选项正确，股票期权买方有权决定在合约规定期间内是否行权。买方支付权利金。"},{"id":"law1-13","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"甲乙丙合伙设立企业，甲乙是普通合伙人，丙是有限合伙人，问（）要符合私募基金管理人的要求监管。","options":["甲和乙","甲","甲乙丙","乙"],"answer":"A","explain":"A选项正确，以合伙企业形式设立的私募基金，资产由普通合伙人管理的，普通合伙人视同私募基金管理人进行规范。"},{"id":"law1-14","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"开放式基金的基金份额在基金存续期间，基金份额持有人（）。","options":["可在任何时间申请赎回","可以在基金合同约定的时间和场所申请赎回","可以在任何场所申请赎回","不得申请赎回"],"answer":"B","explain":"B选项正确，开放式基金的基金份额可以在基金合同约定的时间和场所进行申购或者赎回。"},{"id":"law1-15","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"上市公司年度报告应当在每个会计年度结束之日起（）前披露。","options":["1月31日","3月31日","4月30日","6月30日"],"answer":"C","explain":"C选项正确，在每一会计年度结束之日起4个月内报送并公告年度报告，即次年4月30日前。"},{"id":"law1-16","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"同一投资者最多可以有（）个同名资金账户。","options":["3","2","1","5"],"answer":"D","explain":"D选项正确，同一客户最多开立5个同名资金账户。"},{"id":"law1-17","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"为加强对证券公司客户资产的保护，下列不符合《证券公司监督管理条例》规定的是（）。","options":["证券公司可以将客户的交易结算资金放在指定的商业银行金融机构","为保护客户权益，证券公司的资产应与客户资产相互独立","证券公司可以将客户资产用于向他人提供融资或者担保","在符合一定条件下的情况下，证券公司可以对客户交易结算资金进行单方面的处理"],"answer":"C","explain":"根据《证券公司监督管理条例》第六十一条，证券公司不得以证券经纪客户或者证券资产管理客户的资产向他人提供融资或者担保（C选项符合题意）。"},{"id":"law1-18","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列不属于证券公司代销金融产品应当遵循的原则是（）。","options":["公开","公平","平等","诚实信用"],"answer":"A","explain":"证券公司代销金融产品应遵循平等、自愿、公平、诚实信用和适当性原则。故本题选A选项。"},{"id":"law1-19","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列不属于证券公司风险控制指标的是（）。","options":["净资产","风险覆盖率","资本杠杆率","净资本"],"answer":"A","explain":"风险控制指标包括净资本、风险覆盖率、资本杠杆率、流动性覆盖率、净稳定资金率等，不包括净资产。"},{"id":"law1-20","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列不属于证券公司及相关从业人员从事私募资产管理业务的禁止行为的是（）。","options":["投资决策出现严重失误导致产品净值大幅度回撤","为规避监管的证券期货业务活动提供交易便利","以获取佣金为目的，使用资产管理计划财产进行不必要的交易","间接向投资者返还管理费"],"answer":"A","explain":"A选项属于业务失误，不属于禁止行为。B、C、D均为禁止行为。"},{"id":"law1-21","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列不属于证券自营业务禁止性行为的是（）。","options":["违反规定委托他人代为买卖证券","将自营业务与经纪业务混合操作","将自营账户借给他人使用","通过专用自营席位进行证券交易"],"answer":"D","explain":"D选项属于证券自营业务的具体操作要求，不是禁止行为。"},{"id":"law1-22","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列关于分类监管制度对证券公司正向激励作用的说法，错误的是（）。","options":["提升风险控制能力","培育核心竞争力","便于证券公司广告宣传","加强合规管理"],"answer":"C","explain":"证券公司不得将分类评估结果用于广告、宣传、营销等商业目的。C选项错误。"},{"id":"law1-23","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列属于证券公司全体工作人员应履行的合规管理职责的是（）。","options":["评估合规管理有效性","组织制定公司规章制度，并监督其实施","在业务开展过程中主动识别和防范业务合规风险","建立与合规负责人的直接沟通机制"],"answer":"C","explain":"C选项正确，全体工作人员应主动识别和防范业务合规风险。"},{"id":"law1-24","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"以公司是否有（）可分为国有独资企业、国有控股企业、国有参股企业、非国有公司等。","options":["股东人数和股份流动性","相互之间的组织关系","公司注册地","国有资本及其所占比重"],"answer":"D","explain":"D选项正确，依公司是否有国有资本及其所占比重，可分为国有独资公司、国有控股公司、国有参股公司、非国有公司等。"},{"id":"law1-25","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"有权决定国有独资公司合并分立的是（）。","options":["股东会","董事会","国有资产监督管理机构","监事会"],"answer":"C","explain":"C选项正确，国有独资公司的合并、分立、解散等，应当由履行出资人职责的机构决定。"},{"id":"law1-26","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"有限责任公司的设立方式是（）。","options":["发起设立","募集设立","公开募集","内部募集"],"answer":"A","explain":"A选项正确，发起设立适用于有限责任公司和股份有限公司。"},{"id":"law1-27","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券的发行、交易活动，必须遵循的原则是（）。","options":["公开、平等、公正","公开、公平、平等","开放、公平、公正","公平、公开、公正"],"answer":"D","explain":"D选项正确，证券的发行、交易活动，必须遵循公开、公平、公正“三公”原则。"},{"id":"law1-28","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司持续合规状况的评价依据之一为（）采取的刑事处罚措施。","options":["中国证监会","司法机关","中国证监会及其派出机构","中国人民银行"],"answer":"B","explain":"B选项正确，持续合规状况主要根据司法机关采取的刑事处罚措施等进行评价。"},{"id":"law1-29","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司进行柜台交易，其（）应当通过中国证券业协会组织的专业评价。","options":["柜台交易管理制度和重大事项报告","实施方案和重大事项报告","柜台交易管理制度和实施方案","实施方案和定期报告"],"answer":"C","explain":"C选项正确，柜台交易管理制度和实施方案应当通过中国证券业协会组织的专业评价。"},{"id":"law1-30","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司进行柜台交易，向投资者收取履约保证金的，应当在双方约定的金融机构开立（）存放，不得违约动用。","options":["存款账户","专门账户","产品账户","信用账户"],"answer":"B","explain":"B选项正确，应当在双方约定的金融机构开立专门账户存放。"},{"id":"law1-31","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司无法以合理成本及时获得充足资金，以偿付到期债务、履行其他支付义务和满足正常业务开展的资金需求的风险是（）。","options":["流动性风险","操作风险","声誉风险","信用风险"],"answer":"A","explain":"A选项符合题意，流动性风险的定义。"},{"id":"law1-32","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司向普通投资者销售产品前，应当告知的信息不包括（）。","options":["可能直接导致本金亏损的事项","限制销售对象权利行使期限或者可解除合同期限等全部限制内容","可能直接导致超过原始本金损失的事项","就产品收益提供的确定性判断"],"answer":"D","explain":"D选项符合题意，禁止向投资者就不确定事项提供确定性的判断。"},{"id":"law1-33","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司应当采取有效措施，确保在柜台市场交易的私募产品持有人数量符合相关规定，其中，非公开募集基金的合格投资者累计不得超过（）人。","options":["150","100","300","200"],"answer":"D","explain":"D选项正确，非公开募集基金合格投资者累计不得超过200人。"},{"id":"law1-34","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司应当在全公司推行的风险文化是（）。","options":["积极","保守","激进","稳健"],"answer":"D","explain":"D选项正确，证券公司应当推行稳健的风险文化。"},{"id":"law1-35","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司应当自资产管理计划终止之日起（）个工作日内报告中国证券投资基金业协会。","options":["1","3","4","5"],"answer":"D","explain":"D选项正确，5个工作日内报告。"},{"id":"law1-36","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司证券自营业务投资运作的最高管理机构是（），负责确定具体的资产配置策略、投资事项和投资品种等。","options":["股东会","自营业务部门","董事会","投资决策机构"],"answer":"D","explain":"D选项正确，投资决策机构是自营业务投资运作的最高管理机构。"},{"id":"law1-37","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司中应对违反职责范围内的内部控制要求所导致的风险和损失承担首要责任的是（）。","options":["直接从事业务经营活动的相关人员","董事会","经理层","合规部门"],"answer":"A","explain":"A选项正确，直接从事业务经营活动的相关人员承担首要责任。"},{"id":"law1-38","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券金融公司向证券公司转融通的期限不得超过（）个月。","options":["12","6","3","9"],"answer":"B","explain":"B选项正确，转融通期限不得超过6个月。"},{"id":"law1-39","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"中国证监会对违反《证券公司融资融券业务管理办法》的证券公司可采取的监管措施不包括（）。","options":["撤销业务许可","暂停部分业务","暂停全部业务","追究刑事责任"],"answer":"D","explain":"D选项符合题意，追究刑事责任属于司法措施。"},{"id":"law1-40","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"法律关系由（）要素构成。","options":["法律关系行为","法律关系客体","法律关系主体","法律关系内容"],"answer":"BCD","explain":"法律关系由主体、客体与内容三个要素构成。"},{"id":"law1-41","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《发布证券研究报告暂行规定》，证券公司证券投资咨询机构发布的证券研究报告，应当载明事项有（）。","options":["证券研究报告采用的信息和资料来源","使用证券研究报告的风险提示","证券公司、证券投资咨询机构名称","收费标准和支付方式"],"answer":"ABC","explain":"D选项不属于必须载明事项。"},{"id":"law1-42","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《证券发行与承销管理办法》证券发行与承销信息披露的有关规定，首次公开发行股票的发行人和主承销商应当在发行和承销过程中公开披露信息的具体内容包括（）。","options":["招股意向书刊登首日在发行公告中披露包括发行定价方式、程序、股票配售原则等信息","在发行结果公告中披露获配投资者名称以及每个获配投资者的报价、申购数量等信息","网上申购前披露每位网下投资者的详细报价情况","采用询价方式且存在规定情形之一的，应当在网上申购前发布投资风险特别公告，详细说明定价合理性，提示投资者注意投资风险"],"answer":"ABCD","explain":"A、B、C、D均正确。"},{"id":"law1-43","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《证券法》，证券的发行、交易活动必须遵守法律、行政法规；禁止行为有（）。","options":["欺诈","内幕交易","获取利益","操纵证券市场"],"answer":"ABD","explain":"禁止欺诈、内幕交易和操纵证券市场的行为。C选项获取利益不必然违法。"},{"id":"law1-44","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《证券法》，证券服务机构未勤勉尽责，所制作、出具的文件有虚假记载、误导性陈述或者重大遗漏的，可以采取的措施包括（）。","options":["责令改正","没收业务收入","暂停或者禁止从事证券服务业务","对直接负责的主管人员给予警告，并处以五十万元以上五百万元以下的罚款"],"answer":"ABC","explain":"D选项错误，对直接负责的主管人员罚款是20万以上200万以下。"},{"id":"law1-45","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《证券公司代销金融产品管理规定》，下列做法错误的有（）。","options":["甲证券公司营业部员工张某向投资者宣传某股票型基金稳赚不赔","乙证券公司营业部员工王某与客户约定某基金亏损由王某承担","丙证券公司营业部销售基金赠送大米","丁证券公司营业部员工李某销售戊基金公司的基金后，收取戊基金公司奖励的购物卡"],"answer":"ABCD","explain":"A、B、C、D均属于禁止行为。"},{"id":"law1-46","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《证券公司为期货公司提供中间介绍业务试行办法》，证券公司受期货公司委托从事介绍业务，应当提供的服务有（）。","options":["提供期货交易设施","提供期货行情信息","代期货公司收取期货保证金","协助办理开户手续"],"answer":"ABD","explain":"C选项错误，证券公司不得代收付期货保证金。"},{"id":"law1-47","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《证券公司信用风险管理指引》，下列关于证券公司信用风险管理的说法，正确的有（）。","options":["证券公司相关业务部门是信用风险管理的一线主体","证券公司董事会应承担信用风险管理的监督责任","证券公司应建立有效的信用风险管理组织架构","证券公司应建立健全有效的考核及问责机制"],"answer":"ACD","explain":"B选项错误，监事会承担监督责任。"},{"id":"law1-48","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《证券基金经营机构信息技术管理办法》，下列关于证券公司经营数据和客户信息保护的说法正确的有（）。","options":["证券公司应当记录经营数据和客户信息的使用情况，并持续监督信息技术服务机构等相关方落实保密协议的情况","证券公司发现信息技术服务机构等相关方违规存储或者使用自身经营数据和客户信息的，应当责令其立即改正并销毁已获取的经营数据和客户信息","信息技术服务机构等相关方拒绝配合整改的，证券公司应当立即停止与其合作，并采取措施维护自身及客户的合法权益","证券公司在收集使用客户信息之前，可以不用公开收集、使用的规则和目的，但应当征得客户同意"],"answer":"ABC","explain":"D选项错误，必须公开收集、使用的规则和目的。"},{"id":"law1-49","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《证券基金经营机构信息技术管理办法》，下列关于证券公司委托信息技术服务机构提供产品或服务的说法，正确的有（）。","options":["证券公司可以委托信息技术服务机构提供产品或服务，但其依法应当承担的责任不因委托而免除或减轻","除法律法规及中国证监会另有规定外，可以将重要信息系统的运维、日常安全管理交由信息技术服务机构独立实施","证券公司应当清晰、准确、完整地掌握重要信息系统的技术架构、业务逻辑和操作流程等内容","证券公司应确保重要信息系统运行始终处于自身控制范围"],"answer":"ACD","explain":"B选项错误，不得将重要信息系统的运维、日常安全管理交由信息技术服务机构独立实施。"},{"id":"law1-50","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《证券投资顾问业务暂行规定》，证券公司、证券投资咨询机构向客户提供证券投资顾问服务，应当告知客户的基本信息包括（）。","options":["证券投资顾问不得代客户作出投资决策","证券投资顾问的姓名及其登记编码","证券投资顾问服务的内容和方式","投资决策由客户作出，投资风险与客户共担"],"answer":"ABC","explain":"D选项错误，投资风险由客户承担而非共担。"},{"id":"law1-51","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《中华人民共和国期货和衍生品法》，下列关于期货结算与交割的说法，正确的有（）。","options":["期货交易实行当日无负债结算制度","在期货交易场所规定的时间，期货结算机构应当在当日按照结算价对结算参与人进行结算","交易者在交割过程中违约的，期货结算机构有权对交易者的标准仓单等合约标的物权利凭证进行处置","结算参与人收取的权利金，在期货保证金存管机构专户存放"],"answer":"ABD","explain":"C选项错误，结算参与人有权处置，而非期货结算机构。"},{"id":"law1-52","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据公司经营原则，公司从事经营活动，应当遵守（）。","options":["商业道德","法律","社会公德","行政法规"],"answer":"ABCD","explain":"公司从事经营活动，应当遵守法律法规，遵守社会公德、商业道德。"},{"id":"law1-53","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"公司合并可以采取（）的形式。","options":["完全合并","吸收合并","部分合并","新设合并"],"answer":"BD","explain":"公司合并可以采取吸收合并或者新设合并。"},{"id":"law1-54","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"公司在企业信息系统平台公示的内容包括（）。","options":["出资时间","出资方式","认缴出资","实缴出资"],"answer":"ABCD","explain":"公司应公示股东认缴和实缴出资、出资时间、出资方式等。"},{"id":"law1-55","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"公司章程对（）具有约束力。","options":["公司","股东","董事","高级管理人员"],"answer":"ABCD","explain":"公司章程对公司、股东、董事、监事、高级管理人员具有约束力。"},{"id":"law1-56","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"股份有限公司章程上应当载明的事项有（）。","options":["发起人的名字","股份总数","公司的注册资本","公司经营范围"],"answer":"ABCD","explain":"上述均属于章程应当载明事项。"},{"id":"law1-57","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"关于证券公司风险控制指标标准，下列表述正确的是（）。","options":["风险覆盖率不低于100%","流动性覆盖率不低于100%","净稳定资金率不低于100%","资本杠杆率不低于100%"],"answer":"ABC","explain":"D选项错误，资本杠杆率不得低于8%。"},{"id":"law1-58","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"关于证券公司在销售产品或者提供服务过程中的责任，下列说法正确的有（）。","options":["将适当的产品或者服务销售或者提供给适合的投资者","全面了解投资者情况，深入调查分析产品或者服务信息","勤勉尽责，审慎履职","对违法违规行为承担法律责任"],"answer":"ABCD","explain":"A、B、C、D均正确。"},{"id":"law1-59","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"关于证券金融公司开展转融通业务的证券来源，说法正确的有（）。","options":["证券金融公司通过证券交易所的业务平台融入的证券","证券金融公司直接使用证券公司客户的证券","证券金融公司通过转融通担保证券账户持有的证券","证券金融公司自有证券"],"answer":"AD","explain":"B选项错误，禁止直接使用客户证券；C选项错误，转融通担保证券账户持有的证券不计入自有证券。"},{"id":"law1-60","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"合伙企业的特征是（）。","options":["共同转让","共同出资","共担风险","共享收益"],"answer":"BCD","explain":"合伙企业特征为共同出资、共担风险、共享收益。"},{"id":"law1-61","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"进行融资融券业务时需要用到的账户有（）。","options":["融券专用证券账户","融资专用资金账户","客户信用证券账户","客户信用资金账户"],"answer":"ABCD","explain":"A、B、C、D均需要。"},{"id":"law1-62","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"声誉风险应遵循的原则包括（）。","options":["全程全员原则","预防第一原则","审慎管理原则","快速响应原则"],"answer":"ABCD","explain":"声誉风险管理应遵循全程全员、预防第一、审慎管理、快速响应原则。"},{"id":"law1-63","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列各项中，属于证券市场行业自律规则的有（）。","options":["中国银行业协会制定的自律规则","中国证券业协会制定的自律规则","证券交易所制定的自律规则","中国证券登记结算有限责任公司制定的自律规则"],"answer":"BCD","explain":"A选项中国银行业协会不属于证券市场行业自律组织。"},{"id":"law1-64","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列关于公司的财务会计制度的说法，正确的有（）。","options":["公司违反规定向股东分配利润的，股东应当将违反规定分配的利润退还公司","公司除法定的会计账簿外，不得另立会计账簿","公司持有的本公司股份可分配利润","公司的公积金可用于弥补公司的亏损、扩大公司生产经营或者转为增加公司资本，资本公积金不得用于弥补公司的亏损"],"answer":"AB","explain":"C选项错误，公司持有的本公司股份不得分配利润；D选项错误，资本公积金可以用于弥补亏损。"},{"id":"law1-65","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列关于股份有限公司董事任免的说法，正确的有（）。","options":["董事会中的职工代表由公司职工通过职工代表大会、职工大会或者其他形式民主选举产生","非职工代表董事由股东会选举","董事任期由公司章程规定，但每届任期不得超过6年","董事任期届满，连选可以连任"],"answer":"ABD","explain":"C选项错误，董事每届任期不得超过3年。"},{"id":"law1-66","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列关于基金财产债权债务独立性的说法，正确的有（）。","options":["非因基金财产本身承担的债务，不得对基金财产强制执行","基金财产的债权不得与基金管理人固有财产的债务相抵销","不同基金财产的债权债务，可以相互抵销","基金财产的债权与基金管理人的固有财产严格区分"],"answer":"ABD","explain":"C选项错误，不同基金财产的债权债务不得相互抵销。"},{"id":"law1-67","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列关于欺诈发行证券罪的说法中，正确的有（）。","options":["必须具有数额巨大、后果严重或者其他严重情节才构成犯罪","若单位构成犯罪的，仅对单位判处罚金","欺诈发行的方式包括在发行文件中隐瞒重要事实或者编造重大虚假内容","犯罪主体只能为个人"],"answer":"AC","explain":"B选项错误，对单位判处罚金并追究直接责任人员；D选项错误，主体主要是单位。"},{"id":"law1-68","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列关于证券公司从事私募资产管理业务的投资经理应具备的条件，正确的是（）。","options":["最近三年未被监管机构采取重大行政监管措施","依法取得基金从业资格","具备良好的诚信记录","具有三年以上投资管理、投资研究、投资咨询等相关业务经验"],"answer":"ABCD","explain":"A、B、C、D均为投资经理应具备的条件。"},{"id":"law1-69","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司、证券投资咨询机构或者其他财务顾问机构存在下列（）情形时，不得担任上市公司独立财务顾问。","options":["持有或者通过协议、其他安排与他人共同持有上市公司股份达到2%","上市公司持有或者通过协议、其他安排与他人共同持有财务顾问的股份达到2%","财务顾问的监事在上市公司任职","最近1年财务顾问为上市公司提供过融资服务"],"answer":"CD","explain":"A、B选项错误，比例需达到或超过5%。"},{"id":"law1-70","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司从事私募资产管理业务，其资产管理计划财产的独立性体现在（）。","options":["独立于证券公司的固有财产","独立于托管人的固有财产","独立于托管人托管的其他财产","独立于证券公司管理的其他财产"],"answer":"ABCD","explain":"A、B、C、D均正确。"},{"id":"law1-71","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司防范敏感信息的不当流动和使用，可以在公开侧业务之间或保密侧业务之间采取的措施包括（）。","options":["信息隔离","限制名单","观察名单","跨墙"],"answer":"ABCD","explain":"可采取信息隔离、跨墙、观察名单、限制名单等措施。"},{"id":"law1-72","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司风险控制指标无法达标，严重危害证券市场秩序、损害投资者利益的，中国证监会可以区别情形对其采取的措施有（）。","options":["责令停业整顿","指定其他机构托管、接管","撤销经营证券业务许可","撤销"],"answer":"ABCD","explain":"A、B、C、D均正确。"},{"id":"law1-73","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司进行柜台交易，应当与特定对手方或投资者签订柜台交易合同，合同的方式可以有（）。","options":["书面","电子","口头","电话"],"answer":"AB","explain":"应以书面或电子方式签订，不得口头或电话。"},{"id":"law1-74","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司开展证券经纪业务中，禁止的行为包括（）。","options":["拒绝客户全权委托代理其买卖证券","将客户的资金账户、证券账户提供给他人使用","在经纪业务营销活动中委托不具有受托资格的单位进行客户招揽","对客户买卖证券承诺收益或赔偿"],"answer":"BCD","explain":"A选项属于可以做的行为。"},{"id":"law1-75","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司可以通过（）开展客户招揽与服务活动。","options":["基金公司","公司员工","委托经纪人","委托其它机构"],"answer":"BC","explain":"证券公司可通过公司员工或委托经纪人开展客户招揽。"},{"id":"law1-76","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司每年在规定时间内应报送柜台市场业务年度报告，下列关于报告内容的说法，正确的有（）。","options":["投资者适当性管理","登记结算","风险及合规管理","交易情况"],"answer":"ABCD","explain":"A、B、C、D均属于年度报告内容。"},{"id":"law1-77","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司应当在全公司推行稳健的风险文化，形成与本公司相适应的（）。","options":["风险管理理念","价值准则","监督机制","职业操守"],"answer":"ABCD","explain":"A、B、C、D均正确。"},{"id":"law1-78","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券投资顾问应当遵循诚实信用原则、勤勉、审慎地为客户提供证券投资顾问服务。证券投资顾问不得从事的活动有（）。","options":["以任何方式向客户承诺或保证投资收益","以个人名义向客户收取证券投资顾问服务费用","向他人泄露客户的投资决策计划信息","通过网络等公众媒体作出买入具体证券的投资建议"],"answer":"ABCD","explain":"A、B、C、D均为禁止活动。"},{"id":"law1-79","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"资产管理计划的投资者主要的义务包括（）。","options":["认真阅读并遵守资产管理合同，保证投资资金的来源及用途合法","认真阅读并签署风险揭示书","在持有的资产管理计划份额内承担资产管理计划亏损或者终止的有限责任","取得分配清算后的剩余资产管理计划财产"],"answer":"ABC","explain":"D选项属于投资者权利，非义务。"},{"id":"law1-80","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"按照《证券公司内部控制指引》的要求，证券公司内部控制的组织结构要求设立严密有效的三道业务防线，其中，第二道防线是建立重要一线岗位双人、双职、双责为基础的防线。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。应为第一道防线，而非第二道防线。"},{"id":"law1-81","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"操纵证券、期货市场罪的客观方面包括在自己实际控制的账户之间进行大量证券交易，造成股票价格上升后卖出获利。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"law1-82","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"发行人向不特定对象发行证券的，应当聘请承销团承销，承销团成员由主承销商和参与承销的证券公司组成。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误，法律并未规定所有向不特定对象发行都必须采用承销团。"},{"id":"law1-83","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"反洗钱是指为了预防通过各种方式掩饰、隐瞒毒品犯罪、黑社会性质的组织犯罪、恐怖活动犯罪、走私犯罪、贪污贿赂犯罪、破坏金融管理秩序犯罪、金融诈骗犯罪和其他犯罪所得及其收益的来源和性质的洗钱活动，依照《反洗钱法》等法律法规采取相关措施的行为。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"law1-84","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"非法吸收或者变相吸收公众存款，扰乱金融秩序，对象达到200人以上的，方可予以立案追诉。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误，应为150人以上。"},{"id":"law1-85","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《证券法》，收购人未按照规定履行上市公司收购的公告、发出收购要约义务的，责令改正，给予警告，并处罚款十万元以上三十万元以下。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误，罚款为50万元以上500万元以下。"},{"id":"law1-86","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《证券公司董事、监事、高级管理人员及从业人员管理规则》，总公司从事业务管理工作的其他董事、上海分公司投资顾问、营业厅经理，都属于证券从业人员。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"law1-87","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《证券公司及基金管理公司子公司资产证券化业务管理规定》，资产证券化业务的基础资产应当权属明确，是可以产生独立、可预测的现金流的特定财产，财产权利不得作为基础资产。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误，财产权利可以作为基础资产。"},{"id":"law1-88","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《证券公司治理准则》，证券公司应当向社会公众披露本公司未经审计的年度财务报告及其他信息，并保证披露信息的真实、准确、完整。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误，应披露经审计的年度财务报告。"},{"id":"law1-89","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"根据期货衍生品法，期货交易实行保证金制度，以有价证券作为保证金。可以依法通过质押等具有履约保障功能的方式进行。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"law1-90","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"公开募集基金的基金管理人，由依法设立的公司和合伙企业担任。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误，公开募集基金管理人由基金管理公司或经核准的其他机构担任。"},{"id":"law1-91","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"公司除法定的会计账簿外，可以另立会计账簿。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误，不得另立会计账簿。"},{"id":"law1-92","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"股份有限公司的设立，可以采取发起设立或募集设立的方式。以募集设立方式设立股份有限公司的，发起人认购的股份不得少于公司股份总数的25%。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误，不得少于35%。"},{"id":"law1-93","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"股票发行采用代销方式，代销期限届满，向投资者出售的股票数量未达到拟公开发行股票数量50%的，为发行失败。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误，应为70%。"},{"id":"law1-94","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"股票期权实行当日无负债结算制度。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"law1-95","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"基金销售机构不得采取抽奖、回扣等方式销售基金。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"law1-96","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"科创板首次公开发行股票上市前5个交易日不设涨跌幅限制，上市5个交易日后涨跌幅限制比例为20%。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"law1-97","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"内核部门是风险管控的第一道防线。","options":["正确","错误"],"answer":"B","explain":"本题说法错误，内核部门是第三道防线。"},{"id":"law1-98","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"普通合伙企业中，若合伙协议未约定或约定不明的事项，应按照全体合伙人一人一票、经超过半数合伙人同意的方式表决。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"law1-99","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"普通投资者在信息告知、风险警示、适当性匹配等方面享有特别保护。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"law1-100","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"上市公司在一年内担保金额超过公司资产总额30%的，应当由股东会做出决议，经出席会议的股东半数人数同意通过。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误，应经出席会议的股东所持表决权的2/3以上通过。"},{"id":"law1-101","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"我国证券市场法律法规体系的主要层级包括法律、行政法规、部门规章、规范性文件和行业自律规则。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"law1-102","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"证券从业人员不得为牟取佣金收入，诱使客户进行不必要的证券买卖。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"law1-103","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"证券发行上市保荐业务中，保荐人出具有重大遗漏的保荐书，处罚措施中包括：责令改正，给予警告，没收业务收入，并处以业务收入1倍以上10倍以下罚款。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"law1-104","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司分类监管评级中，D级是正常经营机构中的最低级别。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误，C级是正常经营状态的最低等级。"},{"id":"law1-105","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司开展股票质押式回购业务，资金融出方可以是证券公司，也可以是证券公司管理的公开募集或非公开募集集合资产管理计划、单一资产管理计划。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误，不存在“公开募集集合资管计划”。"},{"id":"law1-106","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司可以根据合同约定，为另类子公司的合规管理、风险控制、人力资源管理、产品销售等方面提供支持和服务。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"law1-107","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司应当建立健全投资者回访制度，为回访提供充分的人力与物质保障，不得委托第三方实施回访。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误，可以委托第三方专业机构实施回访。"},{"id":"law1-108","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司应至少每半年对流动性风险限额进行一次评估，必要时进行调整。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误，应至少每年评估一次。"},{"id":"law1-109","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"证券市场当事人具有不平等地位，在自愿、有偿、诚实信用的原则下进行交易活动。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误，当事人具有平等的法律地位。"},{"id":"law1-110","subject":"law","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】张某在某基金销售公司担任销售部经理，同时又在A证券公司担任证券经纪人。为拓展业务，张某将A证券公司开户二维码转发其基金销售公司六名下属，委托他们协助其招揽A证券公司客户，对开户成功客户张某会长期推荐“黑马”股票，并承诺年化投资收益可以达到10%。假设上述案例所述情形均发生在现行相关法律法规生效时间之后，且不考虑各备选项之间的相关影响，请根据上述背景信息回答以下问题。\n\n【问题】要求1 下列关于A证券公司经纪人张某存在违规行为的说法，错误的是（）。","options":["张某存在“自营或者为他人经营与所任证券公司同类或者存在利益冲突业务”的行为","张某存在“向客户违规承诺收益或者承担损失”的行为","张某存在“泄露因职务便利获取的未公开信息”的行为","张某存在“超出法规规定和证券公司授权的范围从事业务”的行为"],"answer":"C","explain":"C选项错误，题干未提及泄露未公开信息。"},{"id":"law1-111","subject":"law","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】张某在某基金销售公司担任销售部经理，同时又在A证券公司担任证券经纪人。为拓展业务，张某将A证券公司开户二维码转发其基金销售公司六名下属，委托他们协助其招揽A证券公司客户，对开户成功客户张某会长期推荐“黑马”股票，并承诺年化投资收益可以达到10%。假设上述案例所述情形均发生在现行相关法律法规生效时间之后，且不考虑各备选项之间的相关影响，请根据上述背景信息回答以下问题。\n\n【问题】要求2 A证券公司的下列情况中符合《证券经纪人管理暂行规定》的是（）。","options":["A证券公司建立健全证券经纪人管理制度，采取有效措施，对证券经纪人及其执业行为实施集中统一管理","A证券公司应当对证券经纪人进行不少于40个小时的执业前培训，其中法律法规和职业道德的培训时间不少于20个小时","A证券公司负责电话回访的人员从事客户招揽和客户服务活动","A证券公司对证券经纪人所招揽和服务客户的账户进行有效监控，并规定出现异常情况的，记录存档并在3个工作日内查明原因"],"answer":"A","explain":"A选项正确。B应为不少于60小时；C回访人员不得从事客户招揽；D应立即查明原因，无3个工作日规定。"},{"id":"law1-112","subject":"law","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】某公司董事长张某、财务总监王某为使公司上市，组织单位工作人员通过使用自制的银行单据等方式，虚增当期利润总额达50%，并在上市申请文件的定期财务报告和招股说明书中均载入上述内容。该公司上市后，张某和王某继续使用相同手段，连续三年均虚增当期营业收入总额40%以上，并在年报中使用上述虚增经营数据，给公众投资者造成重大损失。请根据上述背景信息回答以下问题。\n\n【问题】要求1 依据张某和王某在上市申请文件和招股说明书中使用虚构财务数据的行为，可能触犯的罪名是（）。","options":["提供虚假证明文件、出具证明文件重大失实罪","欺诈发行证券罪","操纵证券、期货市场罪","非法吸收公众存款罪"],"answer":"B","explain":"B选项正确，构成欺诈发行证券罪。"},{"id":"law1-113","subject":"law","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】某公司董事长张某、财务总监王某为使公司上市，组织单位工作人员通过使用自制的银行单据等方式，虚增当期利润总额达50%，并在上市申请文件的定期财务报告和招股说明书中均载入上述内容。该公司上市后，张某和王某继续使用相同手段，连续三年均虚增当期营业收入总额40%以上，并在年报中使用上述虚增经营数据，给公众投资者造成重大损失。请根据上述背景信息回答以下问题。\n\n【问题】要求2 下列关于张某和王某就虚构上市公司财务数据并在年报中进行披露的行为应承担的法律责任的说法，错误的有（）。","options":["可能触犯违规披露、不披露重要信息罪","可能触犯背信运用受托财产罪","可能触犯提供虚假证明文件、出具证明文件重大失实罪","若王某不配合监管机关调查且伪造证据，应予从重处罚"],"answer":"BC","explain":"B、C选项错误，背信运用受托财产罪主体为金融机构；提供虚假证明文件罪主体为中介组织人员。"},{"id":"law1-114","subject":"law","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】甲证券公司为了扩大公司规模，提高自己在市场上的竞争力，经过董事会同意，拟向中国证监会申请为期货公司提供中间介绍业务的资格。请根据上述背景信息回答以下问题。\n\n【问题】要求1 如果甲证券公司的申请获得了中国证监会的批准，甲可以接受（）的委托从事中间介绍业务。","options":["与甲证券公司长期具有贸易往来的期货公司","甲证券公司全资拥有的期货公司","与甲证券公司属于同一机构控制的期货公司","甲证券公司控股的期货公司"],"answer":"BCD","explain":"证券公司只能接受其全资拥有、控股或同一机构控制的期货公司的委托。"},{"id":"law1-115","subject":"law","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】甲证券公司为了扩大公司规模，提高自己在市场上的竞争力，经过董事会同意，拟向中国证监会申请为期货公司提供中间介绍业务的资格。请根据上述背景信息回答以下问题。\n\n【问题】要求2 甲证券公司受期货公司委托从事介绍业务，不得从事（）。","options":["提供期货行情信息、交易设施","代理客户进行期货交易","代期货公司、客户收付期货保证金","利用证券资金账户为客户存取、划转期货保证金"],"answer":"BCD","explain":"B、C、D均为禁止行为。"},{"id":"law1-116","subject":"law","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】甲证券公司为了扩大公司规模，提高自己在市场上的竞争力，经过董事会同意，拟向中国证监会申请为期货公司提供中间介绍业务的资格。请根据上述背景信息回答以下问题。\n\n【问题】要求3 甲证券公司从事介绍业务，应当与期货公司签订书面委托协议，委托协议应当载明（）。","options":["客户投诉的接待处理方式","介绍业务的范围","报酬支付及相关费用的分担方式","介绍业务对接规则"],"answer":"ABCD","explain":"A、B、C、D均需载明。"},{"id":"law1-117","subject":"law","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】客户王某在甲证券公司某营业部开立有经纪业务账户，因其账户证券交易存在异常被证券公司使用的反洗钱系统预警。甲证券公司营业部的业务人员和合规人员共同分析、识别后，结合客户尽职调查的结果，怀疑客户王某用于进行证券交易的资金与其担任法定代表人的公司违规经营外汇业务相关。甲证券公司立即向中国反洗钱监测分析中心提交了可疑交易报告，同时向其营业部所在地的中国人民银行某中心支行提交了重点可疑交易报告，并将客户的洗钱风险等级调至最高，对客户采取了冻结账户等措施。请根据上述背景信息回答以下问题。\n\n【问题】要求1 下列关于大额交易和可疑交易的表述，说法正确的是（）。","options":["既属于大额交易又属于可疑交易的交易，证券公司应当提交综合报告","证券公司与客户进行金融交易并通过银行账户划转款项的，由银行机构按照规定提交大额交易报告","可疑报告与所涉资金金额或者资产价值大小有关","证券公司在报送可疑交易报告后，应当根据中国证监会的相关规定采取适当的后续风险控制措施"],"answer":"B","explain":"B选项正确。A应分别提交；C可疑报告与金额大小无关；D应根据中国人民银行规定。"},{"id":"law1-118","subject":"law","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】客户王某在甲证券公司某营业部开立有经纪业务账户，因其账户证券交易存在异常被证券公司使用的反洗钱系统预警。甲证券公司营业部的业务人员和合规人员共同分析、识别后，结合客户尽职调查的结果，怀疑客户王某用于进行证券交易的资金与其担任法定代表人的公司违规经营外汇业务相关。甲证券公司立即向中国反洗钱监测分析中心提交了可疑交易报告，同时向其营业部所在地的中国人民银行某中心支行提交了重点可疑交易报告，并将客户的洗钱风险等级调至最高，对客户采取了冻结账户等措施。请根据上述背景信息回答以下问题。\n\n【问题】要求2 存在（）的情形，证券公司应当向中国反洗钱监测分析中心提交可疑交易报告。","options":["明显涉嫌洗钱、恐怖融资等犯罪活动","交易数额巨大","严重危害国家安全","影响社会稳定"],"answer":"ACD","explain":"B选项错误，交易数额巨大是大额交易报告条件。"},{"id":"law1-119","subject":"law","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】客户王某在甲证券公司某营业部开立有经纪业务账户，因其账户证券交易存在异常被证券公司使用的反洗钱系统预警。甲证券公司营业部的业务人员和合规人员共同分析、识别后，结合客户尽职调查的结果，怀疑客户王某用于进行证券交易的资金与其担任法定代表人的公司违规经营外汇业务相关。甲证券公司立即向中国反洗钱监测分析中心提交了可疑交易报告，同时向其营业部所在地的中国人民银行某中心支行提交了重点可疑交易报告，并将客户的洗钱风险等级调至最高，对客户采取了冻结账户等措施。请根据上述背景信息回答以下问题。\n\n【问题】要求3 证券公司应当在向中国反洗钱监测分析中心提交可疑交易报告的同时，以（）向所在地中国人民银行或者其分支机构报告，并配合反洗钱调查。","options":["电子形式或口头形式","口头形式或其他形式","书面形式或其他形式","书面形式或电子形式"],"answer":"D","explain":"D选项正确，以电子形式或书面形式报告。"}]},{"id":"law2","subject":"law","name":"法律法规 · 押题卷二","stats":{"单选":30,"多选":50,"判断":30,"案例":10},"questions":[{"id":"law2-0","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"按照《证券业从业人员执业行为准则》及相关规则的规定，一般证券从业人员应接受协会和所在机构组织的后续职业培训，且每年的培训不少于（）。","options":["20学时","15学时","10学时","5学时"],"answer":"B","explain":"B选项正确，从业人员自首次执业登记日的下一年起，每个自然年为一个培训周期。证券公司应当要求其从业人员在每个培训周期内完成一定时间的业务培训，建议不少于15学时，每学时为45分钟。故本题选B选项。"},{"id":"law2-1","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"对于流动性风险限额的评估（）","options":["每半年一次","每三年一次","每两年一次","每一年一次"],"answer":"D","explain":"D选项正确，证券公司应至少每年对流动性风险限额进行一次评估，必要时进行调整。故本题选D选项。"},{"id":"law2-2","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《公司法》，关于有限责任公司股东会职权的说法，错误的是（）。","options":["对发行公司债券作出决议","制定公司的基本管理制度","审议批准公司的利润分配方案和弥补亏损方案","审议批准董事会的报告"],"answer":"B","explain":"B选项错误，制定公司的基本管理制度属于董事会的职责。股东会行使的法定职权包括：对发行公司债券作出决议、审议批准公司的利润分配方案和弥补亏损方案、审议批准董事会的报告等。"},{"id":"law2-3","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《公司法》，上市公司董事和高级管理人员在任职期间每年转让的股份不得超过其所持本公司股份总数的（）。","options":["15%","10%","20%","25%"],"answer":"D","explain":"D选项正确，公司董事、监事、高级管理人员在就任时确定的任职期间每年转让的股份不得超过其所持有本公司股份总数的25%。"},{"id":"law2-4","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《合伙企业法》，下列关于合伙企业应当解散的情形，说法错误的是（）。","options":["三分之二以上合伙人决定解散","合伙协议约定的解散事由出现","合伙人已不具备法定人数满三十天","合伙期限届满，合伙人决定不再经营"],"answer":"A","explain":"A选项错误，合伙企业解散情形为全体合伙人决定解散，而非三分之二以上。"},{"id":"law2-5","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《证券公司风险控制指标管理办法》，证券公司应建立以（）和流动性为核心的风险控制指标体系。","options":["净资本","净资产","总负债","净利润"],"answer":"A","explain":"A选项正确，证券公司应建立以净资本和流动性为核心的风险控制指标体系。"},{"id":"law2-6","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《证券公司和证券投资基金管理公司合规管理办法》，证券公司合规管理基本制度应当经（）审议通过后实施。","options":["股东会","董事会","风险控制委员会","经营管理层"],"answer":"B","explain":"证券公司应当制定合规管理的基本制度，经董事会审议通过后实施（B选项正确）。"},{"id":"law2-7","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《证券公司另类投资子公司管理规范》规定，下列关于另类投资子公司下设机构的说法，正确的是（）。","options":["可以下设全资子公司","可以下设控股子公司","不得下设任何机构","可以下设参股子公司"],"answer":"C","explain":"C选项正确，另类子公司不得再下设任何机构。"},{"id":"law2-8","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《证券公司证券自营业务指引》，关于自营业务资金出入的相关规定，下列行为正确的是（）。","options":["以个人名义从自营账户调出资金","以公司名义从自营账户提取现金","以个人名义调入资金","以公司名义调入资金"],"answer":"D","explain":"自营业务资金的出入必须以公司名义进行（D选项正确），禁止以个人名义从自营账户中调入调出资金，禁止从自营账户中提取现金。"},{"id":"law2-9","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《证券基金经营机构董事、监事、高级管理人员及从业人员监督管理办法》，证券从业人员的以下行为，不违反从业人员履职限制及禁止行为的是（）。","options":["泄露因职务便利获取的未公开信息","接受他人赠送的股票","买卖上市公司发行的可转换公司债券","公平进行业务竞争"],"answer":"D","explain":"D选项符合题意，公平进行业务竞争不违反从业人员的履职限制及禁止行为。"},{"id":"law2-10","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《证券期货经营机构私募资产管理业务管理办法》证券期货经营机构被宣告破产且在六个月内没有新的管理人承接的，证券期货经营机构设立的资产管理计划应当（）。","options":["终止","展期","中止","破产清算"],"answer":"A","explain":"A选项正确，证券公司被依法撤销资产管理业务资格或者依法解散、被撤销、被宣告破产，且在6个月内没有新的管理人承接，资产管理计划应当终止。"},{"id":"law2-11","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《证券市场资信评级业务管理办法》，证券评级机构评级委员会委员及评级从业人员在开展证券评级业务期间，下列关于证券资信评级业务人员的回避情形，错误的是（）。","options":["本人、直系亲属持有受评级机构或者受评级证券发行人的股份达到5%以上","本人、直系亲属为受评级机构或者受评级证券发行人的普通员工","本人、直系亲属持有受评级证券或者受评级机构发行的证券金额超过50万元","本人、直系亲属担任受评级机构或者受评级证券发行人聘任的会计师事务所、律师事务所、财务顾问等证券服务机构的负责人或者项目签字人"],"answer":"B","explain":"B选项错误，回避情形不包括普通员工。"},{"id":"law2-12","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《证券投资顾问业务暂行规定》，以下不属于证券投资顾问从业的禁止性行为的是（）。","options":["向客户说明与其投资建议不一致的观点","以个人名义向客户收取证券投资顾问服务费用","向客户承诺或者保证投资收益","代客户作出投资决策"],"answer":"A","explain":"A选项不属于禁止行为。"},{"id":"law2-13","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据资产支持证券信息披露的规定，管理人、托管人应当在每年（）之前向资产支持证券合格投资者披露上年度资产管理报告、年度托管报告。","options":["1月31日","3月31日","4月30日","6月30日"],"answer":"C","explain":"C选项正确，管理人、托管人应当在每年4月30日之前披露上年度资产管理报告、年度托管报告。"},{"id":"law2-14","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"公司应当自作出合并决议之日起（）日内通知债权人，并于30日内在报纸上公告。","options":["15","10","20","30"],"answer":"B","explain":"B选项正确，公司应当自作出合并决议之日起10日内通知债权人，并于30日内在报纸上或者国家企业信用信息公示系统公告。"},{"id":"law2-15","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"股份有限公司以超过股票票面金额的发行价格发行股份所得的溢价款应当列为公司的（）。","options":["资本公积金","任意公积金","股本溢价","法定公积金"],"answer":"A","explain":"A选项正确，应当列为公司资本公积金。"},{"id":"law2-16","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"关于诱骗投资者买卖证券、期货合约罪的犯罪构成，以下说法错误的是（）。","options":["主体包含证券公司、期货公司从业人员，不包含证券期货监督管理部门的工作人员","主观方面为故意","侵犯的客体是证券、期货市场的正常交易管理秩序和证券、期货投资人的合法利益","客观要件包含行为人故意提供虚假信息诱骗投资者买卖证券，造成严重后果的行为"],"answer":"A","explain":"A选项错误，诱骗投资者买卖证券、期货合约罪的主体包括证券期货监督管理部门的工作人员。"},{"id":"law2-17","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"关于证券金融公司开展转融通业务的资金来源的说法，错误的是（）。","options":["证券金融公司通过证券交易所的业务平台融入的资金","证券金融公司不得使用向股东借入次级债融入的资金","证券金融公司自有资金","证券金融公司通过自己的业务平台融入的资金"],"answer":"B","explain":"B选项错误，证券金融公司可以向股东或其他符合条件的机构投资者借入次级债，作为其资金来源之一。"},{"id":"law2-18","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"甲与乙串通，以事先约定的时间、价格和方式相互进行证券交易，影响证券交易价格，获得巨大非法收益，则甲与乙的行为构成（）罪。","options":["内幕交易","利用未公开信息交易","操纵证券市场","背信运用受托财产"],"answer":"C","explain":"C选项正确，构成操纵证券市场罪。"},{"id":"law2-19","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"甲证券营业部客服人员李某向张某销售某集合资产管理计划，李某向普通投资者张某进行了背景调查，并告知了适当性匹配意见及相关警示内容，并提供了书面文件。下列关于了解投资者信息的说法，错误的是（）。","options":["李某向张某销售产品，应当了解张某的诚信记录","李某向张某提供服务，应当了解张某的直系亲属信息","李某向张某提供服务，应当了解张某的投资经验","李某向张某提供服务，应当了解张某的风险偏好及可承受的损失"],"answer":"B","explain":"B选项错误，了解投资者信息不包括直系亲属信息。"},{"id":"law2-20","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"期货交易实行（）结算制度。","options":["次日负债","当日负债","当日无负债","次日无负债"],"answer":"C","explain":"C选项正确，期货交易实行当日无负债结算制度。"},{"id":"law2-21","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"投资者融券卖出时，私募证券投资基金的融券保证金比例不得低于（）。","options":["50%","70%","90%","120%"],"answer":"D","explain":"D选项正确，私募证券投资基金的融券保证金比例不得低于120%。"},{"id":"law2-22","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"我国有限责任公司股东不得超过（）人。","options":["50","100","150","200"],"answer":"A","explain":"A选项正确，有限责任公司由1个以上50个以下股东出资设立。"},{"id":"law2-23","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列法律法规及主要部门规章、规范性文件中，不属于证券公司发行与承销业务适用的是（）。","options":["《企业债券管理条例》","《证券发行与承销管理办法》","《上市公司收购管理办法》","《公司法》"],"answer":"C","explain":"C选项符合题意，《上市公司收购管理办法》属于与证券交易、证券投资活动有关的财务顾问业务的规章制度。"},{"id":"law2-24","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于非公开基金投资范围的说法中，错误的是（）。","options":["非公开募集基金可以买卖股指期货","非公开募集基金可以买卖基金份额","非公开募集基金可以买卖股权","非公开募集基金可以买卖基金合同约定以外的投资标的"],"answer":"D","explain":"D选项错误，非公开募集基金财产的投资包括买卖股票、股权、债券、期货、期权、基金份额及投资合同约定的其他投资标的。"},{"id":"law2-25","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于合伙企业的清算的说法，错误的是（）。","options":["合伙企业解散，应当由清算人进行清算。清算人由全体合伙人担任","经全体合伙人过半数同意，可以自合伙企业解散事由出现后15日内指定1个或者数个合伙人，或者委托第三人，担任清算人","合伙企业财产在支付清算费用和职工工资、社会保险费用、法定补偿金以及缴纳所欠税款、清偿债务后的剩余财产，依照普通合伙企业利润分配、亏损分担规则进行分配","清算结束，清算人应当编制清算报告，经2/3合伙人签名、盖章后，在15日内向企业登记机关报送清算报告，申请办理合伙企业注销登记"],"answer":"D","explain":"D选项错误，清算结束，清算人应当编制清算报告，经全体合伙人签名、盖章后，在15日内向企业登记机关报送清算报告。"},{"id":"law2-26","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于净资本的说法，正确的是（）。","options":["计算核心净资本时，不需要计提资产减值准备","净资本和净资产的概念相同","净资本由核心净资本和附属净资本构成","核心净资本由净资本和附属净资本构成"],"answer":"C","explain":"C选项正确，证券公司净资本由核心净资本和附属净资本构成。"},{"id":"law2-27","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于证券投资咨询机构及其执业人员向社会公众开展证券投资咨询业务活动的说法，错误的是（）。","options":["证券投资咨询从业人员向公众提供证券投资咨询服务时，需先行取得所在机构的认可","证券公司财务顾问专业人员在离开原岗位后的 6 个月内不得从事面向公众开展的投资咨询业务","证券投资咨询机构可参加媒体等机构举办的模拟证券投资大赛的节目，但证券投资咨询人员除外","经证监会核准的公开发行证券的企业的承销商及其所属的证券投资咨询机构，不得在公众传播媒体上刊登其为客户撰写的投资价值分析报告"],"answer":"C","explain":"C选项错误，证券投资咨询机构及其从业人员不得参加媒体等机构举办的荐股“擂台赛”、模拟证券投资大赛或类似的栏目或节目。"},{"id":"law2-28","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于资产管理产品的说法，错误的是（）。","options":["资产管理产品按投资性质不同可分为三类，即固定收益类产品、权益类产品、期货和衍生品类产品","固定收益类产品投资于债权类资产比例不低于 80%","权益类产品投资于股权类资产比例不低于 80%","期货和衍生品的持仓合约价值的比例不低于资产管理计划总资产的 80%"],"answer":"A","explain":"A选项错误，资产管理产品按照投资性质不同，分为固定收益类产品、权益类产品、期货和衍生品类产品和混合类产品。"},{"id":"law2-29","subject":"law","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列有关证券公司证券自营业务禁止性行为的说法，错误的是（）。","options":["证券自营业务不得违反规定委托他人代为买卖证券","证券公司不得利用本公司投资银行业务内幕信息从事证券交易活动","证券自营业务不得违反规定购买本证券公司控股股东发行的证券","证券公司可以将自营业务与经纪业务混合操作"],"answer":"D","explain":"D选项错误，证券公司不得将自营业务与经纪业务混合操作。"},{"id":"law2-30","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"以下关于信息安全的说法，错误的是（）。","options":["证券公司已经或可能掌握内幕信息的，应当将内幕信息所涉公司或证券列入限制名单","与公司工作人员签署保密文件，要求工作人员对工作中获取的敏感信息严格保密","加强对涉及敏感信息的信息系统、通信及办公自动化等信息设施、设备的管理，保障敏感信息安全","对可能知悉敏感信息的工作人员使用公司的信息系统或配发的设备形成的电子邮件、即时通信信息和其他通信信息进行监测"],"answer":"A","explain":"A选项错误，证券公司已经或者可能掌握内幕信息的，应当将内幕信息所涉公司或者证券列入观察名单（并非“限制名单”）。"},{"id":"law2-31","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"以下可能不属于专业投资者的是（）。","options":["金融资产300万的个人投资者","商业银行","保险公司","私募基金管理者"],"answer":"A","explain":"A选项符合题意，专业投资者自然人金融资产不低于500万元。"},{"id":"law2-32","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"以下属于证监会等监管机构制定证券经纪业务相关监管政策、实施监督管理的重要法规依据的是（）。","options":["《证券登记结算管理办法》","《信托法》","《公司法》","《证券公司监督管理条例》"],"answer":"D","explain":"D选项正确，《证券法》《证券公司监督管理条例》是中国证监会等监管机构制定证券经纪业务相关监管政策、实施监督管理的重要法律依据。"},{"id":"law2-33","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"由于股票期权交易实行（）制度，证券登记结算机构应当在当日及时将结算结果通知结算参与人，结算参与人据此对投资者进行结算，并应当将结算结果按照与投资者约定的方式及时通知投资者。","options":["当日无负债结算","保证金","强制平仓","套期保值"],"answer":"A","explain":"A选项正确，股票期权交易实行当日无负债结算制度。"},{"id":"law2-34","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"债券交易人员薪酬与激励合计超过人民币（）万元的，超过部分应按照等分原则递延发放，周期不少于2年。","options":["50","100","200","500"],"answer":"B","explain":"B选项正确，债券交易人员薪酬与激励合计超过人民币100万元的，超过部分应按照等分原则递延发放，周期不少于2年。"},{"id":"law2-35","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"证券公司从事证券自营业务，可以依据（）的附件《证券公司证券自营投资品种清单》买卖其中所列的证券。","options":["《证券公司证券自营业务指引》","《证券公司内部控制指引》","《证券公司风险控制指标管理办法》","《关于证券公司证券自营业务投资范围及有关事项的规定》"],"answer":"D","explain":"D选项正确，根据《关于证券公司证券自营业务投资范围及有关事项的规定》，证券公司从事证券自营业务，可以买卖此规定附件《证券公司证券自营投资品种清单》所列证券。"},{"id":"law2-36","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"证券公司派内部单位工作人员，借调至贫困山区参与扶贫项目，参与扶贫攻坚，体现了其（）。","options":["承担社会责任","遵守法律法规","接受政府和公众的监督","遵守社会公德"],"answer":"A","explain":"A选项正确，证券公司派员参与扶贫攻坚，属于积极响应国家脱贫攻坚战略，是典型的社会责任体现。"},{"id":"law2-37","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"证券公司应当于每年（）前，完成对上一年网络和信息安全工作的专项评估，编制网络和信息安全管理年报，报送中国证监会及其派出机构。","options":["8月31日","12月31日","4月30日","6月30日"],"answer":"C","explain":"C选项正确，证券公司应当于每年4月30日前，完成对上一年网络和信息安全工作的专项评估。"},{"id":"law2-38","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"中国证监会等监管机构制定证券公司信用业务相关监管政策、实施监督管理的法律依据是（）。","options":["《中国证券登记结算有限责任公司证券出借及转融通登记结算业务规则（试行）》","《转融通业务监督管理试行办法》","《证券公司融资融券业务管理办法》","《证券法》和《证券公司监督管理条例》"],"answer":"D","explain":"D选项正确，《证券法》和《证券公司监督管理条例》是中国证监会等监管机构制定信用业务相关监管政策、实施监督管理的重要法律依据。"},{"id":"law2-39","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"中国证监会根据证券公司评价计分的高低，将证券公司分为五大类十一个级别，其中（）是正常经营状态的最低等级。","options":["D级","B级","E级","C级"],"answer":"D","explain":"D选项正确，C级是正常经营状态的最低等级。"},{"id":"law2-40","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"（ ）不属于法律法规调整的关系。","options":["代理关系","委托关系","恋爱关系","朋友关系"],"answer":"CD","explain":"C、D选项正确，恋爱关系、朋友关系一般不受法律规范调整。"},{"id":"law2-41","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"不具备证券自营业务资格的证券公司，其自有资金能够从事（）。","options":["不以对冲风险为目的的金融衍生产品交易","以对冲风险为目的的金融衍生产品交易","以套期保值为目的的股票期权交易","公开发行并上市的股票交易"],"answer":"BC","explain":"B、C选项正确，不具备证券自营业务资格的证券公司只能以对冲风险为目的从事金融衍生产品交易，以套期保值为目的参与股票期权交易。"},{"id":"law2-42","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"从事私募基金业务活动，应当遵循（）的原则。","options":["自愿","平等","诚信","公平"],"answer":"ACD","explain":"从事私募基金业务活动，应当遵循自愿、公平、诚信原则。"},{"id":"law2-43","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《非上市公众公司监督管理办法》，对挂牌公司进行持续监管，防范风险，维护证券市场秩序的监管主体包括（）。","options":["国务院有关部门","商业银行","地方人民政府","中国证监会"],"answer":"ACD","explain":"中国证监会会同国务院有关部门、地方人民政府，对挂牌公司进行持续监管。"},{"id":"law2-44","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《关于规范债券市场参与者债券交易业务的通知》，债券交易包括（）等符合规定的债券交易业务。","options":["现券买卖","债券回购","债券远期","债券借贷"],"answer":"ABCD","explain":"债券交易包括现券买卖、债券回购、债券远期、债券借贷等。"},{"id":"law2-45","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《金融机构洗钱和恐怖融资风险评估及客户分类管理指引》，下列关于证券公司开展洗钱风险评估及客户分类管理的说法，错误的有（）。","options":["证券公司应对客户参与不同的业务进行不同的风险等级划分，同一客户在证券公司不应有唯一的风险等级","对高风险客户应采取强化的客户尽职调查及其他风险控制措施","对于首次建立业务关系的客户，无论风险等级高低，证券公司在初次确定其风险等级后的三年内至少应进行一次复核","对于已确立过风险等级的客户，证券公司不得再根据其风险程度设置相应的重新审核期限"],"answer":"AD","explain":"A选项错误，同一客户在证券公司应有唯一的风险等级。D选项错误，应根据风险程度设置相应的重新审核期限。"},{"id":"law2-46","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《期货和衍生品法》，下列关于期货交易所职责的说法正确的有（）。","options":["按照章程和业务规则对会员进行自律管理","开展交易者教育和市场培育工作","设计合约品种，安排合约品种上市","直接或者间接参与期货交易"],"answer":"ABC","explain":"D选项错误，期货交易场所不得直接或者间接参与期货交易。"},{"id":"law2-47","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《区域性股权市场自律管理与服务规范（试行）》，应当遵守证券行业自律管理的主体包括（）。","options":["区域性股权市场运营机构","区域性股权市场运营机构从业人员","参与区域性股权市场的证券公司","参与区域性股权市场的证券公司从业人员"],"answer":"ABCD","explain":"A、B、C、D均应当遵守证券行业自律管理。"},{"id":"law2-48","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《私募投资基金监督管理暂行办法》，私募基金管理人不得实施的行为有（）。","options":["从事损害基金财产的投资活动","公平地对待其管理的基金财产","玩忽职守，不按规定履行职责","挪用基金财产"],"answer":"ACD","explain":"B选项属于应当做的行为。"},{"id":"law2-49","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《刑法》，下列关于违规披露、不披露重要信息罪构成要件的说法，正确的有（）。","options":["本罪侵犯的客体是国家有关公司、企业的财会报告及其他重要信息的管理秩序和股东、社会公众和其他利害关系人的合法权益","本罪在客观方面表现为向股东和社会公众提供虚假的或者隐瞒重要事实的财务会计报告等，严重损害股东或者其他人利益的行为","本罪主观方面既可以是故意，也可以是过失","本罪的主体是特殊主体，即依法负有信息披露义务的公司、企业及相关责任人员"],"answer":"ABD","explain":"C选项错误，本罪主观方面只能由故意构成。"},{"id":"law2-50","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《证券法》，下列关于证券公司承销证券的说法，正确的有（）。","options":["证券公司承销证券，发现公开发行募集文件有虚假记载、误导性陈述或者重大遗漏的，不得进行销售活动","证券公司承销证券，不得进行虚假的或者误导投资者的广告宣传","证券公司承销证券，发现公开发行募集文件有虚假记载、误导性陈述或者重大遗漏，已经销售的，必须立即停止销售活动，并采取纠正措施","证券公司承销证券，不得以不正当竞争手段招揽承销业务"],"answer":"ABCD","explain":"A、B、C、D均正确。"},{"id":"law2-51","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《证券公司风险处置条例》下列关于国务院证券监督管理机构在处置证券公司风险工作中应履行的职责，正确的有（）。","options":["及时向国家审计机关通报涉嫌证券违规的情况，移送违规的案件","派驻风险处置现场工作组，对被处置证券公司、托管组、接管组、行政清理组、管理人以及参与风险处置的其他机构和人员进行监督和指导","协调证券交易所、证券登记结算机构、证券投资者保护基金管理机构，保障被处置证券公司证券经纪业务正常进行","向有关地方人民政府通报证券公司风险状况以及影响社会稳定的情况"],"answer":"BCD","explain":"A选项错误，应及时向公安机关等通报涉嫌刑事犯罪的情况。"},{"id":"law2-52","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《证券公司风险控制指标管理办法》，净资本指标不符合规定标准时，证券公司应当向（）报告。","options":["公司全体董事","中国证券业协会","中国证监会派出机构","公司全体股东"],"answer":"ACD","explain":"净资本指标不符合规定标准时，证券公司应当向公司全体董事、公司全体股东、中国证监会及其派出机构报告。"},{"id":"law2-53","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《证券公司流动性风险管理指引》，下列关于证券公司流动性风险限额的说法，正确的有（）。","options":["证券公司应当对流动性风险限额的执行情况进行监控","证券公司应当根据其业务规模、性质、复杂程度、流动性风险偏好和外部市场发展变化、监管要求等情况设定流动性风险限额","证券公司流动性风险限额一经设定，不得调整","证券公司应至少每年对流动性风险限额进行一次评估"],"answer":"ABD","explain":"C选项错误，流动性风险限额可以根据情况进行调整。"},{"id":"law2-54","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《证券公司流动性风险管理指引》，证券公司流动性风险管理的目标是建立健全流动性风险管理体系，对流动性风险采取（）等措施，以有效管控流动性风险。","options":["识别和计量","报告","监测","控制"],"answer":"ACD","explain":"流动性风险管理的目标是对流动性风险实施有效识别、计量、监测和控制。"},{"id":"law2-55","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《证券公司信用风险管理指引》，下列属于证券公司信用风险的有（）。","options":["因财务顾问违约导致损失的风险","因发行人违约导致损失的风险","因融资方违约导致损失的风险","因交易对手违约导致损失的风险"],"answer":"BCD","explain":"A选项通常属于操作风险。信用风险指因融资方、交易对手或发行人违约导致损失的风险。"},{"id":"law2-56","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《证券基金经营机构信息技术管理办法》，下列关于证券公司信息系统安全的说法，正确的有（）。","options":["证券公司应当结合公司发展战略、市场交易规模等因素定期对重要信息系统开展压力测试和评估分析，确保其容量满足业务开展需要","证券公司应当确保重要信息系统具备可审计功能，并可以根据监管部门的要求转换、提供数据","证券公司应当建立健全信息系统安全监测机制，设定监测指标并持续监测重要信息系统的运行状况","证券公司重要信息系统计划停止使用的，可不用开展技术和业务影响评估"],"answer":"ABC","explain":"D选项错误，证券公司重要信息系统计划停止使用的，应当开展技术和业务影响评估。"},{"id":"law2-57","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据合伙人对合伙企业债务承担责任的不同，合伙企业可分为（）。","options":["有限合伙企业","普通合伙企业","个人合伙企业","合资合伙企业"],"answer":"AB","explain":"合伙企业可分为普通合伙企业和有限合伙企业。"},{"id":"law2-58","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"股份有限公司董事，监事，高级管理人员持有本公司股票转让方式正确的有（）。","options":["在任职期间每年转让的股份不得超过其所持有本公司股份总数的 25%","在离职后一年内不得转让","上市交易之日起一年内不得转让","上市交易之日起半年内不得转让"],"answer":"AC","explain":"B选项错误，离职后半年内不得转让。D选项错误，上市交易之日起1年内不得转让。"},{"id":"law2-59","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"甲证券公司不得为（）开立信用业务账户。","options":["未按照要求提供有关情况的张某","从事证券交易时间不足半年，缺乏风险承担能力的李某","最近20个交易日日均证券类资产低于50万元或者有重大违约记录的王某","最近20个交易日日均证券类资产高于50万元的赵某"],"answer":"ABC","explain":"D选项符合开户条件。"},{"id":"law2-60","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"某证券公司的下列实践中，能够反映证券行业文化建设基本要求中\"牢记社会责任，展现良好形象\"的有（）。","options":["将对口帮扶地区的农副产品引入工会慰问品采购名单并鼓励会员优先选","多措并举增加注册资本并积极推动上市","建立各业务条线负责人必须出席的定期合规展业交流机制","积极参与证券行业支持民营企业发展系列资管计划（纾困基金）的设立"],"answer":"AD","explain":"B选项属于商业行为，C选项属于合规管理。"},{"id":"law2-61","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"普通投资者应至少在（）享有特别保护。","options":["信息告知","风险警示","适当性匹配","保证本金"],"answer":"ABC","explain":"普通投资者在信息告知、风险警示、适当性匹配等方面享有特别保护。"},{"id":"law2-62","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于非公开募集基金的募集与宣传推介的说法，正确的有（）。","options":["不得通过讲座、报告会、分析会等方式向其现有投资者宣传推介","不得通过报刊、电台、电视台等公众传播媒体向不特定对象宣传推介","不得在互联网上向不特定对象宣传推介","不得向合格投资者之外的单位和个人募集资金"],"answer":"BCD","explain":"A选项错误，现有投资者属于合格投资者，可以通过讲座等方式宣传推介。"},{"id":"law2-63","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于股份有限公司监事会的表述正确的有（）。","options":["监事会设主席一人，并应当设副主席","监事会主席由全体监事过半数选举产生","董事、高级管理人员不得兼任监事","监事会成员不得少于三人"],"answer":"BCD","explain":"A选项错误，监事会设主席1人，可以设副主席（并非应当）。"},{"id":"law2-64","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于有限责任公司股权转让的规定，说法正确的有（）。","options":["股东之间可以相互转让股权","股东向股东以外的人转让股权，其他股东自接到书面通知之日起满30日未答复的，视为放弃优先购买权","未经其他股东同意的，股东不得转让股权","股东向股东以外的人转让股权，口头书面通知其他股东即可，无需书面通知"],"answer":"AB","explain":"C选项说法过于绝对，D选项错误，应书面通知。"},{"id":"law2-65","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于证券公司对敏感信息采取保密措施的说法，正确的有（）。","options":["与证券公司工作人员签署保密文件，要求工作人员对工作中获取的敏感信息严格保密","对可能知悉敏感信息的工作人员使用的公司及个人各类信息系统或设备形成的电子邮件、即时通信信息和其他通讯信息进行监测","建立内幕信息知情人管理制度","加强对涉及敏感信息的信息系统、通信及办公自动化等信息设施、设备的管理，保障敏感信息安全"],"answer":"ACD","explain":"B选项错误，监测对象不包括个人设备。"},{"id":"law2-66","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于证券公司合规管理的说法，错误的有（）。","options":["证券公司首次开展行业已有可借鉴先例的业务，不需要进行新产品、新业务的评估与决策","经过合规负责人审核的材料，其他相关高级管理人员不需再对其中的内容负责","合规负责人发现公司存在合规风险隐患的，应依照公司章程及时向董事会、经营管理主要负责人报告，提出处理意见，并督促整改","合规负责人直接向总经理办公会负责"],"answer":"ABD","explain":"A选项错误，需要进行评估与决策。B选项错误，其他高级管理人员仍需对材料内容负责。D选项错误，合规负责人直接向董事会负责。"},{"id":"law2-67","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于子公司法律地位的说法，正确的有（）。","options":["子公司具有独立的法人资格","子公司从事经营活动的民事责任由其母公司承担","子公司不具有法人资格","子公司依法独立承担民事责任"],"answer":"AD","explain":"子公司具有法人资格，依法独立承担民事责任。"},{"id":"law2-68","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列规章及规范性文件涉及上市公司收购以及上市公司重大资产重组的有（）。","options":["《科创板上市公司重大资产重组特别规定》","《上市公司并购重组财务顾问业务管理办法》","《证券投资顾问业务暂行规定》","《上市公司重大资产重组管理办法》"],"answer":"ABD","explain":"C选项属于证券投资咨询业务相关规则。"},{"id":"law2-69","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列属于期货交易制度的有（）。","options":["账户实名制","当日无负债结算制度","保证金制度","持仓限额制度"],"answer":"ABCD","explain":"A、B、C、D均属于期货交易制度。"},{"id":"law2-70","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列行为不属于资产管理业务禁止行为的有（）。","options":["为规避监管的期货业务提供交易便利","投资决策错误导致资产管理计划业绩回报处于同类产品末端","系统故障导致交易无法达成，造成资产管理计划财产受损","向投资者返还管理费"],"answer":"BC","explain":"B、C属于正常商业风险或技术风险，不属于禁止行为。"},{"id":"law2-71","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"证券公司承销证券，同发行人签订的证券代销协议必备的条款包括（）。","options":["代销证券的发行价格","代销的期限及起止日期","代销证券的种类、数量","代销证券的金额"],"answer":"ABCD","explain":"A、B、C、D均属于必备条款。"},{"id":"law2-72","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"证券公司风险管理部门具备3年以上的有关领域工作经历的人员占公司总部员工比例应不低于2%，不包括（）。","options":["金融","法律","证券","新闻"],"answer":"BD","explain":"B、D选项不属于相关领域。"},{"id":"law2-73","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"证券公司净资本或者其他风险控制指标不符合规定标准的，中国证监会派出机构应当责令公司限期改正。整改期内，中国证监会及其派出机构应当区别情形，可以对证券公司采取的措施有（）。","options":["限制转让财产或在财产上设定其他权利","限制薪酬发放","限制分配红利","停止批准新业务"],"answer":"ACD","explain":"B选项错误，限制薪酬发放不属于整改期内可采取的措施。"},{"id":"law2-74","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"证券公司开展中间介绍业务，有下列（）行为的，按照《期货交易管理条例》相关规定进行处罚。","options":["未将财务、人员、经营场所与期货公司分开隔离","未将介绍业务与其他经营业务分开或者有效隔离","未按规定审查客户的开户资料和身份真实性","未经许可擅自开展介绍业务"],"answer":"ABCD","explain":"A、B、C、D均属于应处罚行为。"},{"id":"law2-75","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"证券公司内部控制应当遵循的原则包括（）。","options":["健全","合理","制衡","独立"],"answer":"ABCD","explain":"内部控制应当遵循健全、合理、制衡、独立原则。"},{"id":"law2-76","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"证券公司融资融券的业务决策机构主要负责（）。","options":["保证金收取和交易执行等业务操作","确定对单一客户和单一证券的授信额度","决定与融资融券业务有关的部门设置","确定融资融券的期限和利率费率"],"answer":"BD","explain":"A选项属于分支机构职责，C选项属于董事会职责。"},{"id":"law2-77","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"证券期货经营机构违反适当性管理规定，有下列（）情形的，给予警告，并处以3万元以下罚款；对直接负责的主管人员和其他直接责任人员，给予警告，并处以3万元以下罚款。","options":["未按规定对普通投资者进行细化分类和管理的","未按规定进行投资者类别转化的","未建立或者更新投资者评估数据库的","未按规定了解所销售产品或者所提供服务信息或者履行分级义务的"],"answer":"ABCD","explain":"A、B、C、D均属于应处罚情形。"},{"id":"law2-78","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"证券投资顾问业务和发布证券研究报告的区别包括以下（）方面。","options":["立场不同","服务对象不同","市场影响有所不同","服务方式和服务内容不同"],"answer":"ABCD","explain":"A、B、C、D均属于区别。"},{"id":"law2-79","subject":"law","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"证券投资咨询业务的基本形式包括（）。","options":["证券投资顾问","委托理财","发布证券研究报告","销售基金"],"answer":"AC","explain":"证券投资顾问业务和发布证券研究报告是证券投资咨询业务的两种基本形式。"},{"id":"law2-80","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"《证券法》适用于在中华人民共和国境内的股票、公司债券、存托凭证、证券投资基金和国务院依法认定的其他证券的发行和交易。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券投资基金的发行主要由《中华人民共和国证券投资基金法》进行规范。"},{"id":"law2-81","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"除公募资产管理产品外，投资者以合伙企业、契约等非法人形式直接或者间接投资于证券公司资产管理计划的，应向管理人充分披露实际投资者和最终资金来源。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"law2-82","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"对证券行业高级管理人员的岗前培训时间和其他从业人员一致。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。培训学时实行差异化管理。"},{"id":"law2-83","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"法律主体主要包括自然人、组织和国家三类。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"law2-84","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《证券公司风险处置条例》，证券公司风险控制指标不符合有关规定，在规定期限内未能完成整改的，中国证券业协会可以责令证券公司停止部分或者全部业务进行整顿。停业整顿的期限不超过3个月。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。应为国务院证券监督管理机构，而非中国证券业协会。"},{"id":"law2-85","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《证券公司风险管理条例》，证券公司风险控制指数不达标的，中国证券业协会责令整改，逾期不改，证券公司停办全部业务或部分业务，停办最长不超三个月。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。派出机构责令改正，并非中国证券业协会。"},{"id":"law2-86","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《证券公司风险控制指标管理办法》，证券公司应当建立动态的风险控制指标监控和资本补足机制，确保净资本等各项风险控制指标在每个季末都符合规定标准。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。应确保在任一时点都符合规定标准。"},{"id":"law2-87","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《证券公司和证券投资基金管理公司合规管理办法》，证券公司的合规是指证券公司及其工作人员的经营管理和执业行为符合法律、法规、规章及规范性文件、行业规范和自律规则、公司内部规章制度，以及行业普遍遵守的职业道德和行为准则。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"law2-88","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"公开发行的证券，可以在证券交易所、国务院批准的其他全国性证券交易场所、按照国务院规定设立的区域性股权市场转让。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。应为非公开发行的证券。"},{"id":"law2-89","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"合规管理人员工作称职的，其年度薪酬收入总额原则上不低于所在机构同等条件（同岗位类型、同职级、同考核结果）人员的平均水平。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"law2-90","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"合伙人企业中，有限合伙企业只存在普通合伙人，该公司应该被注销。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。有限合伙企业仅剩普通合伙人的，转为普通合伙企业。"},{"id":"law2-91","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"经营证券承销与保荐、证券融资融券、证券做市交易、证券自营、其他证券业务之一的，注册资本最低限额为1亿元。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"law2-92","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"全面风险管理包含了：“全员”对“全部风险”进行管理、开展风险管理的“全部活动”、对风险进行“全程管理”四部分含义。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"law2-93","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"声誉风险不包括战略风险和法律风险。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"law2-94","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"王某在2020年3月因证券违法行为受到过行政处罚，2022年9月其参与内幕交易获利30万元，其行为应予立案追诉。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。2020年3月至2022年9月已超出2年限制。"},{"id":"law2-95","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"为加强融资融券业务集中统一管理，证券公司分管融资融券业务的高级管理人员应该兼管风险监控部门。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。分管融资融券业务的高级管理人员不得兼管风险监控部门和业务稽核部门。"},{"id":"law2-96","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"我国的金融市场世界排名第一，保险市场也名列世界前茅，我国是金融强国。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。我国还未成为金融强国。"},{"id":"law2-97","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"向投资者销售或者提供\"荐股软件\"，并直接或者间接获取经济利益的，属于从事证券公司中间介绍业务，应当经中国证监会许可，取得相关业务资格。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。属于从事证券投资咨询业务。"},{"id":"law2-98","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"有限责任公司只能募集设立。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。有限责任公司只能采取发起设立的方式。"},{"id":"law2-99","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"在上交所开展的股票质押式回购业务融入方违约处置完成后，证券公司向中国证券业协会、证券交易所、中国结算提交违约处置结果报告。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。应向交易所、中国结算和中国证券投资者保护基金有限责任公司提交。"},{"id":"law2-100","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"在营业场所内办理普通投资者转化为专业投资者应全程录音录像。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"law2-101","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"在证券公司从事基金产品销售需要具有基金从业资格证。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"law2-102","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"证券包销包括证券公司将发行人的证券按照协议全部购入的承销方式或者在承销期结束时将售后剩余证券全部自行购入的承销方式（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"law2-103","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"证券公司代销证券期限最长不得超过60日。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券的代销、包销期限最长不得超过90日。"},{"id":"law2-104","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"证券公司分类监管评价设定正常经营的证券公司基准分为90分。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。基准分为100分。"},{"id":"law2-105","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"证券公司及其境内分支机构可以经营未经批准的业务。","options":["正确","错误"],"answer":"B","explain":"本题说法错误。不得经营未经批准的业务。"},{"id":"law2-106","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"证券公司借助信息技术手段从事证券基金业务活动，应当在依法合规、有效防范风险的前提下进行。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"law2-107","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"证券公司应当设专职部门或者岗位，处理客户投诉。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"law2-108","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"证券投资咨询人员只需专科学历即可执业登记。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。需具有大学本科以上学历。"},{"id":"law2-109","subject":"law","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"中国证监会、国务院其他主管部门等其他省部级以上单位作出的表彰、奖励应当记入中国证监会建立的全国统一的证券期货市场诚信档案数据库。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"law2-110","subject":"law","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】2021年底，国内甲证券公司担任乙股份公司的保荐机构，甲证券公司按照协议全部购入乙公司将要发行的全部股票，然后分销给其他投资者。甲证券公司承担销售和价格的全部风险，甲证券公司本次承销活动非常顺利，在短时间内将所承销股票全部售出。此后，甲证券公司以自有资金在证券市场上对乙公司的股票进行买卖，并赚取了买卖差价。请根据上述背景信息回答以下问题。\n\n【问题】要求1 甲证券公司在承销证券时，应对公开发行募集文件的（）进行核查。","options":["真实性","合理性","准确性","完整性"],"answer":"ACD","explain":"证券公司承销证券，应当对公开发行募集文件的真实性、准确性、完整性进行核查。"},{"id":"law2-111","subject":"law","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】2021年底，国内甲证券公司担任乙股份公司的保荐机构，甲证券公司按照协议全部购入乙公司将要发行的全部股票，然后分销给其他投资者。甲证券公司承担销售和价格的全部风险，甲证券公司本次承销活动非常顺利，在短时间内将所承销股票全部售出。此后，甲证券公司以自有资金在证券市场上对乙公司的股票进行买卖，并赚取了买卖差价。请根据上述背景信息回答以下问题。\n\n【问题】要求2 甲证券公司以自有资金在证券市场上对乙公司的股票进行买卖，并赚取了买卖差价，证券公司在承销证券要求包括（）。","options":["注册资本不低于1亿元人民币","注册资本不低于5亿元人民币","净资本不低于2亿元人民币","净资本不低于5000万元人民币"],"answer":"BC","explain":"经营证券承销与保荐、证券自营等两项以上，注册资本最低5亿元，净资本不低于2亿元。"},{"id":"law2-112","subject":"law","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】唐某为A证券公司营业部总经理，负责营业部全面工作。孙某为A证券公司营业部客户经理，负责开发及维护客户。201x年3月至201x年8月，唐某、孙某擅自运用客户沙某的证券账户进行交易，造成沙某证券账户亏损人民币1080万元，为A证券公司赚取交易手续费121万元。法院经审理认为，唐某、孙某未征得沙某同意，利用掌握的交易密码自行操作沙某证券账户，属于擅自运用客户资金的行为。唐某、孙某为A证券公司员工，其违法行为收取的手续费亦归A证券公司所有，A证券公司构成单位犯罪。\n\n【问题】要求1 A证券公司违背受托义务，擅自运用客户资金，情节特别严重，其行为侵犯了国家的金融管理秩序和客户的合法权益，构成（）。","options":["非法吸收公众存款罪","集资诈骗罪","背信运用受托财产罪","利用未公开信息交易罪"],"answer":"C","explain":"C选项正确，构成背信运用受托财产罪。"},{"id":"law2-113","subject":"law","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】唐某为A证券公司营业部总经理，负责营业部全面工作。孙某为A证券公司营业部客户经理，负责开发及维护客户。201x年3月至201x年8月，唐某、孙某擅自运用客户沙某的证券账户进行交易，造成沙某证券账户亏损人民币1080万元，为A证券公司赚取交易手续费121万元。法院经审理认为，唐某、孙某未征得沙某同意，利用掌握的交易密码自行操作沙某证券账户，属于擅自运用客户资金的行为。唐某、孙某为A证券公司员工，其违法行为收取的手续费亦归A证券公司所有，A证券公司构成单位犯罪。\n\n【问题】要求2 唐某作为营业部直接负责的主管人员，孙某作为该营业部其他责任人员，依法均应予惩处，下列刑罚中，说法正确的有（）。","options":["唐某，判处有期徒刑3年6个月，并处罚金人民币20万元","孙某，判处有期徒刑3年，并处罚金5万元","唐某，判处有期徒刑2年6个月，并处罚金人民币20万元","孙某，判处有期徒刑3年，并处罚金3万元"],"answer":"AB","explain":"情节特别严重的，处3年以上10年以下有期徒刑，并处5万元以上50万元以下罚金。"},{"id":"law2-114","subject":"law","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】甲公司成立于2010年9月10日发起人李某认购公司股份200万股，为公司的小股东。2017年12月15日公司向社会公开发行A股10000万股，2018年1月5日公司股票在证券交易所上市交易。陈某于2011年1月10日至2019年5月10日期间任甲公司副董事长、董事，2019年5月11日正式离职。截至2019年6月，陈某个人直接持有甲公司股票3444000股。陈某实际控制的乙公司持有丙公司23.26%的股份，丙公司持有甲公司股票2091000股。根据该案例，回答以下问题。\n\n【问题】要求1 下列关于公司上市后李某在公司成立时认购的股份转让的说法，正确的是（）。","options":["2018年1月5日后方可以转让","2019年1月5日后方可以转让","2019年12月15日后方可以转让","2018年9月10日后方可以转让"],"answer":"B","explain":"公司公开发行股份前已发行的股份，自公司股票在证券交易所上市交易之日起一年内不得转让。2018年1月5日上市，2019年1月5日后可转让。"},{"id":"law2-115","subject":"law","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】甲公司成立于2010年9月10日发起人李某认购公司股份200万股，为公司的小股东。2017年12月15日公司向社会公开发行A股10000万股，2018年1月5日公司股票在证券交易所上市交易。陈某于2011年1月10日至2019年5月10日期间任甲公司副董事长、董事，2019年5月11日正式离职。截至2019年6月，陈某个人直接持有甲公司股票3444000股。陈某实际控制的乙公司持有丙公司23.26%的股份，丙公司持有甲公司股票2091000股。根据该案例，回答以下问题。\n\n【问题】要求2 根据《公司法》，下列有关股份有限公司董事在就任时确定的任职期间转让所持有的本公司股份的表述，正确的有（）。","options":["每年转让的股份不得超过其所持股份总数的 5%","每年转让的股份不得超过其所持股份总数的 25%","所持股份自公司上市之日起12个月内不得转让","所持股份自公司上市之日起36个月内不得转让"],"answer":"BC","explain":"B、C选项正确。"},{"id":"law2-116","subject":"law","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】甲公司成立于2010年9月10日发起人李某认购公司股份200万股，为公司的小股东。2017年12月15日公司向社会公开发行A股10000万股，2018年1月5日公司股票在证券交易所上市交易。陈某于2011年1月10日至2019年5月10日期间任甲公司副董事长、董事，2019年5月11日正式离职。截至2019年6月，陈某个人直接持有甲公司股票3444000股。陈某实际控制的乙公司持有丙公司23.26%的股份，丙公司持有甲公司股票2091000股。根据该案例，回答以下问题。\n\n【问题】要求3 下列有关股份有限公司股份转让的规定，错误的是（）。","options":["记名股票，由股东以背书方式或者法律、行政法规规定的其他方式转让","无记名股票，由股东将该股票交付给受让人后即可","股份在法律、行政法规规定的限制转让期限内出质的，质权人在限制转让期限内行使质权","公司董事、监事、高级管理人员离职后半年内，不得转让其所持有的本公司股份"],"answer":"C","explain":"C选项错误，质权人不得在限制转让期限内行使质权。"},{"id":"law2-117","subject":"law","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】张某担任甲证券公司私募资产管理业务投资经理。2022年6月1日，张某从甲证券公司离任，拟入职乙证券公司担任私募资产管理业务投资经理，从事投资业务。请根据上述背景信息回答以下问题。\n\n【问题】要求1 张某作为私募资产管理业务的投资经理，应当具备（）。","options":["从事证券业务所需的专业能力","2年以上投资管理、投资研究、投资咨询等相关业务经验","良好的诚信记录和职业操守","法律法规规定的其他条件"],"answer":"ACD","explain":"B选项错误，应具有3年以上相关业务经验。"},{"id":"law2-118","subject":"law","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】张某担任甲证券公司私募资产管理业务投资经理。2022年6月1日，张某从甲证券公司离任，拟入职乙证券公司担任私募资产管理业务投资经理，从事投资业务。请根据上述背景信息回答以下问题。\n\n【问题】要求2 关于张某的离任审查，下列说法正确的有（）。","options":["张某离任时，甲证券公司应当立即对其进行离任审查","张某在2022年12月1日方可在乙证券公司担任私募资产管理业务投资经理","甲证券公司应当自张某离任之日起3个月内形成离任审查报告，以存档备查","甲证券公司应当自张某离任之日起30个工作日内将审查报告报送中国证监会相关派出机构及证券投资基金业协会"],"answer":"AB","explain":"A选项正确，应立即进行离任审查。B选项正确，离任未满6个月不得从事相关业务。C选项错误，应为2个月内。D选项错误，应报送中国证监会相关派出机构。"},{"id":"law2-119","subject":"law","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】张某担任甲证券公司私募资产管理业务投资经理。2022年6月1日，张某从甲证券公司离任，拟入职乙证券公司担任私募资产管理业务投资经理，从事投资业务。请根据上述背景信息回答以下问题。\n\n【问题】要求3 甲、乙证券公司应当针对私募资产管理业务的主要业务人员和相关管理人员建立收入递延支付机制，递延支付年限原则上不少于（）年。","options":["1","2","3","4"],"answer":"C","explain":"C选项正确，递延支付年限原则上不少于3年。"}]},{"id":"basics1","subject":"basics","name":"金融基础 · 押题卷一","stats":{"单选":30,"多选":50,"判断":30,"案例":10},"questions":[{"id":"basics1-0","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"1992年以前，我国对银行业、证券业、保险业、信托业实行集中统一监管的机构是（）。","options":["财政部","国务院金融稳定委员会","中国人民银行","国家发改委"],"answer":"C","explain":"C选项正确，1984年，中国人民银行开始专门行使中央银行职能，负责对银行业、证券业、保险业、信托业实行集中统一监管。"},{"id":"basics1-1","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"IOSCO（国际证监会组织）不包含下列（）监管目标。","options":["保护投资者","保证市场公平透明","消除市场波动","减少系统性风险"],"answer":"C","explain":"国际证监会组织公布的证券监管三个目标：保护投资者利益、保证证券市场的公平效率和透明、降低系统性风险。故本题选C选项。"},{"id":"basics1-2","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"从基金财产中列支的费用不包括（）。","options":["基金托管人的托管费","基金的证券交易费用","基金转换费","基金管理人的管理费"],"answer":"C","explain":"基金转换费由基金投资者承担，不从基金财产中列支。"},{"id":"basics1-3","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"地方政府债券包括一般债券和（）。","options":["公益债权","专项债券","短期债券","中期债券"],"answer":"B","explain":"B选项正确，地方政府债券按资金用途和偿还资金来源不同，通常可以分为一般债券和专项债券。"},{"id":"basics1-4","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"非累积优先股票的特点是股息分派以（）为界，当年结清。","options":["每个经营周期","每个营业年度","每个产业周期","每个生产周期"],"answer":"B","explain":"非累积优先股是指公司不足以支付优先股的全部股息时，对所欠股息部分，优先股股东不能要求公司在以后年度补发，以每个营业年度为界，当年结清。"},{"id":"basics1-5","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《证券法》，持有上市公司（）以上有表决权股份的股东可以作为征集人代为出席股东大会，并代为行使提案权、表决权等股东权利。","options":["0.1%","1%","0.3%","0.5%"],"answer":"B","explain":"新《证券法》明确持有1%以上有表决权股份的股东可以作为征集人。"},{"id":"basics1-6","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据商业银行的业务分类，下列不属于商业银行表外业务中担保承诺类业务的是（）。","options":["信用证","投资业务","保函","银行承兑汇票"],"answer":"B","explain":"投资业务属于商业银行的资产业务，不属于表外业务中的担保承诺类业务。"},{"id":"basics1-7","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"国际债券以（）作为计量货币。","options":["外国货币","本国货币或外国货币","本国货币","通用货币"],"answer":"D","explain":"国际债券在国际市场上发行，其计价货币往往是国际通用货币。"},{"id":"basics1-8","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"基金一般都是按照（）的时间间隔对基金资产进行估值。","options":["不确定","固定","管理人随时确定","托管人随时确定"],"answer":"B","explain":"B选项正确，基金一般都按照固定的时间间隔对基金资产进行估值。"},{"id":"basics1-9","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"交易双方在场外市场上通过协商，按约定价格在约定的未来日期买卖某种标的金融资产的合约称为（）。","options":["互换合约","远期合约","期货合约","期权合约"],"answer":"B","explain":"B选项正确，金融远期合约是指交易双方在场外市场上通过协商，按约定价格在约定的未来日期买卖某种标的金融资产的合约。"},{"id":"basics1-10","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"买卖双方签订了一份合约，该合约规定买方在交付了一笔费用后，即取得在合约规定的到期日或到期日以前按协定价买入或卖出一定数量相关股票的权利。这种合约称为（）合约。","options":["货币期权","互换期权","利率期权","股票期权"],"answer":"D","explain":"D选项正确，股票期权指买方在交付了期权费后，即取得在合约规定的到期日或到期日以前按协定价格买入或卖出一定数量相关股票的权利。"},{"id":"basics1-11","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"某投资者投资项目，该项目五年后，将一次性获得一万元收入假定投资者希望的年利率为5%，那么按单利计算，投资的现值为（）。","options":["8000元","7500元","10000元","12500元"],"answer":"A","explain":"PV = FV / (1 + i × n) = 10000 / (1 + 5% × 5) = 8000元。"},{"id":"basics1-12","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"某外商独资私募证券基金管理机构拟在中国境内开展私募证券基金管理业务，其需要满足的条件不包括（）。","options":["该机构为在中国境外设立的公司","该机构的境外股东为所在国家金融监管当局（已与中国证监会签订证券监管合作谅解备忘录）批准的金融机构","应当在中国证券投资基金业协会登记为私募证券基金管理人","该机构及其境外股东最近3年没有受到监管机构和司法机构的重大处罚"],"answer":"A","explain":"A选项错误，该私募证券基金管理机构应为在中国境内设立的公司。"},{"id":"basics1-13","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"目前，证券业传统业务面临激烈的（）竞争，金融业对外开放和金融混业经营趋势进一步加剧了证券行业竞争。","options":["全球化","异质化","多样化","同质化"],"answer":"D","explain":"D选项正确，目前证券业传统业务面临激烈的同质化竞争。"},{"id":"basics1-14","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"双方约定在未来某一时刻按照现在确定的价格买卖标的证券的行为称为（）。","options":["远期交易","现券交易","回购交易","即期交易"],"answer":"A","explain":"A选项符合题意，远期交易是双方约定在未来某一时刻按照现在确定的价格买卖标的债券的行为。"},{"id":"basics1-15","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"投资者在证券交易所买卖证券，是通过委托（）来进行的。","options":["证券经纪商","中国证券业协会","中国证券登记结算有限责任公司上海分公司或深圳分公司","上海证券交易所或深圳证券交易所"],"answer":"A","explain":"A选项正确，投资者在证券交易所买卖证券，是通过委托证券经纪商来进行的。"},{"id":"basics1-16","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"我国的证券登记结算制度实行证券（）。","options":["代持制","实名制","代理制","经纪制"],"answer":"B","explain":"B选项正确，我国的证券登记结算制度实行证券实名制。"},{"id":"basics1-17","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列不属于北交所上市公司向特定对象发行股票的禁止情形的是（）。","options":["上市公司擅自改变募集资金用途，未作纠正也未经股东大会认可","上市公司实际控制人因涉嫌侵占财产正被司法机关立案侦查，尚未有明确结论意见","上市公司最近半年内存在重大信息披露违法行为","上市公司实际控制人被列入失信被执行人名单但目前情形已经消除"],"answer":"D","explain":"D选项符合题意，被列入失信被执行人名单且情形尚未消除才属于禁止情形，已消除的不属于。"},{"id":"basics1-18","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列不属于金融机构类投资者的是（）。","options":["银行业金融机构","保险经营机构","证券经营机构","全国社会保障基金"],"answer":"D","explain":"D选项符合题意，全国社会保障基金属于基金类投资者。"},{"id":"basics1-19","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列不属于其他存款吸收机构的是（）。","options":["信用合作社","投资银行","抵押贷款银行","证券交易商"],"answer":"D","explain":"D选项符合题意，证券交易商属于其他金融公司。"},{"id":"basics1-20","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列关于ABS产品的说法，错误的是（）。","options":["狭义的ABS主要以某一类同质资产为标的资产","ABS产品可以分为狭义的ABS和担保债务凭证CDO","担保债务凭证的基础资产是一系列的债务工具","期限在一年以下的资产支持商业票据属于担保债务凭证CDO的基础资产"],"answer":"D","explain":"D选项错误，期限在一年以下的资产支持商业票据属于狭义的ABS。"},{"id":"basics1-21","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列关于地方政府债券的说法，错误的是（）。","options":["由地方政府发行并负责偿还的债券","简称地方债券","发行主体是地方政府","筹集资金不能用于弥补地方财政资金的不足"],"answer":"D","explain":"D选项错误，筹集的资金一般用于弥补地方财政资金的不足。"},{"id":"basics1-22","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列关于风险与金融产品的说法，错误的是（）。","options":["金融产品具有风险性","\"无风险收益率\"仅是理论上的一种设定","金融产品定价仅考虑收益","风险溢价是对投资者承担风险的补偿"],"answer":"C","explain":"C选项错误，金融产品定价需要综合考虑收益、风险、流动性等因素，不是仅考虑收益。"},{"id":"basics1-23","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列关于金融市场功能的说法，错误的是（）。","options":["金融市场的首要功能是风险管理","金融市场提供流动性指其为金融资产交易变现或赎回提供渠道和机制","金融市场中供求双方的相互作用决定了交易资产的价格","在金融交易中，花费一定的时间来定位交易对手一般视为隐性成本"],"answer":"A","explain":"A选项错误，金融市场的首要功能是资金融通。"},{"id":"basics1-24","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列关于融资融券交易的说法，错误的是（）。","options":["融资交易是一种杠杆交易，能放大投资者的盈利或者亏损，参与融资融券交易要求投资者有较强的证券研究能力和风险承受能力","融资交易是指投资者向证券公司缴纳一定的保证金，融入一定数量的资金买入股票的交易行为","融资融券交易又被称为信用交易，分为融资交易和融券交易","融资交易中投资者向证券公司提交的保证金必须是现金"],"answer":"D","explain":"D选项错误，投资者向证券公司提交的保证金可以是现金或者可充抵保证金的证券。"},{"id":"basics1-25","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列关于申请募集基金时基金招募说明书和投资者适当性管理制度的说法，错误的是（）。","options":["有明确的对基金投资者的定位、识别和评估的方法","有符合投资者特征的投资者适当性管理制度","招募说明书要真实、准确、完整地披露投资者作出投资决策所需要的重要信息","招募说明书语言要详尽，不需要简明，但要易懂、实用，符合投资者的理解能力"],"answer":"D","explain":"D选项错误，招募说明书语言简明、易懂、实用，符合投资者的理解能力。"},{"id":"basics1-26","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列关于我国基金资产估值原则的说法错误的是（）。","options":["有充分证据表明估值日或最近交易日的报价不能真实反映公允价值的，应对报价进行调整，确定公允价值","估值日无报价且最近交易日后未发生影响公允价值计量的重大事件的，应采用最近交易日的报价确定公允价值","采用估值技术确定公允价值时，应优先使用不可观察输入值","对不存在活跃市场的投资品种，应采取在当前情况下适用并且可利用数据和其他信息支持的估值技术确定公允价值"],"answer":"C","explain":"C选项错误，采用估值技术确定公允价值时，应优先使用可观察输入值。"},{"id":"basics1-27","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列关于证券公司的说法，错误的是（）。","options":["世界各国对证券公司的划分和称呼不尽相同，美国的通俗称谓是“投资银行”，英国则称为“商人银行”","证券公司是证券市场证券和资金的主要提供者","在我国，设立证券公司必须经国务院证券监督管理机构审查批准","证券公司可以通过资产管理方式，为投资者提供证券及其他金融产品的投资管理服务"],"answer":"B","explain":"B选项错误，证券公司是证券市场的主要中介机构，是证券市场投融资服务的提供者。"},{"id":"basics1-28","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列关于证券公司声誉风险管理的说法，正确的是（）。","options":["公司有董事会秘书，可不设新闻发言人","公司声誉风险只能由风险管理部门牵头","公司办公室主任不能担任新闻发言人","公司可有多名新闻发言人，但其中至少一人为高管"],"answer":"D","explain":"D选项正确，新闻发言人可由一人或多人担任，其中至少一名为公司高级管理人员。"},{"id":"basics1-29","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"行权价格可以取基础资产在一段时间内的平均值的期权，称之为（）。","options":["平均期权","任选期权","障碍期权","百慕大期权"],"answer":"A","explain":"A选项正确，行权价格可以取基础资产在一段时间内的平均值的期权称为平均期权。"},{"id":"basics1-30","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"在公募REITs的运营管理方面，（）应当主动履行基础设施项目运营管理职责，通过设立专门子公司或者委托运营管理机构负责基础设施项目运营管理。","options":["基金管理人","项目公司","财务顾问","原始权益人"],"answer":"A","explain":"A选项正确，基金管理人应当主动履行基础设施项目运营管理职责。"},{"id":"basics1-31","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"在基金募集期间募集的资金应当（），在基金募集行为结束前，任何人不得动用。","options":["存入专门账户","存入管理人账户","存入托管人账户","存入第三方账户"],"answer":"A","explain":"A选项正确，在基金募集期间募集的资金应当存入专门账户。"},{"id":"basics1-32","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"在债券评级中，证券评级机构应当在受评证券存续期内每年至少出具一次（）。","options":["评级等级跟踪报告","实地调研跟踪报告","定期跟踪评级报告","临时跟踪评级报告"],"answer":"C","explain":"C选项正确，证券评级机构应当在受评证券存续期内每年至少出具一次定期跟踪评级报告。"},{"id":"basics1-33","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"在长期实践探索的基础上，对证券公司实施有效监管的基础性制度已经基本形成。其中，基础性制度不包括（）。","options":["证券公司业务许可制度","以风险资本为核心的风险监控和预警制度","客户交易结算资金第三方存管制度","信息报送和披露制度"],"answer":"B","explain":"B选项符合题意，应为以净资本和流动性为核心的风险监控和预警制度。"},{"id":"basics1-34","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司对于风险超限额的处置，应当由（）负责组织落实，并对超限额处置的实际效果定期进行返回检验。","options":["高级管理人员","董事会","监事会","风险管理部门"],"answer":"D","explain":"D选项正确，对于超限额的处置，应由风险管理部门负责组织落实。"},{"id":"basics1-35","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司为客户办理证券和资金的清算与交收的时间为（）。","options":["每个工作日结束后","每个自然日结束后","每个指定日结束后","每个交易日结束后"],"answer":"D","explain":"D选项正确，每日交易结束后，证券公司要为客户办理证券和资金的清算与交收。"},{"id":"basics1-36","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"直接融资的特点之一是（）。","options":["融资的主动权主要掌握在金融中介机构手中","融资者有相对较强的自主性","融资信誉的差异性相对较小","融资的相对集中性"],"answer":"B","explain":"B选项正确，直接融资的特点之一是融资者有相对较强的自主性。"},{"id":"basics1-37","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"主板市场对发行人的稳定性、股本大小、盈利水平、最低市值等方面的要求标准较高，上市企业多为（）。","options":["创业型企业","大型成熟企业","创新型企业","成长型企业"],"answer":"B","explain":"B选项正确，主板市场上市企业多为大型成熟企业。"},{"id":"basics1-38","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"主要的商品期货种类不包括（）。","options":["能源化工期货","外汇期货","金属期货","农产品期货"],"answer":"B","explain":"B选项符合题意，外汇期货属于金融期货的品种。"},{"id":"basics1-39","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"资金需求者与资金初始供应者之间不发生直接信贷关系，而是由金融中介机构起桥梁作用，二者只与金融机构发生债权债务关系。这反映了间接融资的（）特点。","options":["资金获得的间接性","融资的相对集中性","融资信誉的较大差异性","可逆性"],"answer":"A","explain":"A选项正确，这反映了间接融资资金获得的间接性特点。"},{"id":"basics1-40","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"按发行流通性质划分，金融市场可分为（）。","options":["交易所市场","场外交易市场","发行市场","流通市场"],"answer":"CD","explain":"按发行流通性质分为一级市场（发行市场）和二级市场（流通市场）。"},{"id":"basics1-41","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"按照市场功能不同，资本市场可分为（）。","options":["场外市场","发行市场","场内市场","交易市场"],"answer":"BD","explain":"B、D选项正确，按照市场功能的不同，可以将资本市场划分为发行市场和交易市场。"},{"id":"basics1-42","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"风险管理的流程包括（）。","options":["风险的识别","风险的衡量","风险的应对","风险的监测、预警与报告"],"answer":"ABCD","explain":"A、B、C、D均属于风险管理的流程。"},{"id":"basics1-43","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"风险管理方法包括（）。","options":["风险控制","风险规避","风险分散","风险补偿"],"answer":"ABCD","explain":"A、B、C、D均属于风险管理方法。"},{"id":"basics1-44","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《证券法》，下列属于国务院证券监督管理机构有权采取的措施包括（）。","options":["查阅、复制与被调查事件有关的财产权登记、通讯记录等文件和资料","进入涉嫌违法行为发生场所调查取证","询问被调查事件当事人、涉嫌违法从业的所有人","对证券发行人、证券公司、证券服务机构、证券交易所、证券登记结算机构进行现场检查"],"answer":"ABCD","explain":"A、B、C、D均属于国务院证券监督管理机构有权采取的措施。"},{"id":"basics1-45","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《证券法》的规定，下列关于我国证券结算分级结算制度和结算参与人制度的说法，正确的有（）。","options":["证券公司是与证券登记结算机构进行证券和资金清算交收的主体，并承担相应的清算交收责任","证券登记结算机构根据清算交收结果为证券公司办理登记过户手续","在分级结算制度下，只有获得证券登记结算机构结算参与人资格的证券经营机构才能直接进入登记结算系统参与结算业务","通过对结算参与人实行准入制度，制订风险控制和财务指标要求，证券登记结算机构可以有效控制结算风险，维护结算系统安全"],"answer":"ACD","explain":"B选项错误，证券登记结算机构根据清算交收结果为投资者办理登记过户手续。"},{"id":"basics1-46","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据科创板的定位，下列属于其服务范围的领域或行业有（）。","options":["新一代信息技术领域","生物医药领域","主要从事金融业务的行业","新能源领域"],"answer":"ABD","explain":"C选项错误，禁止房地产和主要从事金融、投资类业务的企业在科创板上市。"},{"id":"basics1-47","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据中国证监会的规定进行注册备案的基金服务机构有（）。","options":["从事基金销售的机构","从事公开基金评价的服务机构","从事公开基金投资顾问业务的机构","从事基金销售支付的机构"],"answer":"ABCD","explain":"A、B、C、D均属于需要注册备案的基金服务机构。"},{"id":"basics1-48","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"股票价格指数被视为股市行情的指示器和经济景气变化的晴雨表。下列属于股票价格指数主要功能的有（）。","options":["作为指数衍生产品和其他金融创新的基础","作为投资业绩评价的标尺，提供一个股市投资的基准回报","由于股票价格短期内受到市场投资者情绪的带动而发生剧烈波动，因此股票价格指数准确反映了市场参与投资者情绪的变动方向和变动程度","为投资者和分析家研究、判断股市动态提供信息，便于对股票市场大势走向作出分析"],"answer":"ABD","explain":"C选项错误，股票价格指数综合反映一定时期内某一证券市场上股票价格的变动方向和变动程度。"},{"id":"basics1-49","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"股票价格指数的编制步骤包括（）。","options":["选择样本股","选定基期并以一定方法计算基期平均股价或市值","计算计算期平均股价或市值且不可作任何修正","指数化"],"answer":"ABD","explain":"C选项错误，计算计算期平均股价或市值，并作必要的修正。"},{"id":"basics1-50","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"关于地方政府一般债券的说法，正确的有（）。","options":["一般债券采用记账式固定利率付息形式","实行自发自还","偿债资金为政府性基金","债券资金收入列入一般公共预算管理"],"answer":"ABD","explain":"C选项错误，偿债资金为一般公共预算收入。"},{"id":"basics1-51","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"关于中国证监会对基金监管的主要职责，下列说法正确的有（）。","options":["制定有关证券投资基金活动监督管理的规章、规则，并行使审批、核准或者注册权","指导和监督基金行业协会的活动","组织行业交流，推动行业创新","监督检查基金信息的披露情况"],"answer":"ABD","explain":"C选项不属于中国证监会对基金监管的主要职责。"},{"id":"basics1-52","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"货币政策的传导机制包括（）。","options":["利率传导机制","信用传导机制","资产价格传导机制","汇率传导机制"],"answer":"ABCD","explain":"A、B、C、D均属于货币政策传导机制。"},{"id":"basics1-53","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"金融机构（不包括政策性银行）发行金融债券申报文件应包括（）。","options":["金融债券发行申请报告、募集说明书","发行人近5年经审计的财务报告及审计报告","发行公告或发行章程、承销协议","发行人关于本期债券偿债计划及保障措施的专项报告"],"answer":"ACD","explain":"B选项错误，应为发行人近3年经审计的财务报告及审计报告。"},{"id":"basics1-54","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"目前我国国债发行方式有（）。","options":["招标方式","承销方式","行政摊派","定向招募方式"],"answer":"ABD","explain":"C选项错误，1991年之前我国普通国债主要采用行政摊派的发行方式，目前不采用。"},{"id":"basics1-55","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"契约型基金的当事人包括（）。","options":["基金管理人","基金投资人","基金董事会","基金托管人"],"answer":"ABD","explain":"契约型基金的当事人包括基金管理人、托管人和投资人。"},{"id":"basics1-56","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"上市公司再融资的方式有（）。","options":["首次公开发行股票","定向增发","向不特定的对象公开募集股份","向原股东配售股份"],"answer":"BCD","explain":"A选项错误，首次公开发行股票属于首次融资，不是再融资。"},{"id":"basics1-57","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"属于金融衍生工具的是（）。","options":["远期合同","期货合同","投资合同","互换和期权合同"],"answer":"ABD","explain":"C选项错误，投资合同不属于金融衍生工具。"},{"id":"basics1-58","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"我国的证券登记结算制度主要包括（）。","options":["货银对付的交收制度","证券账户转借制度","分级结算制度和结算参与人制度","净额结算制度"],"answer":"ACD","explain":"B选项错误，我国实行证券实名制，不允许证券账户转借。"},{"id":"basics1-59","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"我国开放式基金的赎回方式采用（）。","options":["份额赎回","金额赎回","\"已知价\"赎回","\"未知价\"赎回"],"answer":"AD","explain":"A、D选项正确，一般采取“金额申购、份额赎回”原则，遵循“未知价”交易原则。"},{"id":"basics1-60","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列各项中，属于委托指令内容的有（）。","options":["委托数量、价格","证券代码","证券账户号码","买卖方向"],"answer":"ABCD","explain":"A、B、C、D均属于委托指令内容。"},{"id":"basics1-61","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列关于保荐制度的说法，正确的有（）。","options":["保荐制度主要内容包括：建立保荐机构资格核准和保荐代表人的登记管理制度","保荐制度的重点是明确保荐机构和保荐代表人的责任，并建立责任追究机制","保荐制度是指有资格的证券公司推荐符合条件的公司公开发行股票和上市，对发行人的申请文件和信息披露资料进行审慎核查，督导发行人规范运作","保荐人的保荐责任期仅为发行上市全过程"],"answer":"ABC","explain":"D选项错误，保荐人的保荐责任期包括发行上市全过程以及上市后的一段时期。"},{"id":"basics1-62","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列关于非公开发行公司债券的说法，正确的有（）。","options":["非公开发行公司债券，募集资金应当用于约定的用途；改变资金用途，应当履行募集说明书约定的程序","非公开发行的公司债券应当向专业投资者发行，不得采用广告、公开劝诱和变相公开方式，每次发行对象不得超过200人","非公开发行公司债券任何时候都不能改变资金用途","非公开发行公司债券，不得进行转让"],"answer":"AB","explain":"C选项错误，可以改变资金用途但需履行约定程序。D选项错误，可以申请在证券交易场所、证券公司柜台转让。"},{"id":"basics1-63","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列关于股票收益性的说法，正确的有（）。","options":["收益性是股票的基本特征之一","认购股票后，持有者即对发行公司享有经济权益，其实现形式是公司派发的股息、红利","资本利得是股票获取收益的来源之一","股东取得股份公司的收益仅取决于个人所持股票的多少"],"answer":"ABC","explain":"D选项错误，收益数量多少取决于股份公司的经营状况和盈利水平。"},{"id":"basics1-64","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列关于国际资金流动的说法，正确的有（）。","options":["国际长期资金流动是指期限在三年以上的资金的跨国流动","最传统的国际资金流动方式就是贸易资金的流动","国际长期资金流动主要有国际直接投资、国际间接投资和国际信贷三种形式","国际短期资金流动包括套利性资金、保值性资金以及投机性资金等的跨国流动"],"answer":"BCD","explain":"A选项错误，国际长期资金流动是指期限在1年以上的资金的跨国流动。"},{"id":"basics1-65","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列关于美国存托凭证（ADR）的说法，正确的有（）。","options":["存托凭证由J.P.摩根首创","上市交易的ADR不须经过SEC注册","存托凭证能避开直接发行股票和债券的相关法律要求，上市手续简单，发行成本低","由于市场容量大，在美国发行ADR的外国公司能在短期内筹集到大量的外汇资金"],"answer":"ACD","explain":"B选项错误，上市交易的ADR须经美国证券交易委员会（SEC）注册。"},{"id":"basics1-66","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列关于中国香港金融市场的说法，错误的有（）。","options":["2000年，香港联合交易所和香港期货交易所实行股份化，并与香港结算所合并于单一控股公司香港交易所旗下","2009年7月，中国香港政府推出政府债券计划的目的是筹集必要资金弥补公共服务支出缺口","中国香港自2003年开放人民币业务以来，逐步成为全球人民币离岸市场中心","在中国香港，基础货币的组成部分包括未偿还外汇基金票据和债券总额"],"answer":"AB","explain":"A选项错误，应为香港商品交易所。B选项错误，主要目的是提供无风险债券种类，促进中国香港债券市场发展。"},{"id":"basics1-67","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列可能导致股票供求变动的特殊原因包括（）。","options":["履行某种承诺（如期权到期行权）而买进股票","由于财产清算等原因股票持有人卖出股票","为了争夺或保持公司控制权而买入股票","股票持有人因流动性挤兑而卖出股票"],"answer":"ABCD","explain":"A、B、C、D均属于可能导致股票供求变动的特殊原因。"},{"id":"basics1-68","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列属于基础设施公募REITs的要求的有（）。","options":["基金通过资产支持证券和项目公司等特殊目的载体取得基础设施项目完全所有权或经营权利","基金管理人主动运营管理基础设施项目，以获取基础设施项目租金、收费等稳定现金流为主要目的","80%以上基金资产投资于基础设施资产支持证券，并持有其全部份额","采取封闭式运作，收益分配比例不低于合并后基金年度可供分配金额的60%"],"answer":"ABC","explain":"D选项错误，收益分配比例不低于合并后基金年度可供分配金额的90%。"},{"id":"basics1-69","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列属于金融期货交易制度的有（）。","options":["集中交易制度","标准化的期货合约和对冲机制","保证金制度","结算所和无负债结算制度"],"answer":"ABCD","explain":"A、B、C、D均属于金融期货交易制度。"},{"id":"basics1-70","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列属于金融市场的有（）。","options":["房地产市场","货币市场","债券市场","股权投资市场"],"answer":"BCD","explain":"A选项不符合题意，房地产市场不属于金融市场。"},{"id":"basics1-71","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"现代信用风险分析的构成要素包括（）。","options":["违约概率","违约损失率","违约时的风险暴露","违约时间"],"answer":"ABC","explain":"D选项错误，违约时间不是现代信用风险分析的构成要素。"},{"id":"basics1-72","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"影响我国金融市场的主要因素有（）。","options":["经济因素","技术因素","心理因素","政策因素"],"answer":"ABCD","explain":"A、B、C、D均属于影响我国金融市场的主要因素。"},{"id":"basics1-73","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"与个人投资者相比，机构投资者的特点包括（）。","options":["投资结构规范化","投资管理专业化","投资灵活性强","投资资金规模化"],"answer":"BD","explain":"A选项错误，应为投资结构组合化。C选项错误，机构投资者投资灵活性相对较弱。"},{"id":"basics1-74","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"债券报价的主要方式包括（）。","options":["公开报价","对话报价","净额报价","双边报价"],"answer":"ABD","explain":"C选项错误，债券买卖交易中有公开报价、对话报价、双边报价和小额报价四种报价方式。"},{"id":"basics1-75","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"债券成交竞价原则的主要内容是（）。","options":["时间优先","价格优先","数量优先","客户委托优先"],"answer":"ABD","explain":"C选项错误，数量优先并非债券成交竞价原则。"},{"id":"basics1-76","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司声誉风险管理应遵循以下（）原则。","options":["全程全员原则","预防第一原则","审慎管理原则","快速响应原则"],"answer":"ABCD","explain":"A、B、C、D均属于证券公司声誉风险管理应遵循的原则。"},{"id":"basics1-77","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司压力测试可采用的方法有（）。","options":["历史情景分析法","历史情景和假设情景相结合的分析方法","假设情景分析法","敏感性分析法"],"answer":"ABCD","explain":"A、B、C、D均属于证券公司压力测试可采用的方法。"},{"id":"basics1-78","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"中央银行的三大职能包含（）。","options":["发行的银行","银行的银行","政府的银行","盈利性商业银行"],"answer":"ABC","explain":"D选项错误，中央银行不以盈利为目的。"},{"id":"basics1-79","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"中证中小投资者服务中心的维权服务主要包括（）。","options":["支持诉讼","股东诉讼","管理和公布市场信息","证券特别代表人诉讼"],"answer":"ABD","explain":"C选项错误，管理和公布市场信息属于证券交易所的职能。"},{"id":"basics1-80","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"按选择权的性质划分，金融期权可以分为股权类期权、利率期权、货币期权、金融期货期权、互换期权。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。按照选择权的性质划分，金融期权可以分为认购期权和认沽期权。"},{"id":"basics1-81","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"存款利息是资产时间价值的一种体现。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics1-82","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"法定存款准备金率越低，银行吸收的存款用于贷款的数额就越少。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。法定准备金率越高，银行吸收的存款用于贷款的数额就越少。"},{"id":"basics1-83","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"根据委托订单的数量，委托指令可分为整数委托、零数委托和批量委托。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。根据委托订单的数量，委托指令可分为整数委托和零数委托。"},{"id":"basics1-84","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"公募REITs与其他公募基金一样，能够申购赎回。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。基础设施基金采取封闭式运作，不开通申购赎回。"},{"id":"basics1-85","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"公司（企业）发行长期公司（企业）债券所募集资金用于长期资本需求，发行短期债券所募资金用于弥补流动性资金短缺。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics1-86","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"公司支付清算费用，员工工资和社会保险费用，缴付所欠税款，清偿公司债务，如还有剩余资产，再按照比例分配给各股东。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics1-87","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"监管资本是按照监管当局的要求计算的资本，金融机构应满足监管的最低要求。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics1-88","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"金融风险内涵包括：任何金融产品是风险和收益的组合，风险是与收益相匹配的，投资是以风险换收益。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics1-89","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"金融期货交易和普通远期交易之间存在一定的区别和联系，其中，金融期货交易是标准化交易，远期交易的内容可协商确定，但是由于两者都实行保证金制度和每日结算制度，交易者均以交易所（或期货清算公司）为交易对手，基本不用担心交易违约风险。（）","options":["正确","错误"],"answer":"B","explain":"本题表述错误。远期交易通常不存在保证金制度和每日结算制度，存在一定的交易对手违约风险。"},{"id":"basics1-90","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"金融市场按照交易是即期还是未来交割，分为现货市场和衍生品市场。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics1-91","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"金融衍生工具极强的派生能力和高度的杠杆性使其发展速度十分惊人，根据国际清算银行的金融衍生产品统计报告，金融衍生工具以场外交易为主。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics1-92","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"科创板包含了高新技术产业和战略性新兴产业。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics1-93","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"可交换债券的股份来源是发行人持有的其他公司已发行在外的股份，而可转换债券的股份来源通常是发行人本身未来将发行的新股。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics1-94","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"敏感性分析是一个动态的分析过程，它将风险因子的变化视为外生的，没有研究风险因子自身变化的概率分布，忽略了这些风险因子自身发生变化的可能性，而将分析集中于金融工具价值随给定风险因子变化而变化的程度。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。敏感性分析是一个静态的分析过程。"},{"id":"basics1-95","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"目前，我国的封闭式基金于每个交易日估值，不晚于下一交易日披露基金份额净值。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。封闭式基金和定期开放式基金的封闭期每个交易日都进行估值，但每周披露一次基金份额净值。"},{"id":"basics1-96","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"目前，我国证券交易所一般采用两种竞价方式集合竞价方式和连续竞价方式。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics1-97","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"内部控制是证券公司操作风险管理的主要手段。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics1-98","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"通常期限在1年以下（含1年）的国债为附息国债；期限在1年以上的为贴现国债。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。通常期限在1年以下（含1年）的国债为贴现国债；期限在1年以上的国债为附息国债。"},{"id":"basics1-99","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"养老目标基金是指以追求养老资产的长期稳健增值为目的，鼓励投资人长期持有，采用成熟的资产配置策略，合理控制投资组合波动风险的私募基金。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。养老目标基金是公开募集证券投资基金，并非私募基金。"},{"id":"basics1-100","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"一般来讲，影响股票投资价值的外部因素主要包括宏观经济因素、行业因素及市场因素。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics1-101","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"在我国设立证券公司，必须由国务院监督管理局核准。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。设立证券公司必须经国务院证券监督管理机构审查批准。"},{"id":"basics1-102","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"在证券交易所内，证券竞价原则的主要内容是\"三先\"，即价格优先、时间优先、机构优先。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。竞价原则的主要内容是价格优先、时间优先、客户委托优先。"},{"id":"basics1-103","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"债券的托管量等于债券的总量。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。债券托管量等于已经发行但尚未到期的债券总量。"},{"id":"basics1-104","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"正常情况下，利率债的信用风险很小。","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics1-105","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"证券存续期内，该证券的评级机构应至少每半年出具一次定期跟踪评级报告。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。应至少每年出具一次定期跟踪评级报告。"},{"id":"basics1-106","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"证券投资咨询机构及其从业人员从事证券服务业务可与委托人约定分享证券投资收益或者分担证券投资损失。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券投资咨询机构及其从业人员不得与委托人约定分享证券投资收益或者分担证券投资损失。"},{"id":"basics1-107","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"直接融资和间接融资比例反映了一国金融体系配置的效率是否与实体经济相匹配。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics1-108","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"直接融资与间接融资的主要区别是资金供求双方是否直接产生债权债务关系。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics1-109","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"中国证券业协会采取会员制的组织形式，是证券业的自律组织，是社会团体法人，证券公司应当加入中国证券业协会。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics1-110","subject":"basics","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】2023年2月1日，某票面利率5%、面值100元、每年付息1次的债券，T+0成交在净价101元。该只债券上次付息为2022年12月31日。请根据上述背景信息回答以下问题。\n\n【问题】要求1 成交当天该只债券的应计利息（按实际天数/360）约为（）。","options":["0.43元","0.12元","0.56元","1.12元"],"answer":"A","explain":"累计天数=31天（1月），累计利息=100×5%×31/360=0.43元。"},{"id":"basics1-111","subject":"basics","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】2023年2月1日，某票面利率5%、面值100元、每年付息1次的债券，T+0成交在净价101元。该只债券上次付息为2022年12月31日。请根据上述背景信息回答以下问题。\n\n【问题】要求2 该只债券的实际支付价格为（）。","options":["101.43元","100.66元","101.12元","100.44元"],"answer":"A","explain":"实际支付价格=净价+应计利息=101+0.43=101.43元。"},{"id":"basics1-112","subject":"basics","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】2021年，中国期货市场成交75.14亿手（单边，下同）和581.2万亿元。全球期货市场成交625.84亿手，中国期货市场成交量占全球期货市场总成交量的12%。请根据材料回答下列问题。\n\n【问题】要求1 下列不属于商品期货的是（）。","options":["能源化工期货","金属期货","农产品期货","金融期货"],"answer":"D","explain":"D选项符合题意，金融期货与商品期货并列，不属于商品期货。"},{"id":"basics1-113","subject":"basics","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】2021年，中国期货市场成交75.14亿手（单边，下同）和581.2万亿元。全球期货市场成交625.84亿手，中国期货市场成交量占全球期货市场总成交量的12%。请根据材料回答下列问题。\n\n【问题】要求2 下列属于我国商品期货交易所的有（）。","options":["上海期货交易所","广州期货交易所","郑州商品交易所","大连商品交易所"],"answer":"ABCD","explain":"A、B、C、D均属于我国商品期货交易所。"},{"id":"basics1-114","subject":"basics","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】2021年股票市场表现良好，投资者成某的朋友购买的基金普遍都获得了20%以上的收益，成某也希望购买基金来赚钱，他在某网站上看到A基金的介绍如下，基金净值为4.075，起购金额1万元，交易日开放申购赎回、管理费率1.5%（每年）、托管费率0.25%（每年）、最高认购费率1.2%（前端）、最高申购费率1.5%（前端）、最高赎回费率1.5%（前端）、业绩比较基准60%×中证1000指数收益率+40%×上证国债指数收益率。2020年债券基金、理财基金和货币基金收益一般不超过6%。根据该案例，回答以下问题。\n\n【问题】要求1 成某的朋友2021年购买的基金最可能为（）。","options":["债券型基金","股票型基金","货币型基金","纯债型基金"],"answer":"B","explain":"由题干知，2021年债券基金、理财基金和货币基金收益一般不超过6%，而成某的朋友购买的基金获得了20%以上的收益，所以最有可能是股票型基金。"},{"id":"basics1-115","subject":"basics","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】2021年股票市场表现良好，投资者成某的朋友购买的基金普遍都获得了20%以上的收益，成某也希望购买基金来赚钱，他在某网站上看到A基金的介绍如下，基金净值为4.075，起购金额1万元，交易日开放申购赎回、管理费率1.5%（每年）、托管费率0.25%（每年）、最高认购费率1.2%（前端）、最高申购费率1.5%（前端）、最高赎回费率1.5%（前端）、业绩比较基准60%×中证1000指数收益率+40%×上证国债指数收益率。2020年债券基金、理财基金和货币基金收益一般不超过6%。根据该案例，回答以下问题。\n\n【问题】要求2 成果如果购买A基金，他需要一次性支付的费用有（）。","options":["认购费","托管费","申购费","管理费"],"answer":"C","explain":"投资者在办理开放式基金申购时，一般需要缴纳申购费，申购费是需要在购买基金时一次性支付的费用。"},{"id":"basics1-116","subject":"basics","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】2021年股票市场表现良好，投资者成某的朋友购买的基金普遍都获得了20%以上的收益，成某也希望购买基金来赚钱，他在某网站上看到A基金的介绍如下，基金净值为4.075，起购金额1万元，交易日开放申购赎回、管理费率1.5%（每年）、托管费率0.25%（每年）、最高认购费率1.2%（前端）、最高申购费率1.5%（前端）、最高赎回费率1.5%（前端）、业绩比较基准60%×中证1000指数收益率+40%×上证国债指数收益率。2020年债券基金、理财基金和货币基金收益一般不超过6%。根据该案例，回答以下问题。\n\n【问题】要求3 最可能对A基金收取托管费的机构有（）。","options":["证券交易所","基金销售机构","商业银行","基金公司"],"answer":"C","explain":"在我国，基金托管人只能由依法设立并取得基金托管资格的商业银行或其他金融机构承担。"},{"id":"basics1-117","subject":"basics","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】假定商业银行法定存款准备金率为20%，超额存款准备金率为5%，并且实行客户一切款项均存入商业银行的非现金结算制度，客户李某将10,000元现金存入商业银行，一段时间以后，中央银行取消了超额存款准备金率和非现金结算制度，现金比率定为5%，这时客户王某将30,000元现金存入商业银行。不考虑其他相关影响因素，请根据上述背景信息回答以下问题。\n\n【问题】要求1 在中央银行货币政策调整前，李某的原始存款货币乘数为（）。","options":["20","4","6.67","5"],"answer":"B","explain":"完整的货币乘数公式为m=(c+1)/(c+r+e)。因为没有考虑到现金比率，c=0，因此m=1/(20%+5%)=4。"},{"id":"basics1-118","subject":"basics","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】假定商业银行法定存款准备金率为20%，超额存款准备金率为5%，并且实行客户一切款项均存入商业银行的非现金结算制度，客户李某将10,000元现金存入商业银行，一段时间以后，中央银行取消了超额存款准备金率和非现金结算制度，现金比率定为5%，这时客户王某将30,000元现金存入商业银行。不考虑其他相关影响因素，请根据上述背景信息回答以下问题。\n\n【问题】要求2 在中央银行货币政策调整后，王某的原始存款可以被商业银行创造出（）万元货币供给。","options":["12.6","12","20","15"],"answer":"A","explain":"货币政策调整后，取消了超额存款准备金率，e=0。现金比率c=5%，法定存款准备金率r=20%，m=(5%+1)/(5%+20%+0)=4.2。王某原始存款为3万元，可创造货币=3万×4.2=12.6万元。"},{"id":"basics1-119","subject":"basics","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】假定商业银行法定存款准备金率为20%，超额存款准备金率为5%，并且实行客户一切款项均存入商业银行的非现金结算制度，客户李某将10,000元现金存入商业银行，一段时间以后，中央银行取消了超额存款准备金率和非现金结算制度，现金比率定为5%，这时客户王某将30,000元现金存入商业银行。不考虑其他相关影响因素，请根据上述背景信息回答以下问题。\n\n【问题】要求3 如不考虑其他因素影响，关于中央银行调整货币政策的措施与效果，下列说法正确的有（）。","options":["取消非现金结算制度将使货币乘数增加","降低超额存款准备金率将使货币乘数增加","提高现金比率将使货币乘数减小","提高法定存款准备金率将使货币乘数减小"],"answer":"BCD","explain":"A选项错误，取消非现金结算制度说明允许客户使用现金结算，提现率增加将使货币乘数减少。B、C、D选项正确。"}]},{"id":"basics2","subject":"basics","name":"金融基础 · 押题卷二","stats":{"单选":30,"多选":50,"判断":30,"案例":0},"questions":[{"id":"basics2-0","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"“金融加速器”理论认为（）。","options":["金融市场只是被动地反映实体经济活动的运行状况","货币供应量的变化影响名义变量而不影响实际变量，货币经济只是覆盖实体经济上的一层面纱","金融市场上资金借贷双方之间的信息不对称导致了外部融资的代理成本等摩擦，这些摩擦及其随后产生的效应会放大对实体经济产出的动态影响","未来的不确定性是货币经济的主要特征，通过利率对投资的诱导等作用，货币能影响实体经济"],"answer":"C","explain":"C选项符合题意，“金融加速器”理论认为，金融市场上资金借贷双方之间的信息不对称导致了外部融资的代理成本等摩擦，这些摩擦会产生“加速器”效应并放大对实体经济产出的动态影响。"},{"id":"basics2-1","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"2018年11月5日，国家主席习近平在首届中国国际进口博览会开幕式上宣布，将在上海证券交易所设立科创板并试点（），支持上海国际金融中心和科技创新中心建设。","options":["申报制","注册制","审批制","核准制"],"answer":"B","explain":"B选项正确，将在上海证券交易所设立科创板并试点注册制。"},{"id":"basics2-2","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《上海证券交易所科创板企业发行上市申报及推荐暂行规定》，科创板重点服务的新能源领域不包括（）。","options":["大型火电","高效储能","先进核电","高效光电光热"],"answer":"A","explain":"A选项符合题意，新能源领域主要包括先进核电、大型风电、高效光电光热、高效储能及相关服务等，不包括大型火电。"},{"id":"basics2-3","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据2020年3月正式实施的《证券法》，从事（）服务业务，应当经国务院证券监督管理机构核准。","options":["资产评估","证券投资咨询","财务顾问","资信评级"],"answer":"B","explain":"《证券法》规定，从事证券投资咨询服务业务，应当经国务院证券监督管理机构核准。"},{"id":"basics2-4","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"关于全球金融市场的说法，错误的是（）。","options":["伦敦外汇市场以非居民交易为主，反映出伦敦外汇市场的高度国际化","纽约联邦储备银行每日计算和发布成交额加权的有效联邦基金利率","2007年，美国证券交易商协会与纽约证券交易所监管委员会合并，成立金融业监管局，是证券业非自律性组织","目前，伦敦证券交易所集团业务涵盖伦敦证交所、意大利证交所、加拿大蒙特利尔证交所以及泛欧股票和衍生品平台Turquoise"],"answer":"C","explain":"2007年，美国证券交易商协会与纽约证券交易所监管委员会合并，成立金融业监管局，是证券业自律性组织（C选项错误）。"},{"id":"basics2-5","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"国际长期资金流动的方式不包括（）。","options":["国际直接投资","投机性资金的流动","国际间接投资","国际信贷"],"answer":"B","explain":"B选项符合题意，投机性资金的流动属于国际短期资金流动。"},{"id":"basics2-6","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"机构投资者有助于实现社会保障体系与宏观经济的良性互动发展的基础是（）。","options":["将养老金投资于期货产品","基金分级制的养老制度","以企业年金为主的企业补充养老金在内的多层次养老保障体系的构建","现收现付的公共养老制度"],"answer":"C","explain":"C选项正确，建立起以包括企业年金为主的企业补充养老金和个人自愿储蓄性养老金在内的多层次养老保障体系，是我国社会保障体系改革的方向。"},{"id":"basics2-7","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"基金管理人会针对不同的基金类型、不同的认购金额设置不同的（）。","options":["认购方式","认购费率","认购代理","认购要件"],"answer":"B","explain":"B选项正确，基金管理人会针对不同的基金类型、不同的认购金额设置不同的认购费率。"},{"id":"basics2-8","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"将整个金融机构或资产组合置于某一特定压力情景之下，然后测试该金融机构或资产组合在这些关键市场变量突变压力下的表现状况，以考虑它们是否能经受得起这种市场的突变，是指（）。","options":["压力测试","压力情景","敏感性分析","情景分析"],"answer":"A","explain":"A选项正确，压力测试是指将整个金融机构或资产组合置于某一特定压力情景之下，然后测试其表现状况。"},{"id":"basics2-9","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"交易者买入看涨期权，是因为其预期基础金融工具的价格在合约期限内将会（）。","options":["上涨","下跌","不变","难以判断"],"answer":"A","explain":"A选项正确，交易者买入认购期权，是因为他预期基础金融工具的价格在合约期限内将会上涨。"},{"id":"basics2-10","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"开放式基金申购、赎回的原则是（）。","options":["份额申购、金额赎回","份额申购、份额赎回","金额申购、金额赎回","金额申购、份额赎回"],"answer":"D","explain":"D选项正确，开放式基金的申购、赎回一般采取“金额申购、份额赎回”原则。"},{"id":"basics2-11","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"李某、王某研究全球金融市场与金融体系，他们认为，全球金融体系主要指金融资本在国际的存在形式和金融资本流动形式的总和、英国、美国和中国香港金融市场发达，其中，伦敦拥有全球最大的外汇市场，美国金融业居全球霸主地位，中国香港在联结中国内地与国际金融市场方面起着重要作用。下列由李某给出的伦敦外汇市场的特点，错误的是（）。","options":["以居民非批发性交易为主","以外币交易为主","以非居民交易为主","以外汇衍生品交易为主"],"answer":"A","explain":"A选项错误，伦敦外汇市场以金融机构批发性交易为主，并非以居民非批发性交易为主。"},{"id":"basics2-12","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"某投资者投资100000.00元认购本基金，对应认购费率为1.2%，在募集期间产生利息50.00元，则其基金认购份额为（）份。","options":["78964.35","98864.23","85664.57","67864.98"],"answer":"B","explain":"净认购金额=100000/(1+1.2%)=98814.23元，认购份额=(98814.23+50)/1=98864.23份。"},{"id":"basics2-13","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"区域性股权市场是为其所在（）级行政区域内中小微企业证券非公开发行、转让及相关活动提供设施与服务的场所。","options":["国家","县","省","市"],"answer":"C","explain":"C选项正确，区域性股权市场是为其所在省级行政区域内中小微企业证券非公开发行、转让及相关活动提供设施与服务的场所。"},{"id":"basics2-14","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"属于我国证券市场监管体系和自律管理体系组成的部分机构是（）。","options":["中国证券登记结算有限公司","分支证监局","中国银行保险业协会","证券投资者保护基金"],"answer":"D","explain":"D选项正确，我国证券市场逐步形成了以国务院证券监督管理机构、派出机构、证券交易所、行业协会和证券投资者保护基金为一体的监管体系和自律管理体系。"},{"id":"basics2-15","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"属于远期合约的衍生工具是（）。","options":["远期股票期权","远期利率协议","远期股票指数期货","远期货币期货"],"answer":"B","explain":"B选项正确，远期利率协议属于金融远期合约。"},{"id":"basics2-16","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"投资者保护机构可以作为诉讼代表人，按照（）的原则，依法为受害投资者提起民事损害赔偿诉讼。","options":["默示退出、明示加入","默示退出、默示加入","明示退出、默示加入","明示退出、明示加入"],"answer":"C","explain":"C选项正确，按照“明示退出、默示加入”的原则。"},{"id":"basics2-17","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"投资者在开放式基金合同生效后，申请购买基金份额的行为通常被称为基金的（）。","options":["买入","申购","认购","交易"],"answer":"B","explain":"B选项正确，投资者在开放式基金合同生效后，申请购买基金份额的行为通常称为基金的申购。"},{"id":"basics2-18","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列各项中，属于国际金融监管机构的是（）。","options":["世界银行","世界贸易组织","国际货币基金组织","国际证监会组织"],"answer":"D","explain":"D选项正确，国际金融监管体系包括巴塞尔银行监管委员会、国际证监会组织、国际保险监督官协会等。"},{"id":"basics2-19","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于非公开募集证券投资基金基本规范的说法，错误的是（）。","options":["担任非公开募集基金的基金管理人，应当按照规定向中国证券投资基金业协会履行登记手续","在我国，单只非公开募集证券投资基金合格投资者累计不得超过200人","除基金合同另有约定外，非公开募集基金应当由基金托管人托管","私募基金不可采用公司型组织形式"],"answer":"D","explain":"D选项错误，私募基金可采用公司型、合伙型、契约型三种组织形式。"},{"id":"basics2-20","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于股利政策的说法，错误的是（）。","options":["股利政策是公司资本管理事项中经常要涉及的一个与股票相关的概念","股利政策体现了公司的发展战略和经营思路","稳定可预测的股利政策是股份公司稳健经营的重要指标","股利政策与股东利益最大化不相关"],"answer":"D","explain":"D选项错误，股利政策与股东利益最大化密切相关。"},{"id":"basics2-21","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于股票合并的说法，错误的是（）。","options":["股票合并会影响每位股东所持股东权益占公司全部股东权益的比重","股票合并是将若干股票合并为1股","股票合并又称并股","股票合并常见于低价股"],"answer":"A","explain":"A选项错误，股票合并并不改变每位股东所持股东权益占公司全部股东权益的比重。"},{"id":"basics2-22","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于股票价格指数的说法，错误的是（）。","options":["股票价格指数一般由一些有影响力的机构编制，并定期及时发布","股票价格指数是衡量整个市场价格水平的一个总的尺度标准，能够观察股票市场的总体变化情况","股票价格指数是观测经济形势和周期状况的参考指标，被视为经济景气变化的晴雨表","股票价格指数是用以反映整个市场上各种股票市场价格的总体水平及其变动情况的指标，因此股票价格指数上涨则意味着市场所有股票价格上涨"],"answer":"D","explain":"D选项错误，股票价格指数上涨并不意味着市场所有股票价格上涨。"},{"id":"basics2-23","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于会计师事务所从事相关业务的做法，错误的是（）。","options":["为乙公司到全国股转系统公司挂牌出具财务报表审计报告，按照从事证券服务业务相关规定向中国证监会和国务院有关主管部门备案","为丙上市公司的控股子公司（资产总额为丙上市公司最近一期经审计合并财务报表对应项目金额的10%）出具内部控制审计报告，未按照从事证券服务业务相关规定向中国证监会和国务院有关主管部门备案","为丁证券公司资产管理产品出具验资报告，未按照从事证券服务业务相关规定向中国证监会和国务院有关主管部门备案","为甲公司股票的发行、上市出具财务报表审计报告，按照从事证券服务业务相关规定向中国证监会和国务院有关主管部门备案"],"answer":"C","explain":"C选项错误，为证券公司及其资产管理产品制作、出具验资报告，应当按照规定向中国证监会和国务院有关主管部门备案。"},{"id":"basics2-24","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于基金资产估值需考虑的估值频率、估值方法的一致性及公开性等因素的说法，错误的是（）。","options":["封闭式基金每周估值一次","我国的开放式基金于每个交易日估值，一般不迟于T+1交易日公告份额净值","基金的估值方法需要在法定募集文件中公开披露","基金一般都按照固定的时间间隔对基金资产进行估值"],"answer":"A","explain":"A选项错误，封闭式基金和定期开放式基金的封闭期每个交易日都进行估值，但每周披露一次基金份额净值。"},{"id":"basics2-25","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于债券评级的说法，错误的是（）。","options":["信用等级评审会议的参会评审委员不得少于5人","评级项目组至少由两名评级分析人员组成","委托人同时委托多家证券评级机构对同一评级对象进行评级，受委托的证券评级机构应当同时对外公布评级结果","评级机构受理复评申请后应当从尽职调查开始重新执行评级程序"],"answer":"D","explain":"D选项错误，证券评级机构受理复评申请后，项目组根据评级对象提供的补充资料修改评级报告，并非从尽职调查开始重新执行评级程序。"},{"id":"basics2-26","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于证券公司次级债的发行条件的说法，错误的是（）。","options":["次级债应以现金或中国证监会认可的其他形式借入或融入","证券公司次级债对发行主体财务状况没有要求","长期次级债计入净资本的数额不得超过净资本（不含长期次级债累计计入净资本的数额）的50%","借入或募集资金有合理用途"],"answer":"B","explain":"B选项错误，净资本与负债的比例、净资产与负债的比例等各项风险控制指标不触及预警标准是对发行主体的财务要求。"},{"id":"basics2-27","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列业务中，不属于财产保险公司业务的是（）。","options":["责任保险","海洋开发保险","信用保证保险","变额年金"],"answer":"D","explain":"D选项符合题意，变额年金属于人身保险公司的业务类型。"},{"id":"basics2-28","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"以下不属于基金的当事人（）。","options":["基金管理人","基金份额持有人","基金托管人","基金销售机构"],"answer":"D","explain":"D选项符合题意，基金销售机构属于基金服务机构，不属于基金的当事人。"},{"id":"basics2-29","subject":"basics","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"以下不属于我国国际债券主要品种的是（）。","options":["国家债券","金融债券","公司债券","次级债券"],"answer":"D","explain":"D选项符合题意，我国国际债券主要品种有政府债券、金融债券和公司债券。"},{"id":"basics2-30","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"银行间债券市场中长期债券信用评级等级划分为（）。","options":["四等九级","三等六级","三等九级","四等六级"],"answer":"C","explain":"C选项正确，银行间债券市场中长期债券信用评级等级划分为三等九级。"},{"id":"basics2-31","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"影响股票投资价值的外部因素是（）。","options":["盈利水平","股份分割","市场因素","并购重组"],"answer":"C","explain":"C选项正确，影响股票价值的外部因素有：宏观经济因素、行业因素、市场因素。"},{"id":"basics2-32","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"影响金融市场长期走势的最主要因素是（）。","options":["宏观经济运行","宏观经济政策","投资者心理因素","国际经济环境"],"answer":"A","explain":"A选项正确，宏观经济因素是影响金融市场长期走势的最重要因素。"},{"id":"basics2-33","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"在全球金融体系中不属于存款吸收机构的是（）。","options":["商业银行","抵押贷款银行","证券交易所","储蓄银行"],"answer":"C","explain":"C选项符合题意，证券交易所不属于存款吸收机构。"},{"id":"basics2-34","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"在我国，设立证券公司必须经过（）审查批准。","options":["人民银行","国务院证券监督管理机构","财政部","证券业协会"],"answer":"B","explain":"B选项正确，设立证券公司必须经国务院证券监督管理机构审查批准。"},{"id":"basics2-35","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"证券投资基金是通过国内公开发售（）募集资金。","options":["理财产品","有价证券","企业债券","基金份额"],"answer":"D","explain":"D选项正确，证券投资基金通过公开发售基金份额等筹集资金。"},{"id":"basics2-36","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"只能用于基金、国债及其他债券的认购及交易的账户是（）。","options":["债券账户","基金账户","资金账户","股票账户"],"answer":"B","explain":"B选项正确，基金账户只能用于基金、国债及其他债券的认购及交易。"},{"id":"basics2-37","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"中国证券业协会的性质是（）。","options":["监管组织","管理机构","自律性组织","审批机构"],"answer":"C","explain":"C选项符合题意，中国证券业协会是证券业自律性组织。"},{"id":"basics2-38","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"中央银行是发行的银行主要体现在（）。","options":["是全国唯一有权发行货币的机构","代理国库收支","代理国家债券的发行","对政府提供信贷"],"answer":"A","explain":"A选项正确，“发行的银行”是指中央银行垄断货币发行权。"},{"id":"basics2-39","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"中证指数有限公司编制沪深300指数，采用的方法是（）。","options":["派许加权法","算术平均法","几何平均法","B-S 模型法"],"answer":"A","explain":"A选项正确，沪深300指数采用派许加权综合价格指数公式进行计算。"},{"id":"basics2-40","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"2018年4月28日，中国证监会正式发布《外商投资证券公司管理办法》，办法修订内容主要涉及（）。","options":["逐步放开合资证券公司业务范围","完善境外股东条件","明确外资持有上市和非上市两类证券公司股权的比例不同","允许外资控股合资证券公司"],"answer":"ABD","explain":"C选项错误，应为统一外资持有上市和非上市两类证券公司股权的比例。"},{"id":"basics2-41","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"道·琼斯股价平均数主要包括（）。","options":["道·琼斯公用事业股价平均数","道·琼斯工业股价平均数","道·琼斯能源业股价平均数","道·琼斯运输业股价平均数"],"answer":"ABD","explain":"C选项错误，道·琼斯股价平均指数包括工业、运输业、公用事业等五组指标。"},{"id":"basics2-42","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《企业债券管理条例》，下列关于企业债券发行的条款设计要求的说法，正确的有（）。","options":["企业发行企业债券的总面额不得大于该企业的自有资产净值的80%","没有对企业债券的期限作出明确的规定，实务操作中一般为1年以上","企业债券的发行期限一般为3~10年，以5年为主","发行企业债券，担保并非强制性要求"],"answer":"BD","explain":"A选项错误，企业发行企业债券的总面额不得大于该企业的自有资产净值。C选项错误，企业债券的发行期限一般为3~20年，以7年为主。"},{"id":"basics2-43","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据国债的偿还期限，可以把国债分为（）。","options":["赤字国债","长期国债","中期国债","短期国债"],"answer":"BCD","explain":"A选项错误，赤字国债是按资金用途分类。按偿还期限分类，国债分为短期国债、中期国债和长期国债。"},{"id":"basics2-44","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据科创板定位，保荐机构优先推荐的科技创新企业所属的领域包括（）。","options":["高端装备领域","新一代信息技术领域","现代服务领域","新材料领域"],"answer":"ABD","explain":"C选项错误，现代服务领域不属于科创板重点服务的行业领域。"},{"id":"basics2-45","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据债券券面的形态不同，可以分为（）。","options":["实物式债券","凭证式债券","记账式债券","电子式债券"],"answer":"ABC","explain":"D选项错误，根据债券券面形态可以分为实物债券、凭证式债券和记账式债券。"},{"id":"basics2-46","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"股份公司解散或破产进行清算时，下列关于对公司剩余资产分配的顺序的说法，正确的有（）。","options":["优先股票股东在普通股票股东之前","优先股票股东在债权人之后","优先股票股东在债权人之前","优先股票股东在普通股票股东之后"],"answer":"AB","explain":"A、B选项正确，优先股股东对公司剩余财产的权利先于普通股股东，但在债权人之后。"},{"id":"basics2-47","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"关于金融市场的经济内涵，下列说法错误的有（）。","options":["金融市场是以货币为交易对象而形成的供求关系和交易机制的总和","金融市场是创造和交易金融资产的市场","金融市场属于要素市场的一种","金融市场的参与者主要有在形的固定场所进行金融资产交易"],"answer":"AD","explain":"A选项错误，金融市场是以金融资产为交易对象。D选项错误，现代金融市场往往是无形的市场。"},{"id":"basics2-48","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"国务院再次出台的资本市场指导性文件新\"国九条\"中主要内容包括下列的（）。","options":["加大退市监管力度，进一步严格强制退市标准","加强证券基金机构监管，完善对衍生品、融资融券等重点业务的监管制度","大力推动中长期资金入市，持续壮大长期投资力量","鼓励更多的量化投资者进入证券机构进行交易"],"answer":"ABC","explain":"D选项错误，新“国九条”中未提及鼓励更多的量化投资者进入证券机构进行交易。"},{"id":"basics2-49","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"基础设施公募REITs的申请文件包括（）","options":["资产支持证券材料","基金管理材料","基金合同草案","招募说明书"],"answer":"ABCD","explain":"A、B、C、D均属于基础设施公募REITs的申请文件。"},{"id":"basics2-50","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"基金管理人运作基金财产进行证券投资，不得出现的情形包括（）。","options":["基金中基金持有其他单只基金，其市值超过基金资产净值的20%","基金财产参与股票发行申购，单只基金所申报的金额超过该基金的总资产","基金财产参与股票发行申购，单只基金所申报的股票数量超过拟发行股票公司本次发行股票的总量","一只基金持有一家公司发行的证券，其市值为该基金资产净值的5%"],"answer":"ABC","explain":"D选项不符合题意，一只基金持有一家公司发行的证券，其市值超过基金资产净值的10%才是禁止情形，5%未超过。"},{"id":"basics2-51","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"基金交易费是指基金在进行证券买卖交易时所发生的相关交易费用，主要包括（）。","options":["印花税","开户费","证管费","佣金"],"answer":"ACD","explain":"B选项错误，开户费不属于基金交易费。我国基金的交易费主要包括印花税、佣金、过户费、经手费、证管费。"},{"id":"basics2-52","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"基金投资收益具体包括（）。","options":["ETF替代损益","衍生工具收益","股利收益","手续费返还"],"answer":"BC","explain":"A、D选项错误，ETF替代损益和手续费返还属于其他收入。B、C选项正确，投资收益包括衍生工具收益、股利收益等。"},{"id":"basics2-53","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"金融市场的功能包括（）。","options":["资金融通","价格发现","提供流动性","风险管理"],"answer":"ABCD","explain":"A、B、C、D均属于金融市场的功能。"},{"id":"basics2-54","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"私募基金募集应当履行的程序，主要包括（）等。","options":["特定对象确定","投资者适当性匹配","合格投资者确认","投资冷静期"],"answer":"ABCD","explain":"A、B、C、D均属于私募基金募集应当履行的程序。"},{"id":"basics2-55","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于地方政府债券概念的说法，错误的有（）。","options":["仅向银行、证券公司等金融机构发行筹集资金","是一种债务凭证","根据本地区经济发展和资金需求状况发行","筹集资金不可用于地方兴建大型项目"],"answer":"AD","explain":"A选项错误，地方政府债券向社会筹集资金，并非仅向金融机构发行。D选项错误，筹集的资金可用于地方兴建大型项目。"},{"id":"basics2-56","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于风险偏好和风险容忍度的说法，正确的有（）。","options":["风险容忍度是风险偏好的具体体现，是对风险偏好的进一步量化和细化","风险容忍度表现为公司在不同业务板块和不同控制维度上的总体边界","风险偏好是公司决策层综合考虑多种风险因素后作出的一种更高层次的承诺","风险偏好的设定通常从战略角度出发，采取“自上而下”的设定方法"],"answer":"ABCD","explain":"A、B、C、D均正确。"},{"id":"basics2-57","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于国债的承购包销发行方式的说法，正确的有（）。","options":["承购包销团负责在市场上转售","任何未能售出的余额均由承销者包销","按一定条件向财政部承购包销国债","大宗机构投资者组成承购包销团"],"answer":"ABCD","explain":"A、B、C、D均正确。"},{"id":"basics2-58","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于沪港通的说法，正确的有（）","options":["沪股通是指投资者委托内地证券公司，向香港联合交易所进行申报，买卖沪港通规定范围内的香港联合交易所上市的股票","沪股通是指投资者委托香港经纪商，向上海证券交易所进行申报，买卖沪港通规定范围内的上海证券交易所上市的股票","沪港通下的港股通，是指投资者委托香港经纪商，向上海证券交易所进行申报，买卖沪港通规定范围内的上海证券交易所上市的股票","沪港通下的港股通，是指投资者委托内地证券公司，向香港联合交易所进行申报，买卖沪港通规定范围内的香港联合交易所上市的股票"],"answer":"BD","explain":"A选项错误，沪股通是投资者委托香港经纪商。C选项错误，港股通是投资者委托内地证券公司。"},{"id":"basics2-59","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于基金信息披露的说法，正确的有（）。","options":["基金的信息披露不具有强制性","基金的信息披露必须保证所披露信息的真实性、准确性和完整性","基金的信息披露制度有利于防止利益冲突和利益输送","与市场上其他理财产品相比，基金的一个突出特点就是透明度较高"],"answer":"BCD","explain":"A选项错误，在我国，基金的信息披露具有强制性。"},{"id":"basics2-60","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于美国金融市场的说法，正确的有（）。","options":["根据国债的特点，美国国债有通货膨胀保值债券、浮动利率国库票据等分类","目前的纽约证券交易所交易制度模式主要包括三个特征，即专家制度、场内经纪商制度和补充流动性供商制度","1997年纳斯达克市场将电子通信引入自身的报价和交易系统中，并启用美国证券交易委员会的《交易指令处理规则》","有效联邦基金利率由联储理事会公开市场委员会负责计算和发布"],"answer":"AC","explain":"B选项错误，应为指定做市商制度。D选项错误，由纽约联邦储备银行负责计算和发布。"},{"id":"basics2-61","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于证券公司压力测试的说法，正确的有（）。","options":["证券公司压力测试采用以定量分析为主的风险分析方法","压力情景包括证券公司内外部经营环境发生极端变化或出现突发事件、开展重大业务以及进行利润分配等情形","证券公司在设置压力情景时，可采取历史情景法、假设情景法或者二者相结合的方法","假设情景法是指基于经验判断或数量模型模拟未来可预见的极端不利情况"],"answer":"ABCD","explain":"A、B、C、D均正确。"},{"id":"basics2-62","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于直接融资和间接融资的说法，正确的有（）。","options":["提高直接融资比重，有利于分散过度集中于银行的金融风险","发展多种股权融资方式有利于提高实体经济的健康稳定发展","相对于直接融资来说，间接融资的信誉程度低，风险也相对较大","直接融资通过市场主体充分博弈直接进行交易，有利于合理引导资源配置"],"answer":"ABD","explain":"C选项错误，相对于直接融资来说，间接融资的信誉程度高，风险也相对较小。"},{"id":"basics2-63","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列属于股票相对估值法的有（）。","options":["自由现金流折现模型","市净率倍数法","市销率倍数法","市盈率倍数法"],"answer":"BCD","explain":"A选项错误，自由现金流折现模型属于绝对估值法。"},{"id":"basics2-64","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列属于金融市场的有（）。","options":["劳动力市场","外汇市场","证券市场","房地产市场"],"answer":"BC","explain":"A、D选项错误，不属于金融市场。"},{"id":"basics2-65","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列属于一般性货币政策工具的有（）。","options":["存款准备金制度","再贴现政策","公开市场业务","常备借贷便利（SLF）"],"answer":"ABC","explain":"D选项错误，常备借贷便利属于选择性货币政策工具。"},{"id":"basics2-66","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列属于优先股的特点的是（）。","options":["收益相对固定","先于普通股获得股息","清偿顺序先于普通股，而次于债权人","权利范围小"],"answer":"ABCD","explain":"A、B、C、D均属于优先股的特点。"},{"id":"basics2-67","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列有关股票特征的说法，正确的有（）。","options":["股票的风险性和收益性是并存的","股份公司派发的股息红利数量，主要取决于公司的盈利情况","股票的风险性和收益性是彼此独立的","股份公司派发的股息红利数量，主要取决于公司的股息红利分配方案"],"answer":"AB","explain":"C选项错误，股票的风险性和收益性是并存的。D选项错误，股息红利数量取决于公司的经营状况和盈利水平。"},{"id":"basics2-68","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"以下属于场内市场的是（）。","options":["主板市场","创业板市场","私募基金市场","全国中小企业股份转让系统"],"answer":"ABD","explain":"C选项错误，私募基金市场属于场外市场。"},{"id":"basics2-69","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"以下属于股利分配相关日期的是（）。","options":["除息除权日","股权登记日","股利宣告日","股利派发日"],"answer":"ABCD","explain":"A、B、C、D均属于股利分配相关日期。"},{"id":"basics2-70","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"以下属于银行附属金融机构的有（）。","options":["财务公司","金融租赁公司","汽车金融公司","消费金融公司"],"answer":"BCD","explain":"A选项错误，财务公司不属于银行附属金融机构。"},{"id":"basics2-71","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"在证券公司柜台市场，证券公司可以为客户提供的私募产品服务有（）。","options":["清算交割","风险监控","公募基金买卖","估值核算"],"answer":"ABD","explain":"C选项错误，公募基金买卖不属于柜台市场私募产品服务。"},{"id":"basics2-72","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"证券公司自营业务投资范围包括（）。","options":["计划在区域股权市场挂牌的私募债券","政府债券","央行票据","短期融资券"],"answer":"BCD","explain":"A选项错误，计划在区域股权市场挂牌的私募债券不在自营业务投资范围内。"},{"id":"basics2-73","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"证券金融公司根据市场状况和风险控制的需要，确定和调整转融通的（）。","options":["佣金","费率","数量占比","保证金的比例"],"answer":"BD","explain":"B、D选项正确，证券金融公司确定和调整转融通费率和保证金的比例。"},{"id":"basics2-74","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"证券金融公司开展转融通业务，应当以自己的名义，在证券登记结算机构分别开立（）账户。","options":["融券专用证券账户","融资专用资金账户","转融通担保资金账户","转融通资金交收账户"],"answer":"CD","explain":"C、D选项正确，证券金融公司在证券登记结算机构开立转融通担保资金账户和转融通资金交收账户。"},{"id":"basics2-75","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"证券投资基金作为一种金融产品，与股票相比较，不同点主要表现为（）。","options":["股票投资风险通常大于基金投资风险","股票价格的波动要小于基金净值的波动","股票是间接投资工具，基金是直接投资工具","股票反映的是一种所有权关系，基金反映的则是一种信托关系"],"answer":"AD","explain":"B选项错误，股票价格的波动要大于基金净值的波动。C选项错误，股票是直接投资工具，基金是间接投资工具。"},{"id":"basics2-76","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"政府债券的功能包括（）。","options":["调节居民收入分配","国家实施宏观经济政策、进行宏观调控的工具","弥补财政赤字","为政府筹集资金、扩大公共开支"],"answer":"BCD","explain":"A选项错误，调节居民收入分配不属于政府债券的功能。"},{"id":"basics2-77","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"资本的功能主要体现在（）。","options":["资本显示金融机构的实力和信誉，向债权人和投资者树立信心","限制业务过度扩张和承担风险，资本是金融机构承担风险的底线和边界","为金融机构提供融资，资本是金融机构发放贷款和投资的资金来源之一","可以抵御风险损失，保证公司正常运营，为避免破产提供缓冲余地"],"answer":"ABCD","explain":"A、B、C、D均属于资本的功能。"},{"id":"basics2-78","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"资产证券化是以（）为支持，发行可交易证券的一种融资形式。","options":["特定现金流","特定股票组合","特定资产组合","特定基金组合"],"answer":"AC","explain":"A、C选项正确，资产证券化是以特定资产组合或特定现金流为支持。"},{"id":"basics2-79","subject":"basics","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"做市商交易制度的特点有（）。","options":["做市商的收入来源是买卖证券的差价","证券成交价格的形成由做市商决定","投资者之间可以直接成交","投资者买卖证券都以做市商为对手"],"answer":"ABD","explain":"C选项错误，投资者买卖证券都以做市商为对手，与其他投资者不发生直接关系。"},{"id":"basics2-80","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"IPO是首次公开发行股票的简称。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics2-81","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"按收益保障性分类可将结构化金融衍生产品分为股权联结型产品、利率联结型产品、汇率联结型产品和商品联结型产品等种类。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。按联结的基础产品分类，结构化金融衍生产品可分为股权联结型产品、利率联结型产品、汇率联结型产品和商品联结型产品等种类。"},{"id":"basics2-82","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"场外交易包括做市商交易和竞价交易。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics2-83","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"场外期权交易不只是机构投资者参与。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。场外期权交易仅限专业机构投资者参与。"},{"id":"basics2-84","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"风险覆盖率和资本杠杆率是重要的证券公司净资本监管工具，二者相辅相成、相互配合，促使证券公司在资产规模和风险水平方面寻求平衡，在业务发展和风险管理方面寻求有机统一，既要避免无节制地扩张业务，又要防止为追求利润过度发展高风险业务。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics2-85","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"风险容忍度更接近于业务单元与实际风险特征联系紧密，通常采用“自下而上”和“自上而下”相结合的方式设定。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics2-86","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"附息债券与累息债券的区别在于支付利息的频率不同。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics2-87","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《证券公司监督管理条例》，证券公司从事证券经纪业务，可以委托证券公司以外的金融机构作为证券经纪人，代理其进行客户招揽、客户服务等活动。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。可以委托证券公司以外的人员作为证券经纪人，即委托自然人而非机构。"},{"id":"basics2-88","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"根据金融资产确认和计量的会计准则，一旦被确认为衍生产品或可分离的嵌入式衍生产品，相关机构应把这一部分资产归入交易性资产类别，按照公允价格计价。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics2-89","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"股票和债券都是直接投资的金融工具，筹集的资金主要投向实业。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics2-90","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"货币供应量增加，实际利率下降，投资增加，总产出增加。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics2-91","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"金融市场只能通过政府干预性的价格决定利率，将货币资金配置到生产效率最高的经济主体或部门，使这些部门能够获得更多的生产要素，从而提高全社会的产出，使资源的利用效率得到提高。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。金融市场通过竞争性的价格决定利率，将货币资金配置到生产效率最高的经济主体或部门。"},{"id":"basics2-92","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"金融债券一般不记名、不挂失，但可以抵押和转让。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics2-93","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"可转换债券的回购是指当公司股票价格在一段时间内连续高于转换价格达到一定幅度时，可转换公司债券持有人按事先约定的价格将所持可转换债券卖给发行人的行为。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。这是赎回的概念，回售是指公司股票在一段时间内连续低于转换价格达到某一幅度时，持有人将债券卖给发行人的行为。"},{"id":"basics2-94","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"目前，在我国基金投资活动中，基金买卖股票按照0.1%的税率征收交易印花税，即对印花税实行双向征收。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。基金卖出股票按照0.05%的税率征收交易印花税，买入交易不征收印花税，即对印花税实行单向征收。"},{"id":"basics2-95","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"募集证券投资基金有一定人数和募集基金限额要求。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics2-96","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"企业市场化并购重组，促进产业整合，是解决产能过剩问题的重要手段。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics2-97","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"首次公开发行证券，持有一定数量的非限售股份或国债的投资者才能参与网上申购。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。网上投资者应当持有一定数量非限售股份或存托凭证，并非国债。"},{"id":"basics2-98","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"特殊目的机构（SPV）是以资产证券化为目的而特别组建的独立法律主体，其负债主要是发行的资产支持债券，资产则是向发起人购买的基础资产，SPV是介于发起人和投资者之间的中介机构，是资产支持证券的真正发行人。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics2-99","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"投资者申请开立A股账户时，开户代理机构应当为其同时开立沪市及深市A股账户，投资者确有需要开立单边A股账户的除外。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics2-100","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"投资者应当以书面形式承诺其符合合格投资者标准，投资者的评估结果有效期最长不得超过5年。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。投资者的评估结果有效期最长不得超过3年。"},{"id":"basics2-101","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"委托指令应当包括下列内容：证券账户号码、证券代码、买卖方向、委托数量、委托价格、交易所及其会员要求的其他内容。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics2-102","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"在信用风险分析中，违约依然是最为重要的信用事件，对信用风险的描述和量化仍然以违约为中心，主要包括违约概率、违约损失率和违约时的风险暴露等。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics2-103","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"在中央银行的职能中，“政府的银行”的职能主要是指垄断发行货币、调节货币供应量。","options":["正确","错误"],"answer":"B","explain":"本题说法错误。“政府的银行”是指中央银行代表国家制定和执行货币政策，处理对外金融关系，为国家提供各种金融服务。"},{"id":"basics2-104","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"债券的特征包括偿还性，波动性和收益性。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。债券的特征：偿还性、流动性、安全性、收益性，不包括波动性。"},{"id":"basics2-105","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"证券服务机构是指会计师事务所、律师事务所以及从事证券投资咨询、资产评估、资信评级、财务顾问、信息技术系统服务的证券服务机构。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics2-106","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"证券公司进行压力测试应遵循全面性、实践性、审慎性和前瞻性原则。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics2-107","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"证券经纪商要根据证券交易所的交易规则，对客户的证件和委托单在合法性和真实性方面进行审查。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。对客户的证件和委托单在合法性和同一性方面进行审查。"},{"id":"basics2-108","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"政府债券最初仅是政府弥补财政赤字的手段，但在现代商品经济条件下，政府债券已经成为政府筹集资金、扩大公共开支的重要手段，也是进行宏观调控的工具。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"basics2-109","subject":"basics","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"中长期银行贷款市场属于资本市场。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"}]},{"id":"advisor1","subject":"advisor","name":"证券投顾 · 押题卷一","stats":{"单选":40,"多选":40,"判断":20,"案例":20},"questions":[{"id":"advisor1-0","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"（），即由于基础资产市场价格的不利变动或者急剧波动而产生的风险暴露。","options":["风险敞口","下行风险","单向敞口","双向敞口"],"answer":"A","explain":"A选项正确，在对冲交易中，风险敞口通常是指市场风险敞口，即由于基础资产市场价格的不利变动或者急剧波动而产生的风险暴露。"},{"id":"advisor1-1","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"（）是对剩余流动性的弹性。","options":["估值杠杆","利润杠杆","运营杠杆","财务杠杆"],"answer":"A","explain":"在不同行业轮动介入时点的选择上，存在三种杠杆：财务杠杆（对利率的弹性）、运营杠杆（对经济的弹性）、估值杠杆（对剩余流动性的弹性）。故本题选A选项。"},{"id":"advisor1-2","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"（）是利用统计、数值模拟和其他定量模型进行证券市场相关研究的方法。","options":["量化分析法","技术分析法","基本分析法","统计分析法"],"answer":"A","explain":"A选项正确，量化分析法是利用统计、数值模拟和其他定量模型进行证券市场相关研究的一种方法。"},{"id":"advisor1-3","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"常见的市场风险计量指标包括（）指标和总量类指标。","options":["趋势性","敏感性","结构性","业务性"],"answer":"B","explain":"B选项符合题意，常见的市场风险计量指标包括敏感性指标和总量类指标。"},{"id":"advisor1-4","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"从家庭生命周期不同阶段的保险安排来看，成熟期家庭的理财重点是（）。","options":["寿险保额","养老保险或递延年金","长期看护险","教育年金"],"answer":"B","explain":"从家庭生命周期不同阶段的保险安排来看，成熟期家庭的理财重点是养老保险或递延年金。故本题选B选项。"},{"id":"advisor1-5","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"从经济学角度讲，“套利”可以理解为（）。","options":["人们利用不同证券或组合的期望收益率不同，通过调整不同证券或组合的构成比例而实现有风险收益的行为","人们利用不同证券或组合的期望收益率不同，通过调整不同证券或组合的构成比例而实现无风险收益的行为","人们利用同一资产在不同市场间定价不一致，通过资金的转移而实现有风险收益的行为","人们利用同一资产在不同市场间定价不一致，通过资金的转移而实现无风险收益的行为"],"answer":"D","explain":"D选项正确，从经济学的角度讲，套利是指利用同一资产在不同市场间定价的不一致，通过资金的转移而实现无风险收益的行为。"},{"id":"advisor1-6","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"风险资产的预期报酬率与其所承担的系统风险β系数之间呈线性关系，充分体现了风险与收益相匹配的原则的方程式是（）。","options":["证券市场线方程","证券特征线方程","资本市场线方程","马柯威茨方程"],"answer":"A","explain":"A选项正确，证券市场线很清晰地反映了风险资产的预期报酬率与其所承担的系统风险β系数之间呈线性关系。"},{"id":"advisor1-7","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"个人在社会群体压力下，放弃自己的意见，采取与大多数人一致的行为现象称为（）。","options":["反应不足","羊群行为","控制力幻觉","过度反应"],"answer":"B","explain":"B选项正确，“羊群效应”也称“从众效应”，是指个人的观念或行为由于真实的或想象的群体的影响或压力，而向与多数人相一致的方向变化的现象。"},{"id":"advisor1-8","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据移动平均法，如果某只股票价格超过平均价的某一百分比时，应该（）。","options":["买入","卖出","清仓","满仓"],"answer":"A","explain":"A选项正确，移动平均法的实质是简单过滤器规则的一种变形。在价格超过平均价的某一百分比时买入该股票，在股票价格低于平均价的一定百分比时卖出该股票。"},{"id":"advisor1-9","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"关于适当性匹配说法正确的是（）。","options":["特定的投资者购买恰当的产品","适合的投资者购买低风险的产品","适合的投资者购买恰当的产品","特定的投资者购买低风险的产品"],"answer":"C","explain":"C选项正确，适当性匹配是证券公司、证券投资咨询机构开展投资顾问业务需要履行的职责，旨在确保证券经营机构向适当的投资者提供适当的金融产品或服务。"},{"id":"advisor1-10","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"关于套利，下列说法正确的是（）。","options":["当投资者不需要任何投资就可以获得低风险收益时，他们就是在套利","套利机会的存在意味着市场处于不均衡状态","套利只存在单一资产上","套利机会可以长久地存在下去"],"answer":"B","explain":"B选项正确，套利是指不需要追加投资就可获得收益的买卖行为。套利机会的存在意味着市场处于不均衡状态。"},{"id":"advisor1-11","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"关于头肩顶形态中的颈线，以下说法不正确的是（）。","options":["头肩顶形态中，它是支撑线，起支撑作用","突破颈线一定需要大成交量配合","当颈线被突破，反转确认以后，大势将下跌","如果股价最后在颈线水平回升，而且回升的幅度高于头部，或者股价跌破颈线后又回升到颈线上方，这可能是一个失败的头肩顶，宜作进一步观察"],"answer":"B","explain":"B选项错误，突破颈线不一定需要大成交量配合，但日后继续下跌时成交量会放大。"},{"id":"advisor1-12","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"国际资本流动造成外汇市场和汇率的波动。国际资本流入将导致（）。","options":["对本币的兑换需求下降，本币贬值","对本币的兑换需求下降，本币升值","对本币的兑换需求上升，本币贬值","对本币的兑换需求上升，本币升值"],"answer":"D","explain":"D选项正确，国际资本流入外币必须兑成本币才能使用，所以会导致对本币的兑换需求上升，本币升值。"},{"id":"advisor1-13","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"基金投资顾问机构开展管理型基金投资顾问业务的，应当（）披露委托资产参考市值，基金投资顾问机构应当建立复核机制，确保市值信息的真实完整。","options":["每日","每周","每月","每季"],"answer":"A","explain":"A选项正确，基金投资顾问机构开展管理型基金投资顾问业务的，应当每日披露委托资产参考市值。"},{"id":"advisor1-14","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"基金投资管理过程中，投资决策委员会负责决定的内容包括（）。","options":["投资原则","投资指令","投资策略","投资权限"],"answer":"C","explain":"C选项正确，投资决策委员会审议决策生成基金组合策略、调整基金组合策略等。"},{"id":"advisor1-15","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"技术分析理论不包括（）。","options":["切线理论","资本资产定价理论","波浪理论","循环周期理论"],"answer":"B","explain":"B选项符合题意，技术分析理论不包括资本资产定价理论。"},{"id":"advisor1-16","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"家庭状况会影响个人投资者的投资需求，家庭状况不包括（）。","options":["子女的数量与年龄","需赡养老人的数量和健康状况","个人投资者的工作稳定性","婚姻状况"],"answer":"C","explain":"C选项符合题意，个人投资者的工作稳定性不属于家庭状况。"},{"id":"advisor1-17","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"某5年期债券，面值为100元，票面利率为10%，单利计息，市场利率为10%，到期一次还本付息，则该债券的麦考利久期为（）年。","options":["3","3.5","4","5"],"answer":"D","explain":"D选项正确，该债券为到期一次还本付息结构，此类债券的麦考利久期恒等于其到期期限，即5年。"},{"id":"advisor1-18","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"某公司的可转换债券，面值为1000元，转换价格为25元，当前的市场价格为1150元，其标的股票当前的市场价格为27元，该债券的转换价值为（）。","options":["1150元","1080元","926元","1000元"],"answer":"B","explain":"B选项正确，转换比率=1000/25=40，转换价值=27×40=1080元。"},{"id":"advisor1-19","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"某投资者用952元购买了一张面值为1000元的债券，息票利率10%，每年付息一次，距到期日还有3年，试计算其到期收益率（）。","options":["15%","14%","12%","8%"],"answer":"C","explain":"C选项正确，952=100/(1+x)+100/(1+x)²+1100/(1+x)³，解得x=12%。"},{"id":"advisor1-20","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"普通投资者应在（）不享有特别保护。","options":["信息告知","风险警示","投资收益","适当性匹配"],"answer":"C","explain":"C选项符合题意，普通投资者在信息告知、风险警示、适当性匹配等方面享有特别保护，投资收益不享有特别保护。"},{"id":"advisor1-21","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"市场预期理论认为利率期限结构完全取决于对未来即期利率的市场预期，局限在于不能解释收益率曲线通常是（）。","options":["向下倾斜的","水平的","向上倾斜的","拱形的"],"answer":"C","explain":"C选项正确，市场预期理论不可以解释收益率曲线是通常向上倾斜的。"},{"id":"advisor1-22","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"收益率曲线的类型不包括（）。","options":["正向的利率曲线","反向的利率曲线","平直的利率曲线","垂直的利率曲线"],"answer":"D","explain":"D选项正确，收益率曲线的类型包括正向、反向、平直和拱形利率曲线，不包括垂直的利率曲线。"},{"id":"advisor1-23","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"套利定价理论的创始人是（）。","options":["威廉夏普","史蒂芬·罗斯","莫辛","马科维茨"],"answer":"B","explain":"B选项正确，1976年，美国学者斯蒂芬·罗斯提出了套利定价理论（APT）。"},{"id":"advisor1-24","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"通常，对于（）型投资者而言，倾向于在保证本金的基础上维持资金增值，进而选择低风险投资产品。","options":["成长","保守","稳健","激进"],"answer":"B","explain":"B选项正确，保守型客户通常为步入退休阶段的老年人群、低收入家庭等，首先考虑是否能够保本，然后才考虑追求收益。"},{"id":"advisor1-25","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"投资顾问业务的私人银行的起源是（）。","options":["英国伦敦","瑞士日内瓦","德国慕尼黑","荷兰阿姆斯特丹"],"answer":"B","explain":"B选项正确，在16世纪的瑞士日内瓦，第一批从事投资顾问业务的私人银行家出现。"},{"id":"advisor1-26","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"为推进利率市场化改革，提高金融机构自主定价能力健全货币政策传导机制，培育货币市场基准利率，（）于2007年开始试运行上海银行间同业拆借利率。","options":["中国人民银行","中国证监会","财政部","中国银监会"],"answer":"A","explain":"中国人民银行于2007开始试运行上海银行间同业拆借利率。故本题选A选项。"},{"id":"advisor1-27","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列对个人资产负债表的理解错误的一项是（）。","options":["资产负债表中的记账法遵循会计恒等式\"资产=负债+净资产\"","资产负债表可以反映客户的动态财务特征","客户的资产负债表是记录和分析客户资产和负债状况的重要工具","编制资产负债表时，首要考虑确定报表时点，即月末、季末或年末"],"answer":"B","explain":"B选项错误，资产负债表是反映某一时点财务状况的会计报表，反映的是静态财务特征。"},{"id":"advisor1-28","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列关于客户投资目标分类的说法中，错误的是（）。","options":["按照时间的长短可以分为短期目标、中期目标和长期目标","休假、购置新车等属于短期目标","短期、中期、长期目标之间的界限是绝对分明的","退休保障安排、遗产安排等属于长期目标"],"answer":"C","explain":"C选项错误，短期、中期、长期目标之间的界限并不是绝对的。"},{"id":"advisor1-29","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列关于生命周期理论的表述，不正确的是（）。","options":["个人在不同阶段的消费水平应相对平滑，而不要出现大幅波动","个人是在相当长的时间内计划他的消费和储蓄行为的","个人希望在整个生命周期实现消费和储蓄的最佳配置","个人在决定目前消费和储蓄时，其主要考虑的因素是未来收入、可预期的支出以及工作时间、退休时间等，而无须关注即期收入"],"answer":"D","explain":"D选项错误，个人在决定目前消费和储蓄时，还需要关注即期收入。"},{"id":"advisor1-30","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列关于债务规划的说法中错误的是（）。","options":["偿还高利率信用贷款时，采取本金摊还款法可以更快地还清本金","通常应优先偿还临近到期的借款","债务整合规划是在降低总负担的前提下，把不同贷款机构的贷款整合在一家","转贷规划是以高利率负债置换低利率负债"],"answer":"D","explain":"D选项错误，转贷规划的目的是以低利率负债置换高利率负债，降低利息支出。"},{"id":"advisor1-31","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列信息中属于客户的定量信息的是（）。","options":["健康状况","收入与支出","金钱观","风险特征"],"answer":"B","explain":"B选项正确，定量信息包括客户的年龄、收入水平、资产负债状况、投资组合、投资经验、风险承受能力等信息。"},{"id":"advisor1-32","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"向客户提供证券投资顾问服务的人员应当符合相关从业条件，并在（）注册登记为证券投资顾问。","options":["证券公司","中国证监会","国务院证券监督管理机构","中国证券业协会"],"answer":"D","explain":"D选项正确，向客户提供证券投资顾问服务的人员应当符合相关从业条件，并在中国证券业协会注册登记为证券投资顾问。"},{"id":"advisor1-33","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"已知无风险回报率为6%，市场要求的回报率为12%，某公司股票的β为1.5，如果去年公司每股股息2.5，股息增长率持续保持在5%，则该公司的股票估值为（）元。","options":["3.75","7.25","26.25","13.25"],"answer":"C","explain":"必要收益率为E(Ri)=6%+1.5(12%-6%)=15%，V=2.5×(1+5%)÷(15%-5%)=26.25元。"},{"id":"advisor1-34","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"用来反映证券组合期望收益水平和总风险水平之间均衡关系的方程式是（）。","options":["证券市场线方程","证券特征线方程","资本市场线方程","套利定价方程"],"answer":"C","explain":"C选项正确，资本市场线方程对有效组合的期望收益率和风险之间的关系提供了十分完整的阐述。"},{"id":"advisor1-35","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"预计某公司的股息每股每年约增长5%，如果上年的股息是每股8元，市场资本化率为每年10%利用股息贴现模型（DDM），当前公司的股价为（）元。","options":["168","56","16","84"],"answer":"A","explain":"由不变增长模型V=D0(1+g)/(r-g)，当前股价=8×(1+5%)/(10%-5%)=168元。"},{"id":"advisor1-36","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"在凯恩斯学派的货币政策传导理论中，其传导机制的核心是（）。","options":["基础货币","货币乘数","利率","货币供应量"],"answer":"C","explain":"C选项正确，凯恩斯学派的货币政策传导机制的主要环节是利率。"},{"id":"advisor1-37","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司、证券投资咨询机构应当向客户提供风险揭示书，并由客户签收确认。风险揭示书内容与格式要求由（）制定。","options":["本公司","中国证监会","中国证券业协会","交易所"],"answer":"C","explain":"C选项正确，风险揭示书内容与格式要求由中国证券业协会制定。"},{"id":"advisor1-38","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券投资顾问依据本公司或者其他证券公司证券投资咨询机构的证券研究报告作出投资建议的，应当向客户说明（）。","options":["证券投资顾问本人关于证券研究报告的观点","证券研究报告的发布人、发布日期","除作为依据之外的第三方证券研究报告的观点","与该证券研究报告冲突的其他证券研究报告的观点"],"answer":"B","explain":"B选项正确，应当向投资者说明证券研究报告的发布人、发布日期。"},{"id":"advisor1-39","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券投资咨询机构中向客户提供证券投资顾问服务的人员应符合相关从业条件，并在协会登记为（）。","options":["证券投资顾问","证券分析师","客户经理","证券经纪人"],"answer":"A","explain":"A选项正确，证券投资咨询机构中向客户提供证券投资顾问服务的人员应符合相关从业条件，并在协会登记为证券投资顾问。"},{"id":"advisor1-40","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"艾略特波浪理论的基本思想包括（）。","options":["斐波那奇数列是波浪理论的数学基础","艾略特的波浪理论以周期为基础","艾略特最初提出波浪理论是受股价上涨下跌现象不断重复的启发","艾略特的波浪理论与道氏理论密切相关"],"answer":"ABCD","explain":"A、B、C、D均正确。"},{"id":"advisor1-41","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"编制个人现金流量表要符合的原则有（）。","options":["真实可靠原则","反映充分原则","本币反映原则","明晰性原则"],"answer":"ABCD","explain":"编制个人现金流量表要符合的原则有：真实可靠原则、反映充分原则、明晰性原则、及时性原则、本币反映原则、充分揭示原则。"},{"id":"advisor1-42","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"财政政策对证券市场的影响有（）。","options":["减少税收，降低税率，扩大减免税范围，会推动证券市场价格上涨","扩大财政支出，加大财政赤字，会推动证券市场价格上涨","减少国债发行（或回购部分短期国债），会推动证券市场上扬","增加财政补贴会推动证券市场总体水平趋于上涨"],"answer":"ABCD","explain":"A、B、C、D均属于积极财政政策对证券市场的影响。"},{"id":"advisor1-43","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"反映公司投资收益的指标有（）。","options":["资本化率","每股收益","市盈率","存货周转率"],"answer":"BC","explain":"B、C选项正确，反映公司投资收益指标的主要有每股收益、市盈率、股利支付率、每股净资产等。"},{"id":"advisor1-44","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《证券投资顾问业务暂行规定》，证券公司、证券投资咨询机构从事证券投资顾问业务，应当保证证券投资顾问（）与服务方式、业务规模相适应。","options":["人员数量","业务能力","合规管理","风险控制"],"answer":"ABCD","explain":"A、B、C、D均正确。"},{"id":"advisor1-45","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《证券投资顾问业务暂行规定》，证券投资顾问向客户提供投资建议，应当具有合理的依据。投资建议的依据包括（）。","options":["证券研究报告","基于证券研究报告形成的投资意见","基于理论模型形成的投资意见","基于分析方法形成的投资分析意见"],"answer":"ABCD","explain":"A、B、C、D均属于投资建议的依据。"},{"id":"advisor1-46","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据《证券投资顾问业务暂行规定》的要求，证券公司、证券投资咨询机构应当对证券投资顾问（）等环节实行留痕管理。","options":["服务提供","客户回访和投诉处理","业务推广","协议签订"],"answer":"ABCD","explain":"A、B、C、D均属于留痕管理环节。"},{"id":"advisor1-47","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据对客户收入预测的方法，可以把客户收入分为（）。","options":["一般性收入","常规性收入","永久性收入","临时性收入"],"answer":"BD","explain":"B、D选项正确，在预测客户的未来收入时，可以将收入分为常规性收入和临时性收入两类。"},{"id":"advisor1-48","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据美林时钟理论，关于不同经济周期的收益率的大小，下列说法正确的有（）。","options":["衰退期：债券>现金>股票>大宗商品","复苏期：股票>债券>现金>大宗商品","过热期：股票>大宗商品>现金/债券","滞胀期：现金>大宗商品/债券>股票"],"answer":"ABD","explain":"C选项错误，过热期应为大宗商品>股票>现金/债券。"},{"id":"advisor1-49","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"根据资本资产定价模型在资源配置方面的应用，下列正确的有（）。","options":["牛市到来时，应选择那些低β系数的证券或组合","牛市到来时，应选择那些高β系数的证券或组合","熊市到来之际，应选择那些低β系数的证券或组合","熊市到来之际，应选择那些高β系数的证券或组合"],"answer":"BC","explain":"B、C选项正确。牛市选择高β系数股票，熊市选择低β系数股票。"},{"id":"advisor1-50","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"关于对客户未来支出的预测，下列说法正确的是（）。","options":["通货膨胀因素是支出预期的考虑因素之一","生活质量是支出预期的考虑因素之一","为了顾及客户未来支出，首先要考虑客户基本生活的支出","客户未来支出还包括临时性支出"],"answer":"ABC","explain":"D选项错误，估计客户的未来支出，需要了解两种不同状态下的客户支出：基本生活支出和期望实现的支出水平。"},{"id":"advisor1-51","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"关于紧急预备金的储存方式，下列说法正确的有（）。","options":["以存款作为储备金可能无法达到长期投资的平均报酬率","以贷款额度作为预备金，需要考虑支付的利息","紧急预备金通常包括两种方式","存贷款利率的差距越大，越需要利用贷款额度作为预备金"],"answer":"ABC","explain":"D选项错误，最好的方式是将存款和贷款额度二者搭配使用。"},{"id":"advisor1-52","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"关于自下而上的分析方法，下列说法正确的有（）。","options":["自下而上的分析法注重对股票趋势的把握","根据投资目标，通过一系列的公司财务指标等选出投资个股的选择","自下而上的分析法更注重个股的选择，忽略市场的短期波动","巴菲特是采用\"自下而上\"分析法的典范"],"answer":"BCD","explain":"A选项错误，自下而上分析法更侧重于关注个股的具体情况和公司的经营状况。"},{"id":"advisor1-53","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"计量违约损失率应当采取审慎的态度，估计经济衰退时期违约债项的损失严重程度，主要方法包括（）。","options":["市场价值法","专家判断法","信用评分模型","回收现金流法"],"answer":"AD","explain":"A、D选项正确，计量违约损失率的主要方法包括市场价值法和回收现金流法。"},{"id":"advisor1-54","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"假设市场中存在A、B两种无风险债券，均每年支付一次，利息相关信息如下，则下列说法中正确的有（）。","options":["市场1年期即期利率为8.25%","市场2年期即期利率为7.08%","市场1年期即期利率为8.05%","市场2年期即期利率为6.97%"],"answer":"AB","explain":"A、B选项正确，通过计算可得1年期即期利率为8.25%，2年期即期利率为7.08%。"},{"id":"advisor1-55","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"结合美国、日本两国业务实践，投资顾问业务模式分为（）。","options":["咨询型模式","全权委托型模式","管理型模式","分析型模式"],"answer":"AB","explain":"A、B选项正确，投资顾问业务模式分为咨询型模式和全权委托型模式。"},{"id":"advisor1-56","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"了解客户的渠道有（）。","options":["家访","面谈","风险测评","调查问卷"],"answer":"BCD","explain":"B、C、D选项正确，可以通过面谈、调查问卷、风险测评等方式来获取客户信息。"},{"id":"advisor1-57","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"某公司某年末净赚利润为150万元，营业收入为3000万元，资产总额为2000万元，股东权益为1000万元，则下列财务指标正确的是（）。","options":["营业利润率为5%","总资产周转率为1.5","权益乘数为2","净资产收益率为15%"],"answer":"ABCD","explain":"A、B、C、D均正确。营业利润率=150/3000=5%，总资产周转率=3000/2000=1.5，权益乘数=2000/1000=2，净资产收益率=5%×1.5×2=15%。"},{"id":"advisor1-58","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"某投资者于年初将1500元现金按5%的年利率投资5年，那么该投资者（）。","options":["按单利计算的第五年年末的终值为1785元","按单利计算的第五年年末的终值为1875元","按复利计算的第二年年末的终值为1653.75元","按复利计算的第二年年末的终值为1914.42元"],"answer":"BC","explain":"B选项正确，单利终值=1500×(1+5%×5)=1875元。C选项正确，复利终值=1500×(1+5%)²=1653.75元。"},{"id":"advisor1-59","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"通过对资本资产定价模型中投资组合的β系数进行管理，可以衍生出一系列量化投资策略。以下属于这类量化策略的有（）。","options":["Smartβ策略——调整资产组合的β系数，来实现一定的组合风险收益特征","纯α策略——通过多空对冲，使整个组合的β系数始终趋近于0，赚取选股带来的主动收益","高频宏观因子策略——利用对利率、经济增长、通胀等因子的观察和跟踪，通过回归等数理统计手段构建有效投资组合","纯β策略——被动投资，跟踪某一股票指数，获得市场收益"],"answer":"ABD","explain":"C选项错误，高频宏观因子策略更多属于因子投资或多因子模型，核心是捕捉宏观经济因子的风险溢价。"},{"id":"advisor1-60","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"投资组合管理及资产配置步骤包括（）。","options":["明确投资组合管理的收益目标","形成资本市场预期","构建具体的投资组合","评价投资组合的业绩"],"answer":"ABCD","explain":"A、B、C、D均属于投资组合管理及资产配置步骤。"},{"id":"advisor1-61","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列不属于客户的定量信息是（）。","options":["收入和支出","家庭状况","职业信息","投资偏好"],"answer":"BCD","explain":"B、C、D选项正确，家庭状况、职业信息、投资偏好属于定性信息。"},{"id":"advisor1-62","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列关于违约风险暴露的说法中，正确的有（）。","options":["若客户尚未违约，违约风险暴露的表外项目为已提取金额+信用转换系数×已承诺未提取金额","若客户已违约，则违约风险暴露为其违约时的债务账面价值","是债务人违约时预期表内项目和表外项目的风险暴露总额","若客户尚未违约，违约风险暴露的表内项目为债务账面价值"],"answer":"ABCD","explain":"A、B、C、D均正确。"},{"id":"advisor1-63","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列关于无差异曲线特点的说法中，正确的有（）。","options":["无差异曲线是由左至右向上弯曲的曲线","每个投资者的无差异曲线形成连续密布整个平面又互不相交的曲线簇","不同无差异曲线上的组合给投资者带来的满意程度相同","无差异曲线的位置越高，其上的组合给投资者带来的满意程度就越高"],"answer":"ABD","explain":"C选项错误，同一条无差异曲线上的组合给投资者带来的满意程度相同；不同无差异曲线上的组合给投资者带来的满意程度不同。"},{"id":"advisor1-64","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列关于现值的说法中，错误的有（）。","options":["当给定终值时，贴现率越高，现值越低","当给定利率及终值时，取得终值的时间越长，该终值的现值就越高","在其他条件相同的情况下，按单利计息的现值要低于用复利计息的现值","利率为正时，现值大于终值"],"answer":"BCD","explain":"B选项错误，时间越长，现值越低。C选项错误，单利计息的现值要高于复利计息的现值。D选项错误，利率为正时，现值小于终值。"},{"id":"advisor1-65","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列属于客户现金流量表支出项目的有（）。","options":["房地产贷款月供支出","学费、培训费","医疗费用","信用卡透支"],"answer":"ABC","explain":"D选项不符合题意，信用卡透支的本金部分属于筹资活动负债，不直接列为支出项目。"},{"id":"advisor1-66","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列说法中，属于资本资产定价模型假设条件的有（）。","options":["投资者厌恶风险","证券收益由历史收益和标准差刻画","证券无限可分","税收和交易费用均忽略不计"],"answer":"ACD","explain":"B选项错误，CAPM假设证券收益服从正态分布，由期望收益和标准差（而非历史收益）刻画。"},{"id":"advisor1-67","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"下列因素中，能增加企业变现能力的因素有（）。","options":["准备很快变现的长期资产","可动用的银行贷款指标","偿债能力的声誉","未作记录的或有负债"],"answer":"ABC","explain":"D选项错误，或有负债和担保责任引起的负债会减弱公司的短期偿债能力。"},{"id":"advisor1-68","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"一般而言，风险偏好型客户会倾向于选择（）。","options":["垃圾债券","股指期货","投资于新兴产业的股票型基金","货币型基金"],"answer":"ABC","explain":"D选项错误，货币型基金属于低风险、低收益、高流动性的产品。"},{"id":"advisor1-69","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"影响证券市场供给的制度因素主要有（）。","options":["发行上市制度","市场设立制度","股权流通制度","红利分配制度"],"answer":"ABC","explain":"D选项错误，红利分配属于公司治理与投资者回报机制，不直接决定市场供给量。"},{"id":"advisor1-70","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"在房地产市场发展过热的形势下，一方面居民大量提取存款买房，另一方面房地产开发商和个人向银行借款。如果房地产市场突然萎缩，出现大量个人住房贷款无法偿还、房地产开发商由于资金链断裂而倒闭的情形。监测信用风险指标的计算方法正确的有（）。","options":["不良贷款率=（次级类贷款+可疑类贷款）/各项贷款×100%","预期损失率=预期损失/资产风险暴露×100%","关联授信比例=全部关联方授信额度/资本净额×100%","逾期贷款率=逾期贷款余额/贷款总余额×100%"],"answer":"BCD","explain":"A选项错误，不良贷款率=（次级类贷款+可疑类贷款+损失类贷款）/各项贷款×100%。"},{"id":"advisor1-71","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"在风险管理过程中，由于利率汇率等市场价格因素的频繁波动，一般（）具有实质性意义。","options":["名义价值","市场价值","公允价值","价值重估"],"answer":"BC","explain":"B、C选项正确，在市场风险计量与监测的过程中，更具有实质意义的是市场价值和公允价值。"},{"id":"advisor1-72","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"在现金、消费和债务管理中，家庭紧急预备金的储存形式包括（）。","options":["短期定期存款","活期存款","货币市场基金","利用贷款额度"],"answer":"ABCD","explain":"A、B、C、D均属于家庭紧急预备金的储存形式。"},{"id":"advisor1-73","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司、证券投资咨询机构提供证券投资顾问服务，应当与客户签订证券投资顾问服务协议，协议内容应包括（）。","options":["服务内容和方式","争议或纠纷解决方式","终止或解除协议的条件和方式","收费标准和支持方式"],"answer":"ABCD","explain":"A、B、C、D均属于协议应当包括的内容。"},{"id":"advisor1-74","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司、证券投资咨询机构通过（）等公众媒体对证券投资顾问业务进行广告宣传，应当遵守《广告法》和证券信息传播的有关规定。","options":["广播","电视","网络","报刊"],"answer":"ABCD","explain":"A、B、C、D均正确。"},{"id":"advisor1-75","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券公司、证券投资咨询机构应当按照（）的原则，与客户协商并书面约定收取证券投资顾问服务费用的安排。","options":["公平","公正","合理","自愿"],"answer":"ACD","explain":"A、C、D选项正确，应当按照公平、合理、自愿的原则。"},{"id":"advisor1-76","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券投资顾问向客户提供投资建议，应当具有合理的依据。投资建议的依据包括（）撰写的证券研究报告。","options":["本公司证券分析师","其他公司证券分析师","投资顾问本人","投资顾问小组"],"answer":"AB","explain":"A、B选项正确，证券投资顾问基于证券研究报告提供投资建议。"},{"id":"advisor1-77","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"证券组合管理过程中，进行证券投资分析的主要目的有（）。","options":["确定具体证券的投资额度","确定投资目标","明确这些证券的价格形成机制和影响证券价格波动的诸因素及其作用机制","发现那些价格偏离价值的证券"],"answer":"CD","explain":"C、D选项正确，进行证券投资分析的一个目的是明确价格形成机制，另一个目的是发现价格偏离价值的证券。"},{"id":"advisor1-78","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"中期移动平均线包括（）。","options":["10日线","30日线","60日线","250日线"],"answer":"BC","explain":"B、C选项正确，以30日、60日线观察中期走势，称为中期移动平均线。"},{"id":"advisor1-79","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷一","q":"资本资产定价模型是投资组合管理的基础，在投资组合管理中的应用非常广泛，包括（）。","options":["资产估值","量化投资","资源配置","预测股票市场的变动趋势"],"answer":"ABC","explain":"A、B、C选项符合题意，资本资产定价模型主要应用于资产估值、资产配置、量化投资三个方面。"},{"id":"advisor1-80","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"本币汇率下降必然导致股价下跌。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。当汇率下降时，本币升值，对股价影响并不确定。"},{"id":"advisor1-81","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"当久期缺口为负值时，如果市场利率下降，则流动性会随之减弱。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。当久期缺口为负值时，如果市场利率下降，流动性随之减弱。"},{"id":"advisor1-82","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"对保险产品的分类有助于投资者研究分析保险产品的风险收益特征，为资产配置奠定基础。","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"advisor1-83","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"分红寿险、万能寿险在为投资人提供一定保障同时兼具储蓄、投资功能。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"advisor1-84","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"基金评价人员可以同时在两个以上的基金评价机构执业。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。基金评价人员不得同时在两家以上的基金评价机构执业。"},{"id":"advisor1-85","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"盲目乐观的客户会认为能够在比实际更低的波动性下获得更高的收益。因此，在资产配置过程中，如果客户预期管理不好，将严重影响投资顾问业务开展。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"advisor1-86","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"如今多因素模型被广泛应用在证券组合中普通股之间的分配上，而均值一方差模型则被广泛应用在不同类型证券之间的投资分配上。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"advisor1-87","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"授信业务中抵（质）押品主要包括金融质押品、应收账款、房地产以及其他抵/质押品。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"advisor1-88","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"随着复利次数的增加，同一个名义年利率求出的有效年利率会不断增加，且速度越来越快。","options":["正确","错误"],"answer":"B","explain":"本题说法错误。随着复利次数的增加，有效年利率也会不断增加，但增加的速度越来越慢。"},{"id":"advisor1-89","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"套利定价模型表明市场均衡状态下套利组合中各种证券的权数之和等于1。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。套利组合中各种证券的投资比例满足w1+w2+...+wN=0，并非等于1。"},{"id":"advisor1-90","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"投资者适当性制度核心目的在于\"将适当的产品或服务销售或提供给适当的投资者”。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"advisor1-91","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"退休后从保险公司领取的养老金和按月领取的奖励均可视为一种年金。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。按月领取的奖励不一定是相等金额，不满足年金的概念。"},{"id":"advisor1-92","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"已获利息倍数可以用于测量债权人投入资本的风险和收益状况。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。已获利息倍数可以测试债权人投入资本的风险，但不能测量投入资本的收益状况。"},{"id":"advisor1-93","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"因金融产品设计、运营和委托人提供的信息不真实、不准确、不完整而产生的责任由证券公司承担。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。因金融产品设计、运营和委托人提供的信息不真实、不准确、不完整而产生的责任由委托人承担，证券公司不承担任何担保责任。"},{"id":"advisor1-94","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"在利率互换时通常无须交换本金，而是定期交换利息差额。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"advisor1-95","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"在期货合约签订后，期货价格可能高于、等于或低于相应的现货金融工具价格。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"advisor1-96","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"证券投资顾问当年注册资格后还需要再教育学时间培训。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券投资顾问在注册的当年是不需要参加后续职业培训的。"},{"id":"advisor1-97","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"证券投资顾问服务费用可以以个人账户收取（）。","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券投资顾问服务费用应当以公司账户收取。"},{"id":"advisor1-98","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"证券投资顾问业务，是证券投资咨询业务的一种基本形式，指证券公司、证券投资咨询机构接受客户委托，按照约定，向客户提供涉及证券及证券相关产品的投资建议服务，辅助客户作出投资决策，并直接或者间接获取经济利益的经营活动。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"advisor1-99","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷一","q":"证券投资者是证券市场资金的供给者，也是证券市场的供给主体。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券市场的供给主体是上市公司（企业）、政府与政府机构以及金融机构。"},{"id":"advisor1-100","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】某证券公司深入研究基金产品及其类型，自营投资了股票型基金和债券型基金，基金A和基金B为股票型基金，基金C为债券型基金。持仓信息如下：请根据上述背景信息回答以下问题。\n\n【问题】要求1 关于基金的类型，下列说法正确的是（）。","options":["指数基金通过指数增强策略，以期获得高于标的指数回报水平的投资业绩","成长型基金主要投资于可带来现金收入的有价证券，以获取当期的最大收入为目的","公司型基金是依据基金合同设立的","基金资产80%以上投资于股票的为股票基金"],"answer":"AD","explain":"B选项错误，收入型基金主要投资于可带来现金收入的有价证券。C选项错误，公司型基金依据公司章程成立。"},{"id":"advisor1-101","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】某证券公司深入研究基金产品及其类型，自营投资了股票型基金和债券型基金，基金A和基金B为股票型基金，基金C为债券型基金。持仓信息如下：请根据上述背景信息回答以下问题。\n\n【问题】要求2 关于股票基金的分析，下列说法正确的有（）。","options":["基金B的净值增长率为-20%","基金A的净值增长率为30%","基金B的净值增长率为0%","基金A的净值增长率为20%"],"answer":"BC","explain":"基金A净值增长率=[1.2-(1-0.1)]/1=30%，基金B净值增长率=[0.8-(1-0.2)]/1=0。"},{"id":"advisor1-102","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】某证券公司深入研究基金产品及其类型，自营投资了股票型基金和债券型基金，基金A和基金B为股票型基金，基金C为债券型基金。持仓信息如下：请根据上述背景信息回答以下问题。\n\n【问题】要求3 关于债券型基金，下列说法错误的是（）。","options":["债券型基金常常被投资者认为是收益、风险适中的投资工具","债券型基金根据投资范围的不同，可分为纯债型基金、混合债券型基金、债券指数型基金","债券型基金以追求长期资本增值为目标","债券型基金的波动通常小于股票型基金"],"answer":"C","explain":"C选项错误，股票型基金以追求长期资本增值为目标，比较适合长期投资。"},{"id":"advisor1-103","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】投资者海某预期甲股票价格将会下跌，于是与另一投资者王某订立期权合约，合约规定有效期限为三个月，海某可按每股10元的价格卖出王某甲股票5000股，期权价格为0.6元/股。请根据上述背景信息回答以下问题。\n\n【问题】要求1 影响期权价格（期权费）的因素包括（）。","options":["协定价格与市场价格","标的物价格的波动性","利率","剩余期限"],"answer":"ABCD","explain":"A、B、C、D均属于影响期权价格的因素。"},{"id":"advisor1-104","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】投资者海某预期甲股票价格将会下跌，于是与另一投资者王某订立期权合约，合约规定有效期限为三个月，海某可按每股10元的价格卖出王某甲股票5000股，期权价格为0.6元/股。请根据上述背景信息回答以下问题。\n\n【问题】要求2 根据以上情况，下列说法正确的是（）。","options":["海某所做的交易属于看跌期权，期权费为3000元","海某所做的交易属于卖出期权，期权费为300元","海某所做的交易属于买进期权，期权费为3000元","海某所做的交易属于卖出期权，期权费为8000元"],"answer":"A","explain":"该投资者预期股票价格将会下跌，所做交易为看跌期权，期权费为5000×0.6=3000元。"},{"id":"advisor1-105","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】投资者海某预期甲股票价格将会下跌，于是与另一投资者王某订立期权合约，合约规定有效期限为三个月，海某可按每股10元的价格卖出王某甲股票5000股，期权价格为0.6元/股。请根据上述背景信息回答以下问题。\n\n【问题】要求3 如果一个月后，甲股票价格降至每股8元，海某认为时机已到，于是以现货方式买进5000股甲股票，然后按原定合约行使期权卖给王某甲股票5000股。该笔交易海某获利（）元。","options":["2500","5000","7000","10000"],"answer":"C","explain":"海某获利=(10-8)×5000-5000×0.6=7000元。"},{"id":"advisor1-106","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】某证券投资组合的实际平均收益率为15%，期间市场组合的期望收益率为8%，无风险收益率为3.5%，投资组合的系统性风险为12%。请根据上述背景信息回答以下问题。\n\n【问题】要求1 该证券投资组合的詹森（Jensen）指数为（）。","options":["4.04%","11.50%","6.50%","10.96%"],"answer":"D","explain":"E(Ri)=3.5%+12%×(8%-3.5%)=4.04%，詹森α=15%-4.04%=10.96%。"},{"id":"advisor1-107","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】某证券投资组合的实际平均收益率为15%，期间市场组合的期望收益率为8%，无风险收益率为3.5%，投资组合的系统性风险为12%。请根据上述背景信息回答以下问题。\n\n【问题】要求2 该投资组合的特雷诺（Treynor）指数为（）。","options":["0.96","1.05","0.58","1.25"],"answer":"A","explain":"特雷诺比率=(15%-3.5%)/12%=0.96。"},{"id":"advisor1-108","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】某证券投资组合的实际平均收益率为15%，期间市场组合的期望收益率为8%，无风险收益率为3.5%，投资组合的系统性风险为12%。请根据上述背景信息回答以下问题。\n\n【问题】要求3 下列关于詹森指数、特雷诺指数和夏普指数的说法，正确的有（）。","options":["三种指数均是风险调整后收益率的业绩评估指标","三种指数均以资本市场线为基础","三种指数可能会因理论假设方面的局限性导致评价结果失真","夏普指数越低越好"],"answer":"AC","explain":"B选项错误，三种指数均以资本资产定价模型为基础。D选项错误，夏普比率一般来讲是越高越好。"},{"id":"advisor1-109","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】证券投资咨询机构甲和乙根据某投资者的收益要求、风险偏好等特征，分别推荐了A股票投资组合和B股票投资组合。B股票投资组合采用指数型消极投资策略，跟踪某个指数。该指数共有100支成分股，前10支成分股市值在指数中合计权重为50%，股票C在指数中权重为10%。请根据上述背景信息回答问题。\n\n【问题】要求1 可以衡量投资组合收益率的波动程度及损失风险的指标是（）。","options":["最大回撤","持有到期收益率","投资组合规模","货币加强收益率"],"answer":"A","explain":"A选项正确，最大回撤是衡量投资组合收益率的波动程度及损失风险的指标。"},{"id":"advisor1-110","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】证券投资咨询机构甲和乙根据某投资者的收益要求、风险偏好等特征，分别推荐了A股票投资组合和B股票投资组合。B股票投资组合采用指数型消极投资策略，跟踪某个指数。该指数共有100支成分股，前10支成分股市值在指数中合计权重为50%，股票C在指数中权重为10%。请根据上述背景信息回答问题。\n\n【问题】要求2 若A股票投资组合采用了量化中性策略，下列说法错误的有（）。","options":["量化中性策略与市场相关性低","量化中性策略获取相对收益","量化中性策略是指利用统计学、时间序列或机器学习等技术发现市场上的同类金融产品之间的定价误差，进而构建投资组合","量化中性策略属于积极型股票投资策略"],"answer":"BC","explain":"B选项错误，量化中性策略追求绝对收益。C选项错误，量化中性策略是通过对冲工具对冲市场风险，赚取选股组合带来的收益。"},{"id":"advisor1-111","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】证券投资咨询机构甲和乙根据某投资者的收益要求、风险偏好等特征，分别推荐了A股票投资组合和B股票投资组合。B股票投资组合采用指数型消极投资策略，跟踪某个指数。该指数共有100支成分股，前10支成分股市值在指数中合计权重为50%，股票C在指数中权重为10%。请根据上述背景信息回答问题。\n\n【问题】要求3 若B股票投资组合是通过市值法，选取前10支成分股构建的，则股票C在B股票投资组合中的权重为（）。","options":["20%","5%","10%","50%"],"answer":"A","explain":"股票C在前10支中的市值占比为10%÷50%=20%。"},{"id":"advisor1-112","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】我国某企业计划发行10亿元面额为100元、期限为5年的债券，该债券的票面利息为每年10元，于每年年末支付，5年末返本，当年通货膨胀率为3%。请根据材料回答下列问题。\n\n【问题】要求1 该债券的名义收益率是（）。","options":["7%","10%","12%","15%"],"answer":"B","explain":"名义收益率=10/100=10%。"},{"id":"advisor1-113","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】我国某企业计划发行10亿元面额为100元、期限为5年的债券，该债券的票面利息为每年10元，于每年年末支付，5年末返本，当年通货膨胀率为3%。请根据材料回答下列问题。\n\n【问题】要求2 如果该债券市场价格为90元，则该债券的当期收益率为（）。","options":["4%","8%","11.1%","13.5%"],"answer":"C","explain":"当期收益率=10/90≈11.1%。"},{"id":"advisor1-114","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】我国某企业计划发行10亿元面额为100元、期限为5年的债券，该债券的票面利息为每年10元，于每年年末支付，5年末返本，当年通货膨胀率为3%。请根据材料回答下列问题。\n\n【问题】要求3 如果发行时当期收益率为10%，则该债券的发行价格应当是（）元。","options":["80","100","110","125"],"answer":"B","explain":"市场价格=年收入利息/当期收益率=10/10%=100元。"},{"id":"advisor1-115","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】基金投资顾问业务，全称是“公开募集证券投资基金投资顾问”，指试点机构可以接受客户委托，按照协议约定向客户提供基金投资组合策略建议。根据与客户协议约定的投资组合策略，试点机构可以在客户授权的范围内，代客户作出具体基金投资品种、数量和买卖时机的决策，并代客户执行基金产品申购、赎回、转换等交易申请，开展管理型基金投资顾问服务。请根据上述背景信息回答以下问题。\n\n【问题】要求1 基金销售机构申请试点机构提供基金投顾服务，非货币基金保有量不低于（）亿元。","options":["10","50","100","200"],"answer":"C","explain":"C选项正确，基金销售机构申请的，非货币基金保有量不低于100亿元。"},{"id":"advisor1-116","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】基金投资顾问业务，全称是“公开募集证券投资基金投资顾问”，指试点机构可以接受客户委托，按照协议约定向客户提供基金投资组合策略建议。根据与客户协议约定的投资组合策略，试点机构可以在客户授权的范围内，代客户作出具体基金投资品种、数量和买卖时机的决策，并代客户执行基金产品申购、赎回、转换等交易申请，开展管理型基金投资顾问服务。请根据上述背景信息回答以下问题。\n\n【问题】要求2 基金投资顾问机构与普通投资者签订的服务协议应当包括（）。","options":["当事人的权利义务","履行持续注意义务的具体方式","费用收取的项目、标准，以及支付方式","服务终止的情形、程序"],"answer":"ABCD","explain":"A、B、C、D均属于服务协议应当包括的内容。"},{"id":"advisor1-117","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】基金投资顾问业务，全称是“公开募集证券投资基金投资顾问”，指试点机构可以接受客户委托，按照协议约定向客户提供基金投资组合策略建议。根据与客户协议约定的投资组合策略，试点机构可以在客户授权的范围内，代客户作出具体基金投资品种、数量和买卖时机的决策，并代客户执行基金产品申购、赎回、转换等交易申请，开展管理型基金投资顾问服务。请根据上述背景信息回答以下问题。\n\n【问题】要求3 基金投资顾问业务回访包括（）。","options":["老客户回访","客户满意度回访","客户持续管理回访","专项回访"],"answer":"BCD","explain":"B、C、D选项正确，基金投资顾问业务回访包括新开业务客户回访、客户满意度回访、客户持续管理回访、专项回访等。"},{"id":"advisor1-118","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】基金投资顾问业务，全称是“公开募集证券投资基金投资顾问”，指试点机构可以接受客户委托，按照协议约定向客户提供基金投资组合策略建议。根据与客户协议约定的投资组合策略，试点机构可以在客户授权的范围内，代客户作出具体基金投资品种、数量和买卖时机的决策，并代客户执行基金产品申购、赎回、转换等交易申请，开展管理型基金投资顾问服务。请根据上述背景信息回答以下问题。\n\n【问题】要求4 基金投资顾问机构与客户约定由第三方机构对授权账户进行监督的，该第三方机构应当具有基金（）业务资格。","options":["咨询","宣传","托管","销售"],"answer":"C","explain":"C选项正确，第三方机构应当具有基金托管业务资格。"},{"id":"advisor1-119","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷一","q":"【资料】基金投资顾问业务，全称是“公开募集证券投资基金投资顾问”，指试点机构可以接受客户委托，按照协议约定向客户提供基金投资组合策略建议。根据与客户协议约定的投资组合策略，试点机构可以在客户授权的范围内，代客户作出具体基金投资品种、数量和买卖时机的决策，并代客户执行基金产品申购、赎回、转换等交易申请，开展管理型基金投资顾问服务。请根据上述背景信息回答以下问题。\n\n【问题】要求5 基金投资顾问机构开展管理型基金投资顾问业务的，应当（）披露委托资产参考市值。","options":["每日","每周","每月","每季"],"answer":"A","explain":"A选项正确，应当每日披露委托资产参考市值。"}]},{"id":"advisor2","subject":"advisor","name":"证券投顾 · 押题卷二","stats":{"单选":40,"多选":40,"判断":20,"案例":20},"questions":[{"id":"advisor2-0","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"“飓风起于青萍之末”，可以类指（）的证券分析方法。","options":["仔细观察","自上而下","宏观经济分析","自下而上"],"answer":"D","explain":"D选项正确，题中“飓风起于青萍之末”即指自下而上分析法，自下而上分析法则是以个股为切入点，通过财务指标分析寻找具有潜力的公司进行投资。"},{"id":"advisor2-1","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"A方案在三年中每年年初付款100元，B方案在三年中每年年末付款100元，若利率为10%则二者在第三年年末时的终值相差（）元。","options":["33.1","31.3","133.1","13.31"],"answer":"A","explain":"A方案终值=100×[(1+10%)+(1+10%)²+(1+10%)³]=364.1元；B方案终值=100×[(1+10%)²+(1+10%)+1]=331元。二者相差33.1元。"},{"id":"advisor2-2","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"财务报表分析的原则主要有两个：一是坚持全面原则，二是坚持（）原则。","options":["考虑个性","均衡性","非流动性","流动性"],"answer":"A","explain":"A选项正确，财务报表分析的原则包括：坚持全面原则、坚持考虑个性原则。"},{"id":"advisor2-3","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"从家庭生命周期的角度分析，家庭收入以理财收入及转移性收入为主的阶段一般称为家庭（）。","options":["衰老期","成熟期","成长期","形成期"],"answer":"A","explain":"A选项正确，衰老期家庭收入以理财收入和转移性收入为主。"},{"id":"advisor2-4","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"存款准备金利率是（）对金融机构存在央行的准备金支付的利率，分为法定准备金利率和超额准备金利率。","options":["中国证监会","中国人民银行","财政部","中国银监会"],"answer":"B","explain":"B选项正确，存款准备金利率是央行对金融机构存在央行的准备金支付的利率。"},{"id":"advisor2-5","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"弹性价格货币分析法模型是由货币需求函数、货币市场均衡条件及（）三者导出。","options":["非套补利率平价","套补的利率平价","国际收支学说","购买力平价理论"],"answer":"D","explain":"D选项正确，弹性价格货币分析法模型是由货币需求函数、货币市场均衡条件及购买力平价理论三者导出。"},{"id":"advisor2-6","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"当没有投资主张时，看着别人投资什么自己也跟着投资属于（）。","options":["羊群效应","处置效应","损失厌恶","锚定效应"],"answer":"A","explain":"A选项正确，行为金融学中，羊群效应常常用来描述金融市场中投资者盲目从众的行为心理现象。"},{"id":"advisor2-7","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"当中央银行（）时，商业银行可运用的资金减少，贷款能力下降，货币乘数变小，市场货币流通量便会相应减少。","options":["提高法定存款准备金率","提高再贴现率","提高存款准备金率","提高存款率"],"answer":"A","explain":"A选项正确，当中央银行提高法定存款准备金率时，商业银行可运用的资金减少，贷款能力下降，货币乘数变小。"},{"id":"advisor2-8","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"个人生命周期中探索期的主要理财活动是（）。","options":["偿还房贷、筹教育金","量入为出、存自备款","求学深造、提高收入","收入增加、筹退休金"],"answer":"C","explain":"C选项正确，探索期的投资理财活动为求学深造、提高收入。"},{"id":"advisor2-9","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据《证券期货投资者适当性管理办法》，证券经营机构应当（）开展一次适当性自查，形成自查报告。","options":["每月","每半年","每年","每2年"],"answer":"B","explain":"B选项正确，证券经营机构应当每半年开展一次适当性自查，形成自查报告。"},{"id":"advisor2-10","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据资本资产定价模型（CAPM），当我们在衡量某证券的收益率时，其风险溢价收益应为（）。","options":["无风险利率和贝塔（β）的乘积","贝塔（β）和市场预期收益率的乘积","无风险利率和市场风险溢价之和","贝塔（β）和市场风险溢价的乘积"],"answer":"D","explain":"D选项正确，风险溢价收益=βi×[E(Rm)-Rf]。"},{"id":"advisor2-11","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"假定汪先生当前投资某项目，期限为3年，第一年年初投资100000元，第二年年初又追加投资50000元，年收益率为10%，那么他在3年内每年末至少收回（）元才是盈利的。","options":["33339","43333","58489","44386"],"answer":"C","explain":"第一年投资终值=100000×(1+10%)³=133100元；第二年投资终值=50000×(1+10%)²=60500元；总终值=193600元。年金A=193600×10%/[(1+10%)³-1]=58489元。"},{"id":"advisor2-12","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"久期缺口是资产加权平均久期减去负债加权平均久期与（）的乘积。","options":["收益率","资产负债率","现金率","市场利率"],"answer":"B","explain":"B选项正确，久期缺口是资产加权平均久期减去负债加权平均久期与资产负债率的乘积。"},{"id":"advisor2-13","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"就单根K线而言，反映多方占据绝对优势的K线形状是（）。","options":["带有较长上影线的阳线","大阴线实体","大阳线实体","大十字星"],"answer":"C","explain":"C选项正确，大阳线实体意味着多方已经取得决定性的胜利。"},{"id":"advisor2-14","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"考察和分析企业的（），主要从管理层风险，行业风险，生产与经营风险，宏观经济，社会及自然环境等方面进行分析和判断。","options":["基本信息","财务状况","经营状况","非财务因素"],"answer":"D","explain":"D选项正确，非财务分析是对法人客户管理层领导能力、生产经营能力、内部控制及风险管理能力，以及所处的宏观、区域、行业、社会等经营环境进行全面综合分析的过程。"},{"id":"advisor2-15","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"了解客户信息是投资顾问提供专业化服务的基础内容和必要工作步骤，下列不属于客户的非财务信息是（）。","options":["收入和支出","家庭状况","职业信息","投资偏好"],"answer":"A","explain":"A选项符合题意，收入和支出属于财务信息。"},{"id":"advisor2-16","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"利率下降，则债券的贴现率（），债券价格（）。","options":["上升，下降","下降，下降","上升，上升","下降，上升"],"answer":"D","explain":"D选项正确，利率和债券价格之间呈现反向变动关系，即利率下降，债券价格上升。"},{"id":"advisor2-17","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"某公司上一年度每股收益为1元，公司未来每年每股收益以5%的速度增长，公司未来每年的所有利润都分配给股东。如果该公司股票今年年初的市场价格为35元，并且必要收益率为10%，据此下列说法错误的是（）。","options":["该公司股票今年年初的内在价值约等于39元","该公司股票的内部收益率为8%","该公司股票今年年初市场价格被高估","持有该公司股票的投资者应当在今年年初卖出该公司股票"],"answer":"A","explain":"A选项错误，内在价值=1×(1+5%)/(10%-5%)=21元。"},{"id":"advisor2-18","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"某客户准备对原油进行对冲交易，现货价格为40美元/桶，1个月后的期货价格为45美元/桶，则零时刻的基差是（）美元。","options":["-8","-5","- 3","3"],"answer":"B","explain":"B选项正确，基差=现货价格-期货价格=40-45=-5美元。"},{"id":"advisor2-19","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"某零息债券在到期日的价值1000元，偿还期为10年，该债券的到期收益率为5%，则其久期为（）年。","options":["9","8","10","7"],"answer":"C","explain":"C选项正确，零息债券的久期等于其到期时间，即10年。"},{"id":"advisor2-20","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"目前不存在完全垄断的市场，我国接近完全垄断的行业有（）。","options":["自来水","纺织","石油","钢铁"],"answer":"A","explain":"A选项正确，公用事业（如发电厂、煤气公司、自来水公司和邮电通信等）属于接近完全垄断的市场类型。"},{"id":"advisor2-21","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"特雷诺比率以（）作为风险的度量。","options":["单位系统性风险","非系统性风险","系统性风险","资本性风险"],"answer":"A","explain":"A选项正确，特雷诺比率以单位系统性风险作为风险的度量。"},{"id":"advisor2-22","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"通常来说，指数化投资策略是（）的代表。","options":["战术性投资策略","战略性投资策略","被动型投资策略","主动型投资策略"],"answer":"C","explain":"C选项正确，通常将指数化投资策略视为消极投资策略（被动型投资策略）的代表。"},{"id":"advisor2-23","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"王某有1万元现金，5万元定期基金，20万元的房产，每月的生活费为0.5万元，还需要偿还房贷0.5万元，那么他的失业保障月数为（）个月。","options":["6","8","28","3"],"answer":"A","explain":"A选项正确，失业保障月数=(1+5)/(0.5+0.5)=6。"},{"id":"advisor2-24","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列对证券投资顾问人员注册登记管理的说法中，错误的是（）。","options":["证券投资顾问不得同时注册为证券分析师","证券投资顾问可以同时注册为证券分析师，但应分开管理以防止可能的利益冲突","向客户提供证券投资顾问服务的人员，应当符合相关从业条件","向客户提供证券投资顾问服务的人员应在中国证券业协会注册登记为证券投资顾问"],"answer":"B","explain":"B选项错误，证券投资顾问不得同时注册为证券分析师。"},{"id":"advisor2-25","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列各项中，（）在每个层次中再度按照权重选取前几位的股票构建模拟组合。","options":["分类法","最优法","分层法","完全法"],"answer":"C","explain":"C选项正确，分层法将投资组合按照某种标准分成若干层次，然后在每个层次中再度按照权重选取前几位的股票构建模拟组合。"},{"id":"advisor2-26","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于基金投资顾问业务的说法中，错误的是（）","options":["试点机构应当通过风险揭示书等向客户充分揭示相关风险","以预收方式收取的基金投资顾问服务费在确认为投资顾问收入前，可以用于人员激励","试点机构应当制定统一的基金投资组合策略说明书","合规、风控部门每季度应当对基金投资组合策略及实施有效性进行核查评估"],"answer":"B","explain":"B选项错误，以预收方式收取的基金投资顾问服务费在确认为投资顾问收入前，不得用于人员激励。"},{"id":"advisor2-27","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列属于绝对估值法是（）。","options":["市盈率","市净率","现金流折现法","企业价值/息税前利润"],"answer":"C","explain":"C选项符合题意，各种基于现金流贴现的方法均属绝对估值法。"},{"id":"advisor2-28","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列行业属于防守型行业的是（）。","options":["TMT行业","食品类","消耗品","商业"],"answer":"B","explain":"B选项正确，防守型行业的产品往往是生活必需品或是必要的公共服务，公众对其产品有相对稳定的需求，如食品业和公用事业。"},{"id":"advisor2-29","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列因素中不会影响银行等金融机构资产负债期限结构的是（）。","options":["金融机构新增营业网点数量","股票市场投资收益率上涨5%","客户新增贷款或融资需求","央行宣布上调利率0.25%"],"answer":"A","explain":"A选项符合题意，新增营业网点数量不会影响到期资产、到期负债问题。"},{"id":"advisor2-30","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"一般而言，风险厌恶型客户的投资需求多倾向于（）。","options":["股票型基金","股票","混合型基金","固定收益类基金"],"answer":"D","explain":"D选项符合题意，风险厌恶型投资者适合投资工具包括安全性较高的定期存款、大额存单、国债以及保险等。"},{"id":"advisor2-31","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"以下不属于证券公司、证券投资咨询机构向客户提供证券投资顾问服务应当告知客户的基本信息的是（）。","options":["投资决策由客户作出，投资风险由客户承担","证券投资顾问服务的内容和方式","证券投资顾问的姓名","与投资人约定分享投资收益"],"answer":"D","explain":"D选项符合题意，与投资人约定分享投资收益不属于应当告知客户的基本信息。"},{"id":"advisor2-32","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"影响资产配置的主要因素（）。","options":["投资期限","流动性要求","生命周期","资产规模"],"answer":"C","explain":"C选项正确，一般情况下，对于个人投资者而言，生命周期是影响资产配置的最主要因素。"},{"id":"advisor2-33","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"与老年父母同住或者夫妻两人同住的情形，出现在（）。","options":["成长期","成熟期","稳定期","衰老期"],"answer":"B","explain":"B选项正确，家庭成熟期的居住状况为与老年父母同住或夫妻两人居住。"},{"id":"advisor2-34","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"在（），创业公司的研究和开发费用较高，销售收入较低。","options":["幼稚期","成长期","成熟期","衰退期"],"answer":"A","explain":"A选项正确，在初创期（幼稚期），创业公司的研究和开发费用较高，销售收入较低。"},{"id":"advisor2-35","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"在半强式有效市场中，下列说法中，错误的是（）。","options":["基本面分析无效","反映了公开信息","技术分析无效","反映了内幕信息"],"answer":"D","explain":"D选项错误，在半强式有效市场中，资产价格已经反映了所有公开信息，不包括内幕信息。"},{"id":"advisor2-36","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"在收集客户信息的过程中，属于定性信息的是（）。","options":["资产负债状况","投资组合","投资偏好","投资经验"],"answer":"C","explain":"C选项符合题意，定性信息更多关注客户的意愿、偏好和目标，包括投资偏好等。"},{"id":"advisor2-37","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"证券A的贝塔系数是1.2，证券B的贝塔系数是0.8，下列正确的是（）","options":["证券A的非系统风险最大","证券B的非系统风险最大","证券A的系统风险最大","证券B的系统风险最大"],"answer":"C","explain":"C选项正确，β系数是衡量证券承担系统风险水平的指数，证券A的β系数大于证券B，因此证券A的系统风险最大。"},{"id":"advisor2-38","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"证券市场技术分析是以一定的假设条件为前提的，这些假设不包括（）。","options":["市场行为涵盖一切信息","证券价格沿趋势移动","历史会重演","指标须可靠"],"answer":"D","explain":"D选项符合题意，指标须可靠不是证券市场技术分析的前提假设条件。"},{"id":"advisor2-39","subject":"advisor","type":"单选","source":"2026.09 LC终极押题 · 押题卷二","q":"证券投资顾问可以通过广播、电视、网络、报刊等公众媒体，客观、专业、审慎地对（）发表评论意见。","options":["特定的分级基金","特定的指数期货合约","某上市公司","宏观经济、行业状况、证券市场变动情况"],"answer":"D","explain":"D选项正确，可以对宏观经济、行业状况、证券市场变动情况发表评论意见。"},{"id":"advisor2-40","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"ETF的特点包括（）。","options":["被动操作的指数基金","独特的实物申购、赎回机制","主动操作的指数基金","实行一级市场与二级市场并存的交易制度"],"answer":"ABD","explain":"ETF的特点有：（1）被动操作的指数基金；（2）独特的实物申购、赎回机制；（3）实行一级市场与二级市场并存的交易制度。"},{"id":"advisor2-41","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"按投资风格划分，股票投资策略可分为（）。","options":["价值型投资策略","成长性投资策略","平衡型投资策略","另类型投资策略"],"answer":"ABC","explain":"按照投资风格划分，可分为价值型投资策略、成长型投资策略和平衡型投资策略。"},{"id":"advisor2-42","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"反转突破的几种形态中，未来走势向下的可能性较大的有（）。","options":["头肩顶形态","头肩底形态","双重顶形态","圆弧顶形态"],"answer":"ACD","explain":"B选项错误，头肩底是头肩顶的倒转形态，是一个可靠的买进时机，未来走势向上的可能性较大。"},{"id":"advisor2-43","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"个人投资者的特点包括（）。","options":["投资的专业性强","资金规模有限","专业知识相对匮乏","投资行为具有随意性、分散性和短期性"],"answer":"BCD","explain":"A选项不符合题意，投资的专业性强属于机构投资者的特点。"},{"id":"advisor2-44","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据可贷资金理论，以下说法正确的是（）。","options":["储蓄S（i），与利率正相关","货币供给增加额ΔMs（i）货币供给变动是由央行决定的","货币供给变动与利率正相关","利率与货币反窖藏正相关"],"answer":"ABCD","explain":"A、B、C、D均正确。"},{"id":"advisor2-45","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"根据有效市场理论，下列说法正确的是（）。","options":["在有效率的市场中，投资者所获得的收益只能是与其承担的风险相匹配的那部分正常收益，而不会有高出风险补偿的超额收益","只要证券价格充分反映了全部有价值的信息，市场价格代表着证券的真实价值，这样的市场就称为有效市场","在有效率的市场中，不存在非正常报酬","在有效率的市场中，一组特定的信息能够在股票市场上随即被投资者知晓"],"answer":"ABCD","explain":"A、B、C、D均正确。"},{"id":"advisor2-46","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"构建基金组合的步骤有（）。","options":["风险承受能力评估","确定投资目标","确定配置方案","定量评价"],"answer":"ABC","explain":"D选项错误，定量评价属于后续绩效评估环节的方法。"},{"id":"advisor2-47","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"关于RSI的应用法则，下列说法正确的是（）。","options":["将100分成五个区域，根据RSI的取值落入的区域进行操作","股票越活跃，RSI所能达到的高度越高","RSI的取值范围介于050之间","当短期RSI>长期RSI时，属多头市场"],"answer":"BD","explain":"A选项错误，将100分成四个区域。C选项错误，RSI的取值范围介于0100之间。"},{"id":"advisor2-48","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"关于客户的证券投资需求与理财需求间的关系，下列说法正确的有（）。","options":["证券投资是客户个人理财需求的一个重要组成部分","收入越高的客户越热衷于以证券投资需求为其主要理财方式","券商可以给客户设计出风险偏低的证券投资组合","对于偏好银行理财产品的客户，股票投资是属于偏激进型"],"answer":"ACD","explain":"B选项错误，客户选择何种理财方式为主要方式，并非仅由收入高低决定。"},{"id":"advisor2-49","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"关于外币汇率上升、本币贬值对证券市场影响，下列说法正确的有（）。","options":["导致资本流出本国，证券市场需求减少市场价格下跌","本币表示的进口商品价格提高，带动国内物价水平上涨，引起通货膨胀","出口型企业的股票价格上涨","政府可能动用外汇储备，抛售外汇减少本币供应量，证券市场价格下跌"],"answer":"ABCD","explain":"A、B、C、D均正确。"},{"id":"advisor2-50","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"管理型投资顾问业务的投资组合管理及资产配置步骤包括（）。","options":["明确投资组合管理的目标","制定投资组合管理政策","建立战略性资产配置","对证券投资组合进行修正"],"answer":"ABCD","explain":"A、B、C、D均属于管理型投资顾问业务的投资组合管理及资产配置步骤。"},{"id":"advisor2-51","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"划分产品或者服务风险等级时应综合考虑的因素有（）。","options":["流动性","杠杆情况","募集方式","投资单位产品或者相关服务的最高金额"],"answer":"ABC","explain":"D选项错误，应为投资单位产品或者相关服务的最低金额。"},{"id":"advisor2-52","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"技术分析方法包括（）方法。","options":["价格类","形态类","指标类","K线类"],"answer":"BCD","explain":"A选项错误，技术分析方法分为K线类、切线类、形态类、波浪类、指标类。"},{"id":"advisor2-53","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"家庭紧急预备金的储存形式包括（）。","options":["短期定期存款","活期存款","货币市场基金","未使用的贷款融资额度"],"answer":"ABCD","explain":"A、B、C、D均属于家庭紧急预备金的储存形式。"},{"id":"advisor2-54","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"敏感性分析是指在保持其他条件不变的前提下，研究单个市场风险要素，包括（）的微小变化可能会对金融工具或资产组合的收益或经济价值产生的影响。","options":["股票价格","商品价格","利率","汇率"],"answer":"ABCD","explain":"A、B、C、D均正确。"},{"id":"advisor2-55","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"某投资者于年初将10万元本金按年利率8%进行投资，那么，该项投资（）。","options":["按单利计算，在投资第二年年末的终值为11.4万元","按单利计算，在投资第三年年末的终值为12.4万元","按复利计算，在投资第二年年末的终值为11.664万元","按复利计算，在投资第三年年末的终值为15.3896万元"],"answer":"BC","explain":"A选项错误，单利第二年年末终值=10×(1+8%×2)=11.6万元。D选项错误，复利第三年年末终值=10×(1+8%)³=12.59712万元。"},{"id":"advisor2-56","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"评价组合管理的业绩需考虑的主要因素包括（）。","options":["组合收益的高低","组合承担的风险","组合的规模","组合管理者的收入"],"answer":"AB","explain":"A、B选项符合题意，证券投资组合的业绩评价既要考虑组合收益的高低，也要考虑组合所承担风险的大小。"},{"id":"advisor2-57","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"投资顾问在对客户正常情况下的收入进行预测时，主要预测（）。","options":["常规性收入","收入最低情况下的收入","临时性收入","上一年的实际收入"],"answer":"AC","explain":"A、C选项正确，在预测客户未来收入时，可以将收入分为常规性收入和临时性收入两类。"},{"id":"advisor2-58","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"我国目前拥有的信用风险缓释工具包括（）。","options":["信用风险缓释合约","信用风险缓释凭证","信用违约互换","信用联结票据"],"answer":"ABCD","explain":"A、B、C、D均属于我国目前拥有的信用风险缓释工具。"},{"id":"advisor2-59","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列对主观CTA策略的表述，说法正确的有（）。","options":["主观CTA策略是指投资决策方式为主观研究、主观决策和主观交易的策略","主观CTA策略对期货合约的历史交易数据进行统计","主观CTA策略的研究重点是期货合约的标的物价格的走势和变化","主观CTA策略考量的是投资经理对基本面或产业链的研究能力"],"answer":"ACD","explain":"B选项错误，量化CTA策略对期货合约的历史交易数据进行统计。"},{"id":"advisor2-60","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列各类公司或行业，不适宜采用市盈率进行估值的有（）。","options":["成熟行业","亏损公司","周期性公司","服务行业"],"answer":"BC","explain":"B、C选项正确，市盈率估值方法一般适用于周期性较弱企业，不适用于亏损公司、周期性公司。"},{"id":"advisor2-61","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列各项中，（）属于货币时间价值的影响因素。","options":["通货膨胀率","单利","复利","时间"],"answer":"ABCD","explain":"A、B、C、D均属于货币时间价值的影响因素。"},{"id":"advisor2-62","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列各项中，可以证实市场不是半强式有效市场的有（）。","options":["股票分割消息宣布后不产生利得","内幕知情人可以从内幕交易中获利","投资者在盈余宣布很长时间后才能做出交易反应","基于公司规模及股票账面价值与市场的比率的投资策略可以从中获利"],"answer":"CD","explain":"C、D选项错误，基本分析有效，可以证实市场不是半强式有效市场。"},{"id":"advisor2-63","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于ρAB的说法正确的是（）。","options":["当ρAB=1时，弯曲程度最大，呈直线","当ρAB=1时，弯曲程度最小，呈直线","当ρAB=1时，弯曲程度最小，呈折线","当ρAB=-1时，弯曲程度最大，呈折线"],"answer":"BD","explain":"B、D选项正确。当ρAB=1时，弯曲程度最小，呈直线；当ρAB=-1时，弯曲程度最大，呈折线。"},{"id":"advisor2-64","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于从事证券投资顾问业务违反相关法律法规的后果说法错误的是（）。","options":["由中国证监会及其派出机构给予处罚","涉嫌犯罪的，由司法机关依法量刑","情节严重的，由司法机关依照法律、行政法规和有关规定作出行政处罚","中国证监会及其派出机构采取的处罚措施中不包括暂停新增客户"],"answer":"CD","explain":"C选项错误，情节严重的，中国证监会依照法律、行政法规和有关规定作出行政处罚。D选项错误，中国证监会及其派出机构采取的处罚措施中包括责令暂停新增客户。"},{"id":"advisor2-65","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于缺口分析法的说法中，正确的有（）。","options":["只要不存在流动性缺口，就不存在流动性风险","流动性缺口就是融资性缺口","缺口分析法是针对未来特定时段，计算到期资产和到期负债之间的差额","通过判断流动性缺口，可以判断金融机构不同时段内流动性是否充足"],"answer":"CD","explain":"A选项错误，流动性缺口仅为衡量风险的指标之一。B选项错误，流动性缺口与融资性缺口不同。"},{"id":"advisor2-66","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列关于证券市场的说法中，错误的有（）。","options":["证券市场供给的主体是投资银行，其数量是证券市场供给的主要影响因素","宏观经济环境的变化对证券市场供给影响不大","上市公司的质量状况会影响公司的再融资，从而影响股票的供给","股权分置改革对证券市场供给影响不大"],"answer":"ABD","explain":"A选项错误，证券市场的供给主体是上市公司（企业）、政府与政府机构以及金融机构。B选项错误，宏观经济环境的变化对证券市场供给影响较大。D选项错误，股权分置改革对证券市场供给影响很大。"},{"id":"advisor2-67","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列说法正确的有（）","options":["套利定价理论和马柯威茨理论一样都属于多因素模型","套利定价理论有三个基本假设","套利定价理论认为，只有投资者的套利行为不断进行直至套利机会出现，市场才能形成证券的均衡价格","套利定价理论认为，只有投资者的套利行为不断进行直至套利机会消失，市场才能形成证券的均衡价格"],"answer":"BD","explain":"A选项错误，套利定价理论是典型的多因素模型。C选项错误，只有套利行为不断进行直至套利机会消失，市场才能形成证券的均衡价格。"},{"id":"advisor2-68","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列行业中，美林投资时钟模型的指导意义相对较强的有（）。","options":["可选消费","石油和天然气","电信","公共事业"],"answer":"AB","explain":"A、B选项符合题意，可选消费和石油天然气属于顺周期行业，美林投资时钟指导意义强。"},{"id":"advisor2-69","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"下列应列入个人现金流量表的是（）。","options":["利息收入","股票","头发护理费用","汽车及住房"],"answer":"AC","explain":"A、C选项正确，利息收入和头发护理费用属于现金流量表项目。"},{"id":"advisor2-70","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"有效市场的支持者极力主张（）。","options":["价值投资","投资于指数基金","被动性的投资策略","主动性的投资策略"],"answer":"BC","explain":"B、C选项正确，信奉市场有效性的投资者会主张被动型投资策略，投资于指数基金。"},{"id":"advisor2-71","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"与股票基金相比，债券基金的特点有（）。","options":["适合追求稳定收入的投资者","不受经济环境变化的影响","收益、风险适中","波动相对较小"],"answer":"ACD","explain":"B选项错误，债券基金也会受经济环境变化的影响。"},{"id":"advisor2-72","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"预计某公司今年年末每股收益为2元，每股股息支付率为90%，并且该公司以后每年每股股利将以5%的速度增长。如果某投资者希望内部收益率不低于10%，那么，（）。","options":["他在今年年初购买该公司股票的价格应小于18元","他在今年年初购买该公司股票的价格应大于38元","他在今年年初购买该公司股票的价格应不超过36元","该公司今年年末每股股利为1.8元"],"answer":"CD","explain":"今年年末每股股利=2×90%=1.8元。购买价格不超过1.8/(10%-5%)=36元。"},{"id":"advisor2-73","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"张某今年56岁，目前没有家庭债务负担，且其儿子已经工作并结婚。下述关于理财规划的表述，适合张某的是（）。","options":["以保守稳健型投资为主，配以适当比例的进取型投资","以活期、定期储蓄为主","以中高风险的组合投资为主要财务投资手段","多配置基金、债券、储蓄、固定收益理财产品"],"answer":"AD","explain":"A、D选项正确，张某属于个人生命周期的高峰期，应以稳健型投资为主。"},{"id":"advisor2-74","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"证券公司、证券投资咨询机构及其人员从事证券投资顾问业务，违反法律、行政法规和相关规定的，中国证监会及其派出机构可以采取监管措施，下列属于相关监管措施的有（）。","options":["监管谈话","出具警示函","处以罚款","责令处分有关人员"],"answer":"ABD","explain":"C选项错误，“处以罚款”属于行政处罚。"},{"id":"advisor2-75","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"证券公司、证券投资咨询机构可以组织证券投资顾问，通过广播电视、网络、报刊等公众媒体，客观、专业、审慎地（）。","options":["对宏观经济、行业状况发表评论意见","对证券市场变动情况发表评论意见","提供买入、卖出或持有具体证券的投资建议","提供股票组合的买入卖出建议"],"answer":"AB","explain":"C、D选项错误，属于禁止性行为。"},{"id":"advisor2-76","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"证券经营机构向投资者销售产品或提供服务时，应当了解投资者的下列（）信息。","options":["财务状况","投资经验","投资目标","诚信记录"],"answer":"ABCD","explain":"A、B、C、D均属于应当了解的信息。"},{"id":"advisor2-77","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"证券投资咨询业务的基本形式包括（）。","options":["证券投资顾问","委托理财","发布证券研究报告","销售基金"],"answer":"AC","explain":"A、C选项符合题意，证券投资顾问和发布证券研究报告业务是证券投资咨询业务的两类基本形式。"},{"id":"advisor2-78","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"证券相对估值的常用指标包括（）。","options":["市盈率","权益现金流","经济增加值与利息折旧摊销前收入比","资本现金流"],"answer":"AC","explain":"A、C选项正确，市盈率、经济增加值与利息折旧摊销前收入比等均属相对估值方法。"},{"id":"advisor2-79","subject":"advisor","type":"多选","source":"2026.09 LC终极押题 · 押题卷二","q":"资本资产定价模型的假设条件包括（）。","options":["证券的收益率具有确定性","资本市场没有摩擦","投资者都依据组合的期望收益率和方差选择证券组合","投资者对证券的收益和风险及证券间的关联性具有完全相同的预期"],"answer":"BCD","explain":"B、C、D选项正确，资本资产定价模型的假设条件包括资本市场没有摩擦、投资者依据期望收益率和方差选择证券组合、投资者具有完全相同的预期。"},{"id":"advisor2-80","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"“倒微笑曲线周期”是基金定投最不适合的市场条件，投资者需要在可能出现的“倒微笑曲线周期”及时止盈。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"advisor2-81","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"从价值链的角度来看，对不同国家和地区间产业竞争力的比较，需要建立在最终产品或服务的比较上，特别是需要就产业价值链条上的某几个价值环节的经济效益进行比较。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。并不一定需要建立在最终产品或服务的比较上。"},{"id":"advisor2-82","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"道氏理论认为，最重要的价格是收盘价。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"advisor2-83","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"短期债券一般不付息，而是到期一次性还本。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"advisor2-84","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"风险认知度反映的是客户主观上对风险的基本态度，也是一种不确定性在客户心理上产生的影响。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。风险偏好反映的是客户主观上对风险的基本态度。"},{"id":"advisor2-85","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"风险转移可分为保险转移和非保险转移。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"advisor2-86","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"管理型基金投资顾问服务的单个客户持有单只基金的市值，不得高于该客户委托资产市值的10%，货币市场基金、指数基金不受此限。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。应为不得高于该客户委托资产市值的20%。"},{"id":"advisor2-87","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"基金投资顾问业务试点机构应当在负责投资业务的部门层面建立专门的投资决策委员会负责审议投资组合策略的产生和调整，并评估形成投资组合策略的风险特征。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。投资决策委员会是公司层面建立的。"},{"id":"advisor2-88","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"考察公司短期偿债能力的关键是考察公司的资金周转能力。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。变现能力是考察公司短期偿债能力的关键。"},{"id":"advisor2-89","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"利率与债券的价格呈正相关关系。","options":["正确","错误"],"answer":"B","explain":"本题说法错误。债券的价格与利率呈反向关系。"},{"id":"advisor2-90","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"两个风险证券的相关系数越小，它们构造组合形成的可行域弯曲度越小。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。相关系数越小，可行域的弯曲程度越大。"},{"id":"advisor2-91","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"三角形态是属于持续整理形态的一类形态，三角形主要分为对称三角形、上升三角形和下降三角形。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"advisor2-92","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"稳健型投资者既不厌恶风险也不追求风险，对任何投资都比较理性，往往会仔细分析不同的投资市场、工具与产品，从中寻找风险适中、收益适中的产品、获得社会平均水平的收益，同时承受社会平均风险。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。应为平衡型投资者。"},{"id":"advisor2-93","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"信用风险缓释是指通过控制措施降低风险的损失频率或影响程度，在银行业中，信用风险缓释通过抵质押品、净额结算等工具转移信用风险。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"advisor2-94","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"一般来说，买卖价差越大，流动性风险越高；成交量越大，流动性越好，流动性风险就越低。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"advisor2-95","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"证券公司、证券投资咨询机构应当按照公平、合理、自愿的原则，与客户协商并书面约定收取证券投资顾问服务费用的安排，可以按照服务期限、客户资产规模收取服务费用，不可以采用差别佣金等其他方式收取服务费用。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。也可以采用差别佣金等其他方式收取服务费用。"},{"id":"advisor2-96","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"证券经营机构对销售的产品划分风险等级时需要考虑产品的到期期限。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"advisor2-97","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"证券经营机构可以将产品或服务风险等级由低至高至少划分为五级。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。"},{"id":"advisor2-98","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"资本资产定价模型在分析问题的过程中，不考虑交易成本对红利、股息以及资本利得的征税，但限制借贷和卖空。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。CAPM的核心假设是无摩擦市场+无限制借贷/卖空。"},{"id":"advisor2-99","subject":"advisor","type":"判断","source":"2026.09 LC终极押题 · 押题卷二","q":"资产配置可以分为战略配置和战术配置两个层次。战略资产配置重在长期回报，不考虑资产的短期波动，其投资期限可以长达5年以上。战术资产配置更多关注市场的短期波动，通过择时调节大类资产之间的分配比例，战术资产配置的模型主要有均值方差模型等。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。均值-方差模型属于战略资产配置模型。"},{"id":"advisor2-100","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】假设证券市场只有证券A和证券B，证券A和证券B的期望收益率分别为6%和12%，β系数分别为0.6和1.2，无风险借贷利率为3%。根据上述材料，回答下列各小题。\n\n【问题】要求1 根据资本资产定价模型，（）","options":["这个证券市场不处于均衡状态","这个证券市场处于均衡状态","证券A的单位系统风险补偿为0.05","证券B的单位系统风险补偿为0.075"],"answer":"ACD","explain":"证券A的单位系统风险补偿=(6%-3%)/0.6=0.05；证券B的单位系统风险补偿=(12%-3%)/1.2=0.075。当市场均衡时，单位系统风险补偿应该相同，因此市场不处于均衡状态。"},{"id":"advisor2-101","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】假设证券市场只有证券A和证券B，证券A和证券B的期望收益率分别为6%和12%，β系数分别为0.6和1.2，无风险借贷利率为3%。根据上述材料，回答下列各小题。\n\n【问题】要求2 一般而言，资本资产定价模型的应用领域包括（）。","options":["投资决策","证券投资预算","公司理财","预测股票市场的变动趋势"],"answer":"AC","explain":"资本资产定价模型广泛应用于投资决策和公司理财领域。"},{"id":"advisor2-102","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】某期国债距到期日还有3年，面值100元，票面利率年息3.75%，每年付息一次，下次付息日在1年以后。1年期、2年期、3年期贴现率分别为3%、4%、5.5%。请根据上述背景信息回答以下问题。\n\n【问题】要求1 该债券的理论价格为（）元。","options":["96.67","95.46","95.74","96.57"],"answer":"B","explain":"P=3.75/(1+3%)+3.75/(1+4%)²+103.75/(1+5.5%)³≈95.46元。"},{"id":"advisor2-103","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】某期国债距到期日还有3年，面值100元，票面利率年息3.75%，每年付息一次，下次付息日在1年以后。1年期、2年期、3年期贴现率分别为3%、4%、5.5%。请根据上述背景信息回答以下问题。\n\n【问题】要求2 下列属于债券估值模型的是（）。","options":["零息债券定价","附息债券定价","累息债券定价","资产报酬率"],"answer":"ABC","explain":"债券估值模型包括：零息债券定价、附息债券定价、累息债券定价。"},{"id":"advisor2-104","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】某公司为扩大业务范围，在上海证券交易所通过发行债券的方式筹集资金，共发行面值为100元、票据利率为5%、到期期限为3年的债券10亿元，每年11月20日支付利息，到期还本付息，假定未来3年市场利率一直保持为5%。请根据上述背景信息回答以下问题。\n\n【问题】要求1 该债券的投资者每张债券第一年后收到的第一笔利息的现值为（）元。","options":["4.5","4.55","4.76","5.05"],"answer":"C","explain":"债券持有一年获得的利息=100×5%=5元，PV=5/(1+5%)=4.76元。"},{"id":"advisor2-105","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】某公司为扩大业务范围，在上海证券交易所通过发行债券的方式筹集资金，共发行面值为100元、票据利率为5%、到期期限为3年的债券10亿元，每年11月20日支付利息，到期还本付息，假定未来3年市场利率一直保持为5%。请根据上述背景信息回答以下问题。\n\n【问题】要求2 该债券的发行价格应为（）元。","options":["86.38","90.7","95.23","100.00"],"answer":"D","explain":"市场利率等于债券收益率时，债券的市场价格（购买价）等于债券面值，即债券为平价发行。"},{"id":"advisor2-106","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】某公司为扩大业务范围，在上海证券交易所通过发行债券的方式筹集资金，共发行面值为100元、票据利率为5%、到期期限为3年的债券10亿元，每年11月20日支付利息，到期还本付息，假定未来3年市场利率一直保持为5%。请根据上述背景信息回答以下问题。\n\n【问题】要求3 该债券的投资者以发行价格买入该债券，持有至到期的收益率为（）。","options":["7.00%","4.55%","5.00%","5.23%"],"answer":"C","explain":"市场利率等于债券收益率时，债券为平价发行，其获得的收益率应等于其息票利率，即5%。"},{"id":"advisor2-107","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】某投资者计划通过跟踪指数的方式参与股票投资，并购买了一只指数基金，该基金采用完全复制的方式对指数进行跟踪。请根据上述背景信息回答以下问题。\n\n【问题】要求1 该投资者采用的投资策略是（）。","options":["主动投资策略","自上而下策略","被动投资策略","自下而上策略"],"answer":"C","explain":"该投资是用跟踪指数的方式参与股票投资，属于指数化投资策略，指数化投资策略是被动投资策略。"},{"id":"advisor2-108","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】某投资者计划通过跟踪指数的方式参与股票投资，并购买了一只指数基金，该基金采用完全复制的方式对指数进行跟踪。请根据上述背景信息回答以下问题。\n\n【问题】要求2 下列变化会增加该投资者购买的指数基金相对于基准指数的跟踪误差的有（）。","options":["指数成分股的交易流动性下降","基金管理人下调基金管理费","基金管理人增加投资组合中的现金比例","国家下调证券交易印花税"],"answer":"AC","explain":"A选项正确，流动性下降会导致交易成本增加，增大跟踪误差。C选项正确，持有现金相当于未完全投资，会增大跟踪误差。"},{"id":"advisor2-109","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】某投资者计划通过跟踪指数的方式参与股票投资，并购买了一只指数基金，该基金采用完全复制的方式对指数进行跟踪。请根据上述背景信息回答以下问题。\n\n【问题】要求3 该投资者眼中的股票市场有可能是（）。","options":["半弱式有效市场","半强式有效市场","弱式有效市场","强式有效市场"],"answer":"BCD","explain":"该投资者使用指数化投资策略，说明他认为市场是有效市场，有效市场分为强式有效市场、半强式有效市场和弱式有效市场。"},{"id":"advisor2-110","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】某公司的企业公司上年度自由现金流为5000000元，预计今年自由现金流增长率为5%，公司的负债比率（负债/总资产）为20%，股票投资者必要收益率为16%，负债的税前成本为8%，税率为25%，公司负债市场价值11200000元，公司现有2000000股普通股发行在外。请根据上述背景信息回答以下问题。\n\n【问题】要求1 根据企业自由现金流贴现模型，采用的贴现率为（）。","options":["必要回报率","最低回报率","加权平均资本成本","算术平均资本成本"],"answer":"C","explain":"企业自由现金流贴现模型采用企业加权平均资本成本（WACC）为贴现率。"},{"id":"advisor2-111","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】某公司的企业公司上年度自由现金流为5000000元，预计今年自由现金流增长率为5%，公司的负债比率（负债/总资产）为20%，股票投资者必要收益率为16%，负债的税前成本为8%，税率为25%，公司负债市场价值11200000元，公司现有2000000股普通股发行在外。请根据上述背景信息回答以下问题。\n\n【问题】要求2 上述材料的贴现率为（）。","options":["12%","13%","14%","15%"],"answer":"C","explain":"WACC=0.8×16%+0.2×8%×(1-25%)=12.8%+1.2%=14%。"},{"id":"advisor2-112","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】某公司的企业公司上年度自由现金流为5000000元，预计今年自由现金流增长率为5%，公司的负债比率（负债/总资产）为20%，股票投资者必要收益率为16%，负债的税前成本为8%，税率为25%，公司负债市场价值11200000元，公司现有2000000股普通股发行在外。请根据上述背景信息回答以下问题。\n\n【问题】要求3 股票的内在价值为（）元/股。","options":["21.57","22.57","23.57","24.57"],"answer":"C","explain":"公司价值=5250000/(14%-5%)≈58333333元。股权价值=58333333-11200000=47133333元。每股内在价值=47133333/2000000≈23.57元。"},{"id":"advisor2-113","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】某投资机构需要为其市值1000万人民币的A股投资组合做对冲，该投资组合业绩对标沪深300，当时的沪深300期货（IF）价格为4000点（每点300元），该投资组合的β值为1.2。请根据上述背景信息回答以下问题。\n\n【问题】要求1 该投资机构需要卖出的指数期货合约数量为（）。","options":["11张","8张","10张","9张"],"answer":"C","explain":"买卖期货合约的数量=β×现货总价值/(期货指数点×每点乘数)=1.2×1000万/120=10张。"},{"id":"advisor2-114","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】某投资机构需要为其市值1000万人民币的A股投资组合做对冲，该投资组合业绩对标沪深300，当时的沪深300期货（IF）价格为4000点（每点300元），该投资组合的β值为1.2。请根据上述背景信息回答以下问题。\n\n【问题】要求2 1个月后，该投资组合上涨了10%，沪深300指数期货的价格上涨到了4340点，忽略手续费和冲击成本，则该投资机构的盈亏状况为（）。","options":["盈利8万元","亏损2万元","亏损8万元","盈利2万元"],"answer":"B","explain":"投资组合盈利1000×10%=100万元；股指期货部分亏损=10×300×340=102万元。总体盈亏状况为100-102=-2万元，亏损2万元。"},{"id":"advisor2-115","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】某投资机构需要为其市值1000万人民币的A股投资组合做对冲，该投资组合业绩对标沪深300，当时的沪深300期货（IF）价格为4000点（每点300元），该投资组合的β值为1.2。请根据上述背景信息回答以下问题。\n\n【问题】要求3 该投资机构要保证利用股指期货进行套期保值成功，必须遵循的原则有（）。","options":["买卖方向对应的原则","品种相同原则","数量相等原则","月份相同或相近原则"],"answer":"ACD","explain":"套期保值操作的基本原则包括：买卖方向对应的原则、品种相同或相近原则、数量相等原则、月份相同或相近原则。"},{"id":"advisor2-116","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】小王和小吴同在一家企业工作。小王今年35岁，有很强的财富规划欲望，属于典型的风险爱好者，对于理财他追求高收益高回报，也敢于承担风险。小吴今年33岁，属于典型的风险厌恶者，对于理财，他追求稳妥、固定的收益回报，秉承安全第一的原则。两人最近都有打算要投资基金产品。请根据上述背景信息回答以下问题。\n\n【问题】要求1 从投资目标来看，小王应该会考虑投资（）产品。","options":["成长型基金","收入型基金","股票基金","私募基金"],"answer":"A","explain":"A选项正确，成长型基金追求的是基金资产的长期增值，符合小王的投资性格和投资目标。"},{"id":"advisor2-117","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】小王和小吴同在一家企业工作。小王今年35岁，有很强的财富规划欲望，属于典型的风险爱好者，对于理财他追求高收益高回报，也敢于承担风险。小吴今年33岁，属于典型的风险厌恶者，对于理财，他追求稳妥、固定的收益回报，秉承安全第一的原则。两人最近都有打算要投资基金产品。请根据上述背景信息回答以下问题。\n\n【问题】要求2 从投资目标来看，小吴应该会考虑投资（）产品。","options":["增长型基金","收入型基金","股票基金","私募基金"],"answer":"B","explain":"B选项正确，收入型基金主要投资于可带来现金收入的有价证券，以获取当期的最大收入为目的。"},{"id":"advisor2-118","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】小王和小吴同在一家企业工作。小王今年35岁，有很强的财富规划欲望，属于典型的风险爱好者，对于理财他追求高收益高回报，也敢于承担风险。小吴今年33岁，属于典型的风险厌恶者，对于理财，他追求稳妥、固定的收益回报，秉承安全第一的原则。两人最近都有打算要投资基金产品。请根据上述背景信息回答以下问题。\n\n【问题】要求3 股票基金以追求长期的资本增值为目标，比较适合长期投资。小王也看重了股票基金的这一特性，欲考虑投资股票基金。若小王真的投资股票基金，则他将面临（）。","options":["系统性风险","经营风险","管理运作风险","通货膨胀风险"],"answer":"ABC","explain":"股票基金所面临的投资风险主要包括系统性风险、经营风险以及管理运作风险。"},{"id":"advisor2-119","subject":"advisor","type":"案例","source":"2026.09 LC终极押题 · 押题卷二","q":"【资料】小王和小吴同在一家企业工作。小王今年35岁，有很强的财富规划欲望，属于典型的风险爱好者，对于理财他追求高收益高回报，也敢于承担风险。小吴今年33岁，属于典型的风险厌恶者，对于理财，他追求稳妥、固定的收益回报，秉承安全第一的原则。两人最近都有打算要投资基金产品。请根据上述背景信息回答以下问题。\n\n【问题】要求4 根据投资对象的不同，小吴应该考虑投资的基金产品是（）。","options":["股票基金","债券基金","货币市场基金","混合基金"],"answer":"C","explain":"C选项符合题意，货币市场基金具有风险低、流动性好的特点，是厌恶风险、对资产流动性和安全性要求较高的投资者进行短期投资和现金管理的理想工具。"}]}];
